@dataclass
class _Peer:
    node_id: str
    host_name: str
    listen_ip: str
    data_port: int
    segment_id: str

    sender_ids: Set[str] = field(default_factory=set)
    sender_kinds: Dict[str, str] = field(default_factory=dict)
    allow_protocols: Set[str] = field(default_factory=set)

    public_ok: bool = False
    gateway_ok: bool = False
    online: bool = True
    last_seen: float = field(default_factory=time.time)
    first_seen: float = field(default_factory=time.time)

    hello_count: int = 0
    rx_frames: int = 0
    tx_frames: int = 0
    rx_bytes: int = 0
    tx_bytes: int = 0
    last_frame_rx_ts: float = 0.0
    last_frame_tx_ts: float = 0.0
    last_ack_ts: float = 0.0

    discovery_port: int = 0
    last_hello_tx_ts: float = 0.0
    advertised_ip: str = ""
    last_hello_from_ip: str = ""
    last_data_from_ip: str = ""
    last_hello_from_port: int = 0
    last_data_from_port: int = 0
    last_discovery_rx_ts: float = 0.0
    last_discovery_tx_ts: float = 0.0
    last_discovery_success_ts: float = 0.0
    discovery_success_count: int = 0
    last_hello_id: str = ""

    # Multiple-path peer learning.  Never collapse a peer to one address only.
    candidate_ips: Dict[str, float] = field(default_factory=dict)
    candidate_data_ports: Dict[str, int] = field(default_factory=dict)
    confirmed_ips: Set[str] = field(default_factory=set)
    path_successes: Dict[str, int] = field(default_factory=dict)
    path_failures: Dict[str, int] = field(default_factory=dict)
    last_success_ip: str = ""
    last_success_port: int = 0

    # Addresses actually observed as the source of a valid HVRM datagram.
    # These are stronger than addresses merely advertised in a HELLO.
    observed_ips: Set[str] = field(default_factory=set)
    observed_data_ports: Dict[str, int] = field(default_factory=dict)
    last_observed_ip: str = ""
    last_observed_port: int = 0

    # Hybrid LAN + IP-passthrough metadata. A peer may legitimately expose
    # both a private address and a public passthrough address at the same time.
    address_roles: Dict[str, str] = field(default_factory=dict)
    private_ips: Set[str] = field(default_factory=set)
    public_ips: Set[str] = field(default_factory=set)
    passthrough_enabled: bool = False
    same_address_mode: bool = False
    preferred_private_ip: str = ""
    path_mode: str = "lan"


