class HyperVRouterManager:
    """
    Peer packet transport manager for Hyper-V / WinTun / WinDivert.

    Quieter rewrite:
      - does not mirror its own HVRM control traffic
      - discovery stays on discovery port
      - frame / ack traffic stays on data port
      - one wire variant only
      - one best target only
      - LAN/private targets only by default
      - no immediate "received" + later "processed" double-ack spam
      - sparse, state-oriented logging
      - early-drops local noise/broadcast/multicast from sidecar mirroring
      - bounded ingress/pending queues with drop-or-defer behavior
      - no inline queue-full send fallback on hot paths
      - explicitly ignores HVRM control/discovery packets seen on WireShark
    """

    MAGIC = "HVRM5"
    ACCEPT_MAGICS = {"HVRM4", "HVRM5", "HVRM6"}
    INBOUND_IFACE_NAME = "HyperVManager"

    DEFAULT_PROTOCOLS = {
        "ETHER", "IP", "IPv6", "TCP", "UDP", "ICMP", "ICMPv6", "ARP",
        "ESP", "AH", "GRE", "ISAKMP", "IKEv2", "RAW",
    }

    LOCAL_NOISE_UDP_PORTS = {
        137, 138, 1900, 3702, 5353, 5355, 546, 547,
    }

    HVRM_CONTROL_TYPES = {"hello", "hello_ack", "frame", "ack"}
    WIRESHARK_IFACE_NAMES = {
        "wireshark",
        "wire shark",
        "wire_shark",
        "wire-shark",
        "wireshark-process",
    }

    def __init__(
            self,
            router_logger,
            *,
            discovery_group: str = "239.255.77.77",
            discovery_port: int = 47771,
            data_port: int = 47772,
            heartbeat_sec: float = 15.0,
            peer_timeout_sec: float = 45.0,
            sender_failure_cooldown_sec: float = 5.0,
            dedupe_ttl_sec: float = 20.0,
            recent_cache_size: int = 8192,
            max_network_queue: int = 64,
            sender_queue_size: int = 32,
    ):
        self.router_logger = router_logger

        self.discovery_group = str(discovery_group)
        self.discovery_port = int(discovery_port)
        self.data_port = int(data_port)
        self.heartbeat_sec = max(10.0, float(heartbeat_sec))
        self.peer_timeout_sec = max(self.heartbeat_sec * 2.0, float(peer_timeout_sec))
        self.sender_failure_cooldown_sec = max(1.0, float(sender_failure_cooldown_sec))
        self.dedupe_ttl_sec = max(1.0, float(dedupe_ttl_sec))
        self.recent_cache_size = max(512, min(8192, int(recent_cache_size)))
        self.max_network_queue = max(32, min(256, int(max_network_queue)))
        self.sender_queue_size = max(16, min(128, int(sender_queue_size)))

        self.segment_id: str = "default"
        self.node_id: str = ""
        self.host_name: str = socket.gethostname()
        self.bind_ip: str = "0.0.0.0"

        # ``bind_ip`` remains the backward-compatible primary address. The
        # manager now also keeps every usable local IPv4 path so a public
        # passthrough host can communicate with ordinary 192.168/10/172 LAN
        # computers without sacrificing its public data path.
        self._primary_bind_ip: str = "0.0.0.0"
        self._explicit_transport_ips: Set[str] = set()
        self._local_transport_roles: Dict[str, str] = {}
        self._auto_detect_local_ips = True
        self._prefer_private_lan_paths = True
        self._hybrid_allow_passthrough_public = True
        self._hybrid_mode = False

        # Address safety and route selection.  AT&T IP Passthrough can assign
        # the real WAN address directly to the Windows LAN adapter.  In that
        # mode private 192.168.x peers are still reached through that adapter,
        # so arbitrary Hyper-V/WSL/APIPA addresses must never outrank it.
        self._allow_link_local_transport = False
        self._auto_detect_virtual_transport_ips = False
        self._prefer_observed_peer_paths = True
        self._suppress_local_address_as_peer_hint = True
        self._route_source_cache: Dict[str, Tuple[str, float]] = {}
        self._route_source_cache_ttl_sec = 5.0

        # IP-passthrough state is metadata for Hyper-V peer transport.  It does
        # not replace the Windows adapter/DHCP manager that owns netsh changes.
        self._ip_passthrough_config: Dict[str, Any] = {
            "enabled": False,
            "public_ip": "",
            "lan_ip": "",
            "gateway_ip": "",
            "subnet_mask": "",
            "prefix_length": None,
            "bind_ip": "",
            "wan_interface": "",
            "lan_interface": "",
            "same_address_mode": False,
            "advertise_public_ip": False,
            "private_lan_ips": [],
            "local_transport_ips": [],
            "address_roles": {},
            "hybrid_mode": False,
            "prefer_private_lan": True,
            "allow_same_segment_public": True,
            "public_ok": False,
            "gateway_ok": True,
            "restart_required": False,
        }

        self._lock = threading.RLock()
        self._sock_lock = threading.RLock()
        self._started = False
        self._stop_event = threading.Event()

        self._discovery_sock: Optional[socket.socket] = None
        self._discovery_tx_sock: Optional[socket.socket] = None
        self._data_sock: Optional[socket.socket] = None

        # One receive/send socket per local IPv4 address. The singular fields
        # above remain aliases for older startup/status code.
        self._discovery_tx_socks: Dict[str, socket.socket] = {}
        self._data_socks: Dict[str, socket.socket] = {}
        self._bound_data_ports_by_ip: Dict[str, int] = {}
        self._socket_source_ips: Dict[int, str] = {}
        self._bound_discovery_port: int = self.discovery_port
        self._bound_data_port: int = self.data_port

        self._hello_thread: Optional[threading.Thread] = None
        self._recv_thread: Optional[threading.Thread] = None
        self._health_thread: Optional[threading.Thread] = None
        self._net_thread: Optional[threading.Thread] = None
        self._router_thread: Optional[threading.Thread] = None
        self._socket_recovery_thread: Optional[threading.Thread] = None

        # Runtime socket repair. Adapter resets, ATT Air route changes, and
        # IP-passthrough renewals can invalidate every UDP handle without
        # stopping the process. A dedicated repair worker rebinds sockets while
        # packet/router workers continue running.
        self._socket_reopen_event = threading.Event()
        self._socket_reopen_lock = threading.RLock()
        self._socket_reopen_reason = ""
        self._socket_reopen_backoff_sec = 0.5
        self._socket_reopen_max_backoff_sec = 15.0
        self._socket_reopen_last_attempt = 0.0
        self._socket_reopen_count = 0
        self._socket_runtime_failures = 0
        self._route_probe_cache: Dict[Tuple[str, str], Tuple[bool, float, str]] = {}
        self._route_probe_cache_ttl_sec = 2.0

        self._senders: Dict[str, _LocalSender] = {}
        self._peers: Dict[str, _Peer] = {}

        self._net_tx_q: queue.Queue = queue.Queue(maxsize=self.max_network_queue)

        self._recent: Dict[str, float] = {}
        self._recent_order: Deque[Tuple[str, float]] = deque()

        self._pending_frames: Dict[str, Dict[str, Any]] = {}
        self._pending_lock = threading.RLock()
        self._frame_ack_timeout_sec = max(4.0, min(8.0, self.heartbeat_sec * 0.5))
        self._frame_retry_interval_sec = max(1.0, min(2.5, self.heartbeat_sec / 4.0))
        self._frame_retry_limit = 2
        self._pending_frame_cap = max(32, min(self.max_network_queue, 128))

        self._router_ingress_queue_size = max(16, min(self.max_network_queue, 64))
        self._router_ingress_q: queue.Queue = queue.Queue(maxsize=self._router_ingress_queue_size)
        self._router_ingress_retry_limit = 1
        self._router_ingress_retry_backoff_sec = 0.05
        self._router_ingress_retry_cap_sec = 0.10
        self._remote_ingress_breaker_threshold = max(4, self._router_ingress_queue_size // 4)
        self._remote_ingress_breaker_window_sec = 20.0
        self._remote_ingress_breaker_open_until = 0.0
        self._remote_ingress_queue_full_events: Deque[float] = deque()
        self._router_ingest_fn = None

        self._hyperv_managers: Dict[str, Any] = {}
        self._wintun_manager: Optional[Any] = None
        self._windivert_manager: Optional[Any] = None
        self._hostboundary_manager: Optional[Any] = None
        self._router_ref: Optional[Any] = None

        self._wintun_iface_name: str = "Nate's Tunnel"
        self._windivert_iface_names: Set[str] = {
            "WinDivert", "windivert", "WinDivertLoopback", "WinDivertBridge"
        }
        self._hyperv_iface_names: Set[str] = {"Hyper-V", "hyperv", "vEthernet"}

        self._manage_wintun_lifecycle = False
        self._manage_windivert_lifecycle = False

        self._allow_data_port_fallback = True
        self._allow_discovery_degraded_mode = False
        self._socket_close_wait_sec = 0.05

        self._wire_payload_compress_over = 1200
        # Keep the JSON/base64 envelope below the maximum UDP payload.
        self._wire_payload_max_bytes = 44 * 1024
        self._wire_message_max_bytes = 65507
        self._mirror_payload_soft_limit = 4096
        self._consumer_flow_bytes_per_window = 64 * 1024
        self._consumer_flow_packets_per_window = 48
        self._consumer_flow_window_sec = 2.0
        self._flow_activity: Dict[str, Dict[str, float]] = {}
        self._flow_activity_order: Deque[str] = deque()
        self._flow_activity_cap = 4096
        self._tls_allowlist_ports: Set[int] = set()
        self._tls_allowlist_hosts: Set[str] = set()

        self._direct_hello_every_sec = max(30.0, self.heartbeat_sec * 2.0)
        self._max_frame_wire_variants = 1
        self._max_ack_wire_variants = 1
        self._startup_hello_burst = 1
        self._startup_hello_gap_sec = 0.0
        self._last_hello_id: str = ""
        self._last_hello_ts: float = 0.0
        self._hello_challenges: Dict[str, float] = {}
        self._implicit_ack_grace_sec = max(0.35, min(1.25, self.heartbeat_sec))
        self._assume_delivery_on_peer_contact = False
        self._assume_delivery_on_online_peer = False

        # ACK return-path hardening for AT&T IP Passthrough. A LAN peer can
        # receive a frame sent from the passthrough public address while being
        # unable to unicast the ACK back to that public address (no NAT
        # hairpin/local-public route). Keep normal same-socket ACKs, but also
        # publish a tiny node-targeted ACK over the discovery multicast path
        # that is already proven to work between the peers.
        self._ack_discovery_fallback_enabled = True
        self._ack_discovery_redundant = True
        self._ack_discovery_target_limit = 4

        # quieter / LAN-scoped behavior
        self._allow_public_peer_data = False
        self._allow_public_discovery = False
        self._send_direct_hello = False
        self._send_global_broadcast = False
        self._send_subnet_broadcast = False
        # Keep several candidates and rotate them after missing ACKs.
        self._peer_target_limit = 3
        self._ack_target_limit = 2
        self._log_wire_messages = False
        self._control_payload_scan_limit = 2048

        # Wire hardening. Authentication remains optional for compatibility.
        self._wire_shared_secret: bytes = b""
        self._wire_require_auth = False
        self._wire_encrypt_payloads = False
        self._wire_encryption_key: bytes = b""
        self._wire_max_clock_skew_sec = max(90.0, self.peer_timeout_sec * 2.0)
        self._wire_require_known_peer_for_data = True
        self._allow_peer_ip_migration = True
        self._allow_cross_subnet_private_peer_hints = True
        self._peer_path_ttl_sec = max(180.0, self.peer_timeout_sec * 4.0)
        self._wire_rx_rate: Dict[str, Dict[str, float]] = {}
        self._wire_rx_rate_cap = 2048
        self._wire_control_per_sec = 48
        self._wire_frames_per_sec = 256
        self._recent_origin_frames: Dict[str, float] = {}
        self._recent_origin_order: Deque[Tuple[str, float]] = deque()

        self._recent_content_hashes: Dict[str, float] = {}
        self._recent_content_order: Deque[Tuple[str, float]] = deque()
        self._log_throttle: Dict[str, float] = {}
        self._stats: Dict[str, int] = {
            "peer_enqueued": 0,
            "peer_send_inline": 0,
            "peer_send_fail": 0,
            "peer_send_ok": 0,
            "peer_send_retry": 0,
            "peer_send_queue_full": 0,
            "peer_discovery_multicast": 0,
            "peer_discovery_broadcast": 0,
            "peer_discovery_rx": 0,
            "peer_discovery_reply": 0,
            "peer_discovery_success": 0,
            "remote_ingress_ok": 0,
            "remote_ingress_observed": 0,
            "remote_ingress_read": 0,
            "remote_ingress_decode_fail": 0,
            "remote_ingress_queued": 0,
            "remote_ingress_requeued": 0,
            "remote_ingress_failed": 0,
            "remote_ingress_queue_full": 0,
            "remote_ingress_busy": 0,
            "remote_ingress_breaker_drop": 0,
            "pending_pruned": 0,
            "local_sender_queue_full": 0,
            "noise_dropped": 0,
            "wireshark_hvrm_dropped": 0,
            "general_traffic_dropped": 0,
            "quic_dropped": 0,
            "tls_dropped": 0,
            "large_stream_dropped": 0,
            "consumer_rate_dropped": 0,
            "hybrid_private_send": 0,
            "hybrid_public_send": 0,
            "hybrid_path_failover": 0,
            "hybrid_discovery_tx": 0,
            "ack_direct_sent": 0,
            "ack_direct_failed": 0,
            "ack_fallback_queued": 0,
            "ack_discovery_sent": 0,
            "ack_discovery_received": 0,
            "ack_discovery_rejected": 0,
            "ack_received": 0,
            "ack_unmatched": 0,
        }

    def _apply_pressure_mode(self) -> None:
        qfull = int(self._stats.get("peer_send_queue_full", 0))
        ingress_full = int(self._stats.get("remote_ingress_queue_full", 0))
        ingress_busy = int(self._stats.get("remote_ingress_busy", 0))

        pressure = qfull + ingress_full + ingress_busy

        if pressure >= 20:
            self._mirror_payload_soft_limit = 2048
            self._consumer_flow_bytes_per_window = 32 * 1024
            self._consumer_flow_packets_per_window = 24
        elif pressure >= 8:
            self._mirror_payload_soft_limit = 4096
            self._consumer_flow_bytes_per_window = 48 * 1024
            self._consumer_flow_packets_per_window = 36
        else:
            self._mirror_payload_soft_limit = 4096
            self._consumer_flow_bytes_per_window = 64 * 1024
            self._consumer_flow_packets_per_window = 48

    def _remember_recent_value(
            self,
            store: Dict[str, float],
            order: Deque[Tuple[str, float]],
            value: str,
            ttl_sec: Optional[float] = None,
    ) -> bool:
        key = str(value or "").strip()
        if not key:
            return False

        now = time.time()
        expiry = float(store.get(key, 0.0) or 0.0)
        if expiry > now:
            return True

        exp = now + float(ttl_sec or self.dedupe_ttl_sec)
        store[key] = exp
        order.append((key, exp))

        hard_cap = max(512, int(self.recent_cache_size))
        while len(order) > hard_cap:
            old_key, old_exp = order.popleft()
            cur = float(store.get(old_key, 0.0) or 0.0)
            if cur <= now or cur == old_exp:
                store.pop(old_key, None)

        return False

    def _prune_recent_store(
            self,
            store: Dict[str, float],
            order: Deque[Tuple[str, float]],
    ) -> None:
        now = time.time()
        while order:
            key, exp = order[0]
            cur = float(store.get(key, 0.0) or 0.0)
            if cur > now and cur == exp:
                break
            order.popleft()
            if cur <= now:
                store.pop(key, None)

    def configure(
            self,
            *,
            segment_id: str,
            bind_ip: str = "0.0.0.0",
            node_id: Optional[str] = None,
            additional_bind_ips: Optional[Any] = None,
            lan_bind_ips: Optional[Any] = None,
            auto_detect_local_ips: bool = True,
    ) -> None:
        """
        Configure the peer-transport identity and every usable local IPv4 path.

        ``bind_ip`` is still the primary/backward-compatible address. For a
        passthrough computer, pass its public address as ``bind_ip`` and pass
        one or more private addresses through ``lan_bind_ips``. When
        ``auto_detect_local_ips`` is true, assigned private addresses are also
        discovered automatically.
        """
        segment = str(segment_id or "default").strip() or "default"
        requested_bind = str(bind_ip or "").strip()
        requested_node = str(node_id or f"{self.host_name}-{uuid.getnode():012x}").strip()

        if not self._is_valid_bind_ip(requested_bind):
            raise ValueError(
                "HyperVRouterManager requires a concrete, usable IPv4 bind_ip; "
                "0.0.0.0, loopback, multicast, and broadcast addresses are not allowed"
            )

        explicit: List[str] = []
        for value in self._coerce_ip_list(additional_bind_ips) + self._coerce_ip_list(lan_bind_ips):
            ip = self._sanitize_peer_ip(value)
            if ip and ip not in explicit:
                explicit.append(ip)

        candidates: List[str] = [requested_bind]
        candidates.extend(explicit)
        if bool(auto_detect_local_ips):
            candidates.extend(self._discover_local_ipv4_addresses())

        local_ips = self._dedupe_usable_ips(candidates)
        if requested_bind not in local_ips:
            local_ips.insert(0, requested_bind)

        roles = self._build_local_address_roles(
            local_ips,
            public_ip="",
            private_lan_ips=self._coerce_ip_list(lan_bind_ips),
            primary_ip=requested_bind,
        )

        with self._lock:
            old_ips = set(self._local_transport_roles)
            new_ips = set(local_ips)
            if self._started and (requested_bind != self.bind_ip or old_ips != new_ips):
                raise RuntimeError(
                    "HyperVRouterManager.configure() cannot change transport addresses while started; "
                    "stop the manager, configure it, then start it again"
                )

            self.segment_id = segment
            self.bind_ip = requested_bind
            self._primary_bind_ip = requested_bind
            self.node_id = requested_node
            self._auto_detect_local_ips = bool(auto_detect_local_ips)
            self._explicit_transport_ips = set(explicit)
            self._local_transport_roles = roles
            self._hybrid_mode = self._has_hybrid_local_paths()

            cfg = dict(self._ip_passthrough_config)
            cfg["bind_ip"] = requested_bind
            cfg["local_transport_ips"] = list(self._ordered_local_transport_ips())
            cfg["address_roles"] = dict(self._local_transport_roles)
            cfg["hybrid_mode"] = bool(self._hybrid_mode)
            cfg["restart_required"] = False
            self._ip_passthrough_config = cfg

        self._log_evt(
            "config",
            f"configured segment='{self.segment_id}' node='{self.node_id}' primary='{self.bind_ip}' "
            f"paths={self._ordered_local_transport_ips()} hybrid={int(self._hybrid_mode)}",
            ["🧠", "📝", "🌐"],
        )

    def configure_ip_passthrough(self, *args, **kwargs) -> Dict[str, Any]:
        """
        Record IP-passthrough state without excluding normal private-LAN peers.

        Supported hybrid example::

            manager.configure_ip_passthrough(
                public_ip="203.0.113.10",
                bind_ip="203.0.113.10",
                private_lan_ips=["192.168.1.20"],
                gateway_ip="192.168.1.254",
                wan_interface="Ethernet",
                lan_interface="Ethernet",
                enabled=True,
            )

        Older positional and alias forms remain accepted. This method records
        transport metadata only; it does not run netsh or change DHCP/NAT.
        """
        options: Dict[str, Any] = dict(kwargs)
        positional_names = (
            "public_ip",
            "lan_ip",
            "gateway_ip",
            "subnet_mask",
            "wan_interface",
            "lan_interface",
        )
        if len(args) > len(positional_names):
            raise TypeError(
                "configure_ip_passthrough() accepts at most 6 positional arguments: "
                "public_ip, lan_ip, gateway_ip, subnet_mask, wan_interface, lan_interface"
            )
        for name, value in zip(positional_names, args):
            options.setdefault(name, value)

        def _pick(*names: str, default: Any = "") -> Any:
            for name in names:
                if name in options and options[name] is not None:
                    value = options[name]
                    if isinstance(value, str):
                        value = value.strip()
                    if value != "":
                        return value
            return default

        enabled = self._coerce_bool(_pick("enabled", "ip_passthrough", "passthrough_enabled", default=True), True)
        strict = self._coerce_bool(_pick("strict", "validate_strictly", default=False), False)
        auto_detect = self._coerce_bool(_pick("auto_detect_local_ips", "discover_local_ips", default=True), True)

        public_ip = self._sanitize_peer_ip(_pick(
            "public_ip", "wan_ip", "external_ip", "static_ip", "passthrough_ip"
        ))
        lan_ip = self._sanitize_peer_ip(_pick(
            "lan_ip", "host_ip", "local_ip", "inside_ip", "router_ip", "client_ip"
        ))
        gateway_ip = self._sanitize_peer_ip(_pick(
            "gateway_ip", "gateway", "default_gateway", "wan_gateway", "public_gateway"
        ))
        requested_bind_ip = self._sanitize_peer_ip(_pick(
            "bind_ip", "transport_bind_ip", "listen_ip", "source_ip"
        ))
        subnet_mask = str(_pick("subnet_mask", "netmask", "mask") or "").strip()
        wan_interface = str(_pick(
            "wan_interface", "out_interface", "out_iface", "upstream_interface", "upstream_iface"
        ) or "").strip()
        lan_interface = str(_pick(
            "lan_interface", "in_interface", "in_iface", "downstream_interface", "downstream_iface"
        ) or "").strip()

        private_values: List[str] = []
        for key in (
                "private_lan_ips", "private_lan_ip", "lan_bind_ips", "secondary_lan_ips",
                "local_private_ips", "additional_bind_ips", "transport_ips",
        ):
            private_values.extend(self._coerce_ip_list(options.get(key)))
        if lan_ip and self._is_private_ipv4(lan_ip):
            private_values.append(lan_ip)
        private_lan_ips = [ip for ip in self._dedupe_usable_ips(private_values) if self._is_private_ipv4(ip)]

        advertise_public_ip = self._coerce_bool(
            _pick("advertise_public_ip", "public_reachable", default=bool(enabled and public_ip)),
            bool(enabled and public_ip),
        )
        prefer_private_lan = self._coerce_bool(
            _pick("prefer_private_lan", "prefer_private_paths", default=True), True
        )
        allow_same_segment_public = self._coerce_bool(
            _pick("allow_same_segment_public", "allow_passthrough_public", default=True), True
        )

        prefix_raw = _pick("prefix_length", "prefix", "cidr_prefix", default=None)
        prefix_length: Optional[int] = None
        if prefix_raw not in (None, ""):
            try:
                prefix_length = int(prefix_raw)
            except (TypeError, ValueError):
                raise ValueError(f"invalid IPv4 prefix length: {prefix_raw!r}")
            if not 0 <= prefix_length <= 32:
                raise ValueError(f"IPv4 prefix length must be from 0 through 32, got {prefix_length}")

        if subnet_mask:
            mask_prefix = self._ipv4_mask_prefix(subnet_mask)
            if mask_prefix is None:
                raise ValueError(f"invalid contiguous IPv4 subnet mask: {subnet_mask!r}")
            if prefix_length is None:
                prefix_length = mask_prefix
            elif prefix_length != mask_prefix:
                raise ValueError(
                    f"subnet_mask {subnet_mask!r} is /{mask_prefix}, but prefix_length={prefix_length}"
                )
        elif prefix_length is not None:
            subnet_mask = self._ipv4_prefix_mask(prefix_length)

        current_bind = self._sanitize_peer_ip(self.bind_ip)
        selected_bind_ip = next((ip for ip in (
            requested_bind_ip, public_ip, lan_ip, current_bind
        ) if self._is_valid_bind_ip(ip)), "")
        if enabled and strict and not selected_bind_ip:
            raise ValueError(
                "IP passthrough is enabled but no usable local bind address was supplied; "
                "provide bind_ip, public_ip, lan_ip, or call configure() first"
            )

        local_candidates: List[str] = []
        local_candidates.extend([selected_bind_ip, current_bind, public_ip, lan_ip])
        local_candidates.extend(private_lan_ips)
        local_candidates.extend(self._explicit_transport_ips)
        if auto_detect:
            local_candidates.extend(self._discover_local_ipv4_addresses())
        local_ips = self._dedupe_usable_ips(local_candidates)
        if selected_bind_ip and selected_bind_ip not in local_ips:
            local_ips.insert(0, selected_bind_ip)

        roles = self._build_local_address_roles(
            local_ips,
            public_ip=public_ip,
            private_lan_ips=private_lan_ips,
            primary_ip=selected_bind_ip or current_bind,
        )
        actual_private_ips = [ip for ip in local_ips if self._is_private_ipv4(ip)]
        hybrid_mode = bool(enabled and public_ip and actual_private_ips)
        configured_ips = [ip for ip in (public_ip, lan_ip, gateway_ip) if ip]
        same_address_mode = bool(
            enabled
            and public_ip
            and selected_bind_ip == public_ip
            and (not lan_ip or lan_ip == public_ip)
            and (not gateway_ip or gateway_ip == public_ip)
            and not actual_private_ips
        ) or (len(configured_ips) >= 2 and len(set(configured_ips)) == 1)
        if same_address_mode and selected_bind_ip:
            roles[selected_bind_ip] = "primary-passthrough-lan-wan"

        requested_public_ok = _pick("public_ok", "has_public_ip", default=None)
        requested_gateway_ok = _pick("gateway_ok", "can_gateway", "gateway_ready", default=None)
        public_ok = (
            self._coerce_bool(requested_public_ok, False)
            if requested_public_ok is not None
            else bool(enabled and public_ip)
        )
        gateway_ok = (
            self._coerce_bool(requested_gateway_ok, False)
            if requested_gateway_ok is not None
            else bool(enabled and (gateway_ip or selected_bind_ip))
        )

        with self._lock:
            old_bind = self._sanitize_peer_ip(self.bind_ip)
            old_ips = set(self._local_transport_roles)
            new_ips = set(local_ips)
            restart_required = bool(
                self._started and (
                    (selected_bind_ip and selected_bind_ip != old_bind)
                    or new_ips != old_ips
                )
            )

            if selected_bind_ip and not self._started:
                self.bind_ip = selected_bind_ip
                self._primary_bind_ip = selected_bind_ip

            if not self._started:
                self._local_transport_roles = roles
                self._explicit_transport_ips.update(private_lan_ips)

            self._prefer_private_lan_paths = bool(prefer_private_lan)
            self._hybrid_allow_passthrough_public = bool(allow_same_segment_public)
            self._hybrid_mode = bool(hybrid_mode)

            self._ip_passthrough_config = {
                "enabled": bool(enabled),
                "public_ip": public_ip,
                "lan_ip": lan_ip,
                "gateway_ip": gateway_ip,
                "subnet_mask": subnet_mask,
                "prefix_length": prefix_length,
                "bind_ip": selected_bind_ip or old_bind,
                "wan_interface": wan_interface,
                "lan_interface": lan_interface,
                "same_address_mode": same_address_mode,
                "advertise_public_ip": advertise_public_ip,
                "private_lan_ips": list(actual_private_ips),
                "local_transport_ips": list(local_ips),
                "address_roles": dict(roles),
                "hybrid_mode": hybrid_mode,
                "prefer_private_lan": bool(prefer_private_lan),
                "allow_same_segment_public": bool(allow_same_segment_public),
                "public_ok": public_ok if enabled else False,
                "gateway_ok": gateway_ok if enabled else True,
                "restart_required": restart_required,
            }
            result = dict(self._ip_passthrough_config)

        mode = "hybrid" if hybrid_mode else ("same-address" if same_address_mode else "passthrough")
        self._log_evt(
            "ip-passthrough",
            f"configured enabled={int(enabled)} mode={mode} public={public_ip or '-'} "
            f"private={actual_private_ips or '-'} primary={result.get('bind_ip') or '-'} "
            f"paths={local_ips} restart_required={int(restart_required)}",
            ["🌐", "🛣️", "🏠", "📝"],
        )

        if restart_required:
            self._log_evt(
                "ip-passthrough",
                "transport address set changed while running; stop and restart HyperVRouterManager "
                "so public and private UDP sockets can be rebound together",
                ["⚠️", "🔄", "🧯"],
            )
        return result

    def get_ip_passthrough_status(self) -> Dict[str, Any]:
        """Return passthrough configuration plus the currently bound paths."""
        with self._lock:
            result = dict(self._ip_passthrough_config)
            result["local_transport_ips"] = list(self._ordered_local_transport_ips())
            result["address_roles"] = dict(self._local_transport_roles)
            result["hybrid_mode"] = bool(self._hybrid_mode)
        with self._sock_lock:
            result["bound_data_paths"] = dict(self._bound_data_ports_by_ip)
            result["bound_discovery_paths"] = sorted(self._discovery_tx_socks)
        return result

    def _passthrough_wire_flags(self) -> Tuple[bool, bool]:
        with self._lock:
            cfg = dict(self._ip_passthrough_config)
        return (
            bool(cfg.get("public_ok", False)),
            bool(cfg.get("gateway_ok", True)),
        )

    def _passthrough_address_hints(self, advertised_ip: str = "") -> List[str]:
        with self._lock:
            cfg = dict(self._ip_passthrough_config)

        candidates: List[str] = [str(advertised_ip or "").strip()]
        candidates.extend(self._ordered_local_transport_ips())
        candidates.extend(self._coerce_ip_list(cfg.get("private_lan_ips")))
        candidates.extend([
            str(cfg.get("lan_ip") or "").strip(),
            str(cfg.get("bind_ip") or "").strip(),
        ])
        if bool(cfg.get("advertise_public_ip", False)) or bool(cfg.get("same_address_mode", False)):
            candidates.append(str(cfg.get("public_ip") or "").strip())

        return self._dedupe_usable_ips(candidates)[:12]

    def _ipv4_mask_prefix(self, mask: Any) -> Optional[int]:
        parts = self._ipv4_parts(mask)
        if parts is None:
            return None
        value = (
            (parts[0] << 24)
            | (parts[1] << 16)
            | (parts[2] << 8)
            | parts[3]
        )
        bits = f"{value:032b}"
        if "01" in bits:
            return None
        return bits.count("1")

    def _ipv4_prefix_mask(self, prefix_length: int) -> str:
        prefix = int(prefix_length)
        if not 0 <= prefix <= 32:
            raise ValueError(f"IPv4 prefix length must be from 0 through 32, got {prefix}")
        value = ((0xFFFFFFFF << (32 - prefix)) & 0xFFFFFFFF) if prefix else 0
        return ".".join(str((value >> shift) & 0xFF) for shift in (24, 16, 8, 0))

    def register_hyperv_backend(
            self,
            sender_id: str,
            backend: Any,
            *,
            allow_protocols: Optional[Set[str]] = None,
            enabled: bool = True,
            start_backend: bool = False,
    ) -> None:
        send_fn = getattr(backend, "send_packet", None)
        if not callable(send_fn):
            raise ValueError(f"Hyper-V backend '{sender_id}' must expose send_packet(packet)")

        self._maybe_capture_router_ref(backend)

        state = _LocalSender(
            sender_id=str(sender_id),
            kind="hyperv",
            send_callable=send_fn,
            allow_protocols=set(allow_protocols or self.DEFAULT_PROTOCOLS),
            enabled=bool(enabled),
            start_fn=getattr(backend, "start", None) if start_backend else None,
            stop_fn=(getattr(backend, "teardown", None) or getattr(backend, "stop", None)) if start_backend else None,
            started_by_manager=bool(start_backend),
            send_q=queue.Queue(maxsize=self.sender_queue_size),
        )

        with self._lock:
            self._senders[state.sender_id] = state
            self._hyperv_managers[state.sender_id] = backend
            started = self._started

        if started:
            self._start_sender_worker(state)

        self._log_evt(
            "sender",
            f"registered Hyper-V backend '{state.sender_id}' protocols={sorted(state.allow_protocols)}",
            ["📦", "🧩"],
        )

    def attach_wintun_manager(
            self,
            wintun_manager: Any,
            *,
            sender_id: str = "wintun-local",
            allow_protocols: Optional[Set[str]] = None,
            start_manager: bool = False,
            expose_as_sender: bool = False,
            wintun_send: Optional[Callable[[Any], bool]] = None,
            iface_name: Optional[str] = None,
    ) -> None:
        self._wintun_manager = wintun_manager
        self._manage_wintun_lifecycle = bool(start_manager)
        self._wintun_iface_name = str(
            iface_name or getattr(wintun_manager, "VIRTUAL_IFACE_NAME", "Nate's Tunnel")
        )
        self._maybe_capture_router_ref(wintun_manager)

        self._log_evt("attach", f"attached WinTunManager iface='{self._wintun_iface_name}'", ["🪟", "🛜"])

        if expose_as_sender:
            if not callable(wintun_send):
                raise ValueError("expose_as_sender=True requires wintun_send(packet)")
            self._register_generic_sender(
                sender_id=sender_id,
                kind="wintun",
                send_callable=wintun_send,
                allow_protocols=allow_protocols,
                start_fn=getattr(wintun_manager, "start", None) if start_manager else None,
                stop_fn=getattr(wintun_manager, "stop", None),
                enabled=True,
            )

    def attach_windivert_manager(
            self,
            windivert_manager: Any,
            *,
            sender_id: str = "windivert-local",
            allow_protocols: Optional[Set[str]] = None,
            start_manager: bool = False,
            expose_as_sender: bool = False,
            windivert_send: Optional[Callable[[Any], bool]] = None,
            iface_names: Optional[Set[str]] = None,
    ) -> None:
        self._windivert_manager = windivert_manager
        self._manage_windivert_lifecycle = bool(start_manager)
        self._maybe_capture_router_ref(windivert_manager)

        if iface_names:
            self._windivert_iface_names = {str(x) for x in iface_names if x}

        self._log_evt("attach", "attached WinDivertManager", ["🪟", "🧲", "📥"])

        if expose_as_sender:
            if not callable(windivert_send):
                raise ValueError("expose_as_sender=True requires windivert_send(packet)")
            self._register_generic_sender(
                sender_id=sender_id,
                kind="windivert",
                send_callable=windivert_send,
                allow_protocols=allow_protocols,
                start_fn=getattr(windivert_manager, "start", None) if start_manager else None,
                stop_fn=getattr(windivert_manager, "stop", None),
                enabled=True,
            )

    def attach_hostboundary_manager(self, hostboundary_manager: Any) -> None:
        self._hostboundary_manager = hostboundary_manager
        self._maybe_capture_router_ref(hostboundary_manager)
        self._log_evt("attach", "attached HostConnectivityBoundaryManager", ["🛡️", "🤝"])

    def _register_generic_sender(
            self,
            *,
            sender_id: str,
            kind: str,
            send_callable: Callable[[Any], bool],
            allow_protocols: Optional[Set[str]],
            start_fn: Optional[Callable[[], Any]],
            stop_fn: Optional[Callable[[], Any]],
            enabled: bool,
    ) -> None:
        state = _LocalSender(
            sender_id=str(sender_id),
            kind=str(kind),
            send_callable=send_callable,
            allow_protocols=set(allow_protocols or self.DEFAULT_PROTOCOLS),
            enabled=bool(enabled),
            start_fn=start_fn,
            stop_fn=stop_fn,
            send_q=queue.Queue(maxsize=self.sender_queue_size),
        )

        with self._lock:
            self._senders[state.sender_id] = state
            started = self._started

        if started:
            self._start_sender_worker(state)

        self._log_evt("sender", f"registered sender '{state.sender_id}' kind={state.kind}", ["📦", "🧩"])

    def _resolve_router_ingest_callable(self):
        router = self._resolve_router()
        if router is None:
            return None
        for fn_name in ("process_packet", "handle_packet", "_process_packet"):
            fn = getattr(router, fn_name, None)
            if callable(fn):
                return fn
        return None

    # ---------------------------------------------------------
    # lifecycle
    # ---------------------------------------------------------

    def start(self) -> None:
        with self._lock:
            if self._started:
                return
            self._started = True
            self._stop_event.clear()

        if self._wintun_manager is not None and self._manage_wintun_lifecycle:
            try:
                self._wintun_manager.start()
                self._log_evt("lifecycle", "started WinTunManager", ["▶️", "🪟"])
            except Exception as e:
                self._log_evt(
                    "lifecycle",
                    f"failed to start WinTunManager: {type(e).__name__}: {e}",
                    ["⚠️", "🧯"],
                )

        if self._windivert_manager is not None and self._manage_windivert_lifecycle:
            try:
                self._windivert_manager.start()
                self._log_evt("lifecycle", "started WinDivertManager", ["▶️", "🧲"])
            except Exception as e:
                self._log_evt(
                    "lifecycle",
                    f"failed to start WinDivertManager: {type(e).__name__}: {e}",
                    ["⚠️", "🧯"],
                )

        try:
            self._open_sockets()
        except Exception as e:
            self._close_sockets()
            self._request_socket_reopen(f"startup:{type(e).__name__}:{e}")
            self._log_sparse(
                "socket-startup-degraded",
                "socket",
                f"transport sockets not ready at startup; continuing local-only and retrying: "
                f"{type(e).__name__}: {e}",
                ["⚠️", "🧯", "🔄"],
                every=2.0,
            )

        with self._lock:
            for state in self._senders.values():
                self._start_sender_worker(state)

        self._hello_thread = threading.Thread(target=self._hello_loop, name="HyperVRouterHello", daemon=True)
        self._recv_thread = threading.Thread(target=self._recv_loop, name="HyperVRouterRecv", daemon=True)
        self._health_thread = threading.Thread(target=self._health_loop, name="HyperVRouterHealth", daemon=True)
        self._net_thread = threading.Thread(target=self._network_sender_loop, name="HyperVRouterWireSend", daemon=True)
        self._router_thread = threading.Thread(target=self._router_ingress_loop, name="HyperVRouterIngress",
                                               daemon=True)
        self._socket_recovery_thread = threading.Thread(
            target=self._socket_recovery_loop,
            name="HyperVRouterSocketRecovery",
            daemon=True,
        )

        self._hello_thread.start()
        self._recv_thread.start()
        self._health_thread.start()
        self._net_thread.start()
        self._router_thread.start()
        self._socket_recovery_thread.start()

        if self._router_runtime_ready():
            try:
                self._send_hello(startup=True)
            except Exception as e:
                self._log_sparse(
                    "startup-hello",
                    "peer",
                    f"initial discovery send failed: {type(e).__name__}: {e}",
                    ["⚠️", "📡", "🧯"],
                    every=2.0,
                )
        else:
            self._log_evt(
                "lifecycle",
                "initial discovery deferred until router routes are ready",
                ["⏳", "📡", "🧭"],
            )
        self._router_ingest_fn = self._resolve_router_ingest_callable()
        if self._data_sock is None:
            self._log_evt("lifecycle", "started in local-only mode; remote transport disabled", ["🧯", "🏠"])
        elif self._discovery_sock is None and self._discovery_tx_sock is not None:
            self._log_evt(
                "lifecycle",
                "started with discovery receive disabled but discovery send active",
                ["⚠️", "📡", "↪️"],
            )
        elif self._discovery_sock is None:
            self._log_evt("lifecycle", "started with discovery disabled; direct peers only", ["⚠️", "📡"])
        else:
            self._log_evt("lifecycle", "HyperVRouterManager started", ["🚀", "🌐"])

    def notify_network_ready(self) -> None:
        """Kick discovery only after the owning router installed its routes."""
        if self._stop_event.is_set() or not self._started:
            return
        if not self._router_runtime_ready():
            return
        with self._sock_lock:
            missing = not self._data_socks or not self._discovery_tx_socks
        if missing:
            self._request_socket_reopen("router-runtime-ready")
        try:
            self._send_hello(startup=True)
        except Exception as exc:
            if self._is_transport_socket_error(exc):
                self._request_socket_reopen(
                    f"ready-hello:{self._transport_socket_error_code(exc)}"
                )
            self._log_sparse(
                "ready-hello",
                "peer",
                f"network-ready discovery deferred: {type(exc).__name__}: {exc}",
                ["⚠️", "📡", "🔄"],
                every=2.0,
            )

    def stop(self) -> None:
        with self._lock:
            if not self._started:
                return
            self._started = False
            self._stop_event.set()
            self._socket_reopen_event.set()

        self._close_sockets()

        if self._windivert_manager is not None and self._manage_windivert_lifecycle:
            try:
                self._windivert_manager.stop()
                self._log_evt("lifecycle", "stopped WinDivertManager", ["🛑", "🧲"])
            except Exception as e:
                self._log_evt(
                    "lifecycle",
                    f"failed to stop WinDivertManager: {type(e).__name__}: {e}",
                    ["⚠️", "🧯"],
                )

        if self._wintun_manager is not None and self._manage_wintun_lifecycle:
            try:
                self._wintun_manager.stop()
                self._log_evt("lifecycle", "stopped WinTunManager", ["🛑", "🪟"])
            except Exception as e:
                self._log_evt(
                    "lifecycle",
                    f"failed to stop WinTunManager: {type(e).__name__}: {e}",
                    ["⚠️", "🧯"],
                )

        try:
            self._router_ingress_q.put_nowait(None)
        except Exception:
            pass

        for t in (
                self._hello_thread, self._recv_thread, self._health_thread,
                self._net_thread, self._router_thread, self._socket_recovery_thread,
        ):
            if t and t.is_alive():
                t.join(timeout=3.0)

        self._hello_thread = None
        self._recv_thread = None
        self._health_thread = None
        self._net_thread = None
        self._router_thread = None
        self._socket_recovery_thread = None
        self._socket_reopen_event.clear()

        with self._lock:
            senders = list(self._senders.values())

        for state in senders:
            try:
                state.send_q.put_nowait(None)
            except Exception:
                pass

        try:
            self._net_tx_q.put_nowait(None)
        except Exception:
            pass

        for state in senders:
            if state.worker and state.worker.is_alive():
                state.worker.join(timeout=3.0)
            state.worker = None

        for state in senders:
            self._maybe_stop_sender(state)

        with self._pending_lock:
            self._pending_frames.clear()

        self._log_evt("lifecycle", "HyperVRouterManager stopped", ["🌙", "🛑"])

    # ---------------------------------------------------------
    # router hot path
    # ---------------------------------------------------------

    def handle_packet(self, packet, inbound_iface: str) -> bool:
        """
        Sidecar mirror only.

        Important contract:
        - never becomes the routing owner
        - never blocks or consumes the router's normal packet flow
        - never drops local traffic because mirroring failed
        - returns False for local/router-origin packets so upstream routing continues
        - only performs best-effort peer mirroring as a side effect
        """
        try:
            if not self._started or self._stop_event.is_set():
                return False

            if packet is None:
                return False

            iface_name = str(inbound_iface or "").strip()
            if not iface_name:
                return False

            if iface_name == self.INBOUND_IFACE_NAME:
                return False

            raw = self._packet_to_bytes(packet)
            if not raw:
                return False

            if self._should_drop_wireshark_hvrm(packet, raw, iface_name):
                self._stats["wireshark_hvrm_dropped"] = int(self._stats.get("wireshark_hvrm_dropped", 0)) + 1
                return False

            _ = self._consult_hostboundary(packet, iface_name)

            protocol_tag = self._classify_protocol(packet)
            if protocol_tag is None:
                return False

            if self._should_drop_sidecar_noise(packet, protocol_tag):
                self._stats["noise_dropped"] = int(self._stats.get("noise_dropped", 0)) + 1
                return False

            if self._is_hvrm_control_packet(packet, raw):
                return False

            if len(raw) > self._wire_payload_max_bytes:
                self._stats["large_stream_dropped"] = int(self._stats.get("large_stream_dropped", 0)) + 1
                self._log_sparse(
                    f"wire-too-large:{protocol_tag}",
                    "route",
                    f"wire frame too large to mirror protocol={protocol_tag} iface={iface_name} len={len(raw)}",
                    ["⚠️", "📦", "📏"],
                    every=3.0,
                )
                return False

            drop_reason = self._general_traffic_drop_reason(packet, protocol_tag, raw, iface_name)
            if drop_reason:
                self._stats["general_traffic_dropped"] = int(self._stats.get("general_traffic_dropped", 0)) + 1
                if drop_reason == "quic":
                    self._stats["quic_dropped"] = int(self._stats.get("quic_dropped", 0)) + 1
                elif drop_reason == "tls":
                    self._stats["tls_dropped"] = int(self._stats.get("tls_dropped", 0)) + 1
                elif drop_reason in {"large_stream", "large_payload_stream"}:
                    self._stats["large_stream_dropped"] = int(self._stats.get("large_stream_dropped", 0)) + 1
                elif drop_reason == "consumer_rate":
                    self._stats["consumer_rate_dropped"] = int(self._stats.get("consumer_rate_dropped", 0)) + 1
                self._log_sparse(
                    f"general-drop:{drop_reason}:{iface_name}:{protocol_tag}",
                    "route",
                    f"sidecar mirror dropped reason={drop_reason} iface={iface_name} proto={protocol_tag} len={len(raw)}",
                    ["🛑", "📦", "🌐"],
                    every=2.0,
                )
                return False

            ingress_kind = self._infer_ingress_kind(iface_name)

            try:
                fp = self._fingerprint(raw, iface_name, protocol_tag, prefix=(ingress_kind or "pkt"))
                if self._seen_recently(fp):
                    return False
            except Exception:
                pass

            exclude_kind = ingress_kind if ingress_kind in {"wintun", "windivert", "hyperv", "wireshark"} else None
            endpoints = self._collect_candidate_endpoints(protocol_tag, exclude_kind=exclude_kind)
            if not endpoints:
                return False

            chosen = self._choose_endpoint(packet, iface_name, protocol_tag, raw, endpoints)
            if chosen is None:
                return False

            _, endpoint = chosen
            dst_node_id = getattr(endpoint, "node_id", "")
            dst_sender_id = getattr(endpoint, "sender_id", "")

            ok = self._enqueue_remote(
                protocol_tag=protocol_tag,
                raw=raw,
                inbound_iface=iface_name,
                dst_node_id=dst_node_id,
                dst_sender_id=dst_sender_id,
            )
            if ok:
                self._stats["peer_enqueued"] += 1

            return False

        except Exception as e:
            self._log_sparse(
                "route-exception",
                "route",
                f"handle_packet error iface={inbound_iface}: {type(e).__name__}: {e}",
                ["⚠️", "🧩", "🧯"],
                every=2.0,
            )
            return False

    def _consult_hostboundary(self, packet, inbound_iface: str) -> str:
        mgr = self._hostboundary_manager
        if mgr is None:
            return "observe"

        try:
            decision = mgr.inspect_packet(packet, inbound_iface)
            action = str(getattr(decision, "action", "observe") or "observe").lower()
            if action in {"bypass", "process", "observe"}:
                return "observe" if action == "bypass" else action
        except Exception:
            pass

        try:
            _ = bool(mgr.should_bypass_router(packet, inbound_iface))
        except Exception:
            pass

        return "observe"

    def _normalize_iface_token(self, iface_name: Any) -> str:
        txt = str(iface_name or "").strip().lower()
        txt = txt.replace("_", " ").replace("-", " ")
        txt = " ".join(txt.split())
        return txt

    def _is_wireshark_iface(self, inbound_iface: str) -> bool:
        return self._normalize_iface_token(inbound_iface) in self.WIRESHARK_IFACE_NAMES

    def _infer_ingress_kind(self, inbound_iface: str) -> Optional[str]:
        iface = self._normalize_iface_token(inbound_iface)
        if not iface:
            return None

        if iface in self.WIRESHARK_IFACE_NAMES:
            return "wireshark"

        if self._wintun_iface_name and iface == self._normalize_iface_token(self._wintun_iface_name):
            return "wintun"

        for name in self._windivert_iface_names:
            if iface == self._normalize_iface_token(name):
                return "windivert"

        for token in self._hyperv_iface_names:
            token_l = self._normalize_iface_token(token)
            if token_l and token_l in iface:
                return "hyperv"

        return None

    # ---------------------------------------------------------
    # sender workers
    # ---------------------------------------------------------

    def _start_sender_worker(self, state: _LocalSender) -> None:
        self._maybe_start_sender(state)

        if state.worker and state.worker.is_alive():
            return

        t = threading.Thread(
            target=self._sender_worker_loop,
            args=(state,),
            name=f"HVRM-{state.sender_id}",
            daemon=True,
        )
        state.worker = t
        t.start()

    def _sender_worker_loop(self, state: _LocalSender) -> None:
        self._log_evt("worker", f"worker started for sender '{state.sender_id}' ({state.kind})", ["🧵", "▶️"])

        while not self._stop_event.is_set():
            try:
                item = state.send_q.get(timeout=0.5)
            except queue.Empty:
                continue

            if item is None:
                break

            qf = self._coerce_send_item(item)
            if qf is None:
                state.drop_count += 1
                continue
            if (time.time() - float(qf.enqueued_ts or 0.0)) > 0.75:
                state.drop_count += 1
                continue
            if not state.enabled:
                state.drop_count += 1
                continue

            if state.cooldown_until > time.time():
                state.drop_count += 1
                continue

            try:
                pkt = self._decode_packet(qf.raw)
                if pkt is None:
                    state.drop_count += 1
                    continue

                ok = state.send_callable(pkt)
                if ok is False:
                    raise RuntimeError("send_callable returned False")

                state.send_count += 1
                state.consecutive_failures = 0
                state.cooldown_until = 0.0

                try:
                    self._seen_recently(
                        self._fingerprint(
                            qf.raw,
                            f"sender:{state.sender_id}",
                            qf.protocol_tag or "egress",
                            prefix=f"tx:{state.kind}",
                        )
                    )
                except Exception:
                    pass

            except Exception as e:
                state.consecutive_failures += 1
                if state.consecutive_failures >= 3:
                    state.cooldown_until = time.time() + self.sender_failure_cooldown_sec
                self._log_sparse(
                    f"worker-send:{state.sender_id}",
                    "worker",
                    f"sender '{state.sender_id}' send failed: {type(e).__name__}: {e}",
                    ["⚠️", "🧵", "🧯"],
                    every=2.0,
                )

        self._log_evt("worker", f"worker stopped for sender '{state.sender_id}'", ["🛑", "🧵"])

    def _maybe_start_sender(self, state: _LocalSender) -> None:
        if state.started_by_manager or not callable(state.start_fn):
            return
        try:
            state.start_fn()
            state.started_by_manager = True
        except Exception as e:
            self._log_evt(
                "worker",
                f"sender start for '{state.sender_id}' failed: {type(e).__name__}: {e}",
                ["⚠️", "🧯"],
            )

    def _maybe_stop_sender(self, state: _LocalSender) -> None:
        if not state.started_by_manager:
            return
        fn = state.stop_fn
        if not callable(fn):
            return
        try:
            fn()
        except Exception as e:
            self._log_evt(
                "worker",
                f"failed stopping sender '{state.sender_id}': {type(e).__name__}: {e}",
                ["⚠️", "🧯"],
            )

    def _enqueue_local(self, state: _LocalSender, raw: bytes) -> bool:
        qf = _QueuedLocalFrame(
            raw=raw,
            protocol_tag=self._quick_proto_from_raw(raw),
            enqueued_ts=time.time(),
        )
        try:
            state.send_q.put_nowait(qf)
            return True
        except queue.Full:
            state.drop_count += 1
            self._stats["local_sender_queue_full"] = int(self._stats.get("local_sender_queue_full", 0)) + 1
            return False

    def _coerce_send_item(self, item: Any) -> Optional[_QueuedLocalFrame]:
        if item is None:
            return None
        if isinstance(item, _QueuedLocalFrame):
            return item
        if isinstance(item, (bytes, bytearray)):
            return _QueuedLocalFrame(raw=bytes(item))
        if isinstance(item, dict) and "raw" in item:
            try:
                return _QueuedLocalFrame(
                    raw=bytes(item["raw"]),
                    trace_id=str(item.get("trace_id") or ""),
                    protocol_tag=str(item.get("protocol_tag") or ""),
                    inbound_iface=str(item.get("inbound_iface") or ""),
                    from_remote=bool(item.get("from_remote", False)),
                    src_node_id=str(item.get("src_node_id") or ""),
                    src_host_name=str(item.get("src_host_name") or ""),
                    src_sender_id=str(item.get("src_sender_id") or ""),
                    frame_id=str(item.get("frame_id") or ""),
                    reply_ip=str(item.get("reply_ip") or ""),
                    reply_port=int(item.get("reply_port") or 0),
                )
            except Exception:
                return None
        return None

    # ---------------------------------------------------------
    # endpoint collection / selection
    # ---------------------------------------------------------

    def _collect_candidate_endpoints(self, protocol_tag: str, *, exclude_kind: Optional[str] = None):
        out: List[Tuple[str, Any]] = []
        now = time.time()

        with self._lock:
            peers = list(self._peers.values())

        for peer in peers:
            if peer.segment_id != self.segment_id:
                continue
            if (now - peer.last_seen) > self.peer_timeout_sec or not peer.online:
                continue
            if not self._candidate_peer_targets(peer):
                continue

            peer_sender_ids = sorted(peer.sender_ids) or ["default"]
            peer_sender_kinds = dict(peer.sender_kinds or {})
            if "default" not in peer_sender_kinds:
                peer_sender_kinds["default"] = "hyperv"

            for sender_id in peer_sender_ids:
                sender_kind = peer_sender_kinds.get(sender_id, "hyperv")
                if exclude_kind and sender_kind == exclude_kind:
                    continue
                if peer.allow_protocols and protocol_tag not in peer.allow_protocols:
                    continue

                out.append((
                    "remote",
                    _RemoteEndpoint(
                        node_id=peer.node_id,
                        host_name=peer.host_name,
                        listen_ip=peer.listen_ip,
                        data_port=peer.data_port,
                        sender_id=sender_id,
                        sender_kind=sender_kind,
                        allow_protocols=set(peer.allow_protocols),
                        public_ok=peer.public_ok,
                        gateway_ok=peer.gateway_ok,
                    ),
                ))
        return out

    def _choose_endpoint(self, packet, inbound_iface: str, protocol_tag: str, raw: bytes, endpoints):
        if not endpoints:
            return None

        ingress_kind = self._infer_ingress_kind(inbound_iface)
        remote_eps = [(kind, obj) for kind, obj in endpoints if kind == "remote"]
        if not remote_eps:
            return None

        def _score(item):
            _, obj = item
            score = 100

            if obj.public_ok:
                score += 5
            if obj.gateway_ok:
                score += 10

            if obj.sender_kind == "hyperv":
                score += 15
            elif obj.sender_kind == "wintun":
                score += 8
            elif obj.sender_kind == "windivert":
                score += 5

            if ingress_kind == "hyperv" and obj.sender_kind == "hyperv":
                score += 10
            elif ingress_kind == "wintun" and obj.sender_kind == "wintun":
                score += 6
            elif ingress_kind == "windivert" and obj.sender_kind == "windivert":
                score += 6

            freshness_bonus = max(0.0, self.peer_timeout_sec - (time.time() - self._peer_last_seen(obj.node_id)))
            score += int(freshness_bonus)
            return score

        remote_eps = sorted(remote_eps, key=_score, reverse=True)
        flow_key = self._stable_flow_key(packet, inbound_iface, protocol_tag, raw)

        top_score = _score(remote_eps[0])
        top = [ep for ep in remote_eps if _score(ep) == top_score]
        idx = int.from_bytes(hashlib.blake2b(flow_key.encode("utf-8"), digest_size=8).digest(), "big") % len(top)
        return top[idx]

    # ---------------------------------------------------------
    # discovery / transport
    # ---------------------------------------------------------

    @staticmethod
    def _transport_socket_error_code(exc: BaseException) -> int:
        try:
            return int(getattr(exc, "winerror", 0) or getattr(exc, "errno", 0) or 0)
        except Exception:
            return 0

    @classmethod
    def _is_transport_socket_error(cls, exc: BaseException) -> bool:
        code = cls._transport_socket_error_code(exc)
        return code in {
            errno.ENETDOWN, errno.ENETUNREACH, errno.EHOSTUNREACH,
            errno.EADDRNOTAVAIL, errno.EBADF, errno.ENOTSOCK,
            10038, 10049, 10050, 10051, 10052, 10053, 10054, 10055, 10064, 10065,
        }

    def _request_socket_reopen(self, reason: str) -> None:
        if self._stop_event.is_set():
            return
        with self._socket_reopen_lock:
            self._socket_reopen_reason = str(reason or "runtime-repair")[:512]
        self._socket_reopen_event.set()

    def _router_runtime_ready(self) -> bool:
        try:
            router = self._resolve_router()
            event = getattr(router, "_runtime_network_ready", None) if router is not None else None
            if event is not None and hasattr(event, "is_set"):
                return bool(event.is_set())
        except Exception:
            pass
        return True

    def _target_route_ready(
            self,
            source_ip: str,
            target_ip: str,
            target_port: int,
            *,
            discovery: bool = False,
    ) -> Tuple[bool, str]:
        """Check the Windows route without sending on a long-lived transport socket."""
        try:
            target_obj = ipaddress.ip_address(str(target_ip or "").strip())
            if target_obj.is_multicast or target_obj.is_unspecified:
                return True, "discovery-special" if discovery else "special"
            if str(target_obj) == "255.255.255.255":
                return True, "discovery-broadcast"
        except Exception:
            return False, "invalid-target"

        source = str(source_ip or "").strip()
        target = str(target_ip or "").strip()
        cache_key = (source, target)
        now = time.monotonic()
        cached = self._route_probe_cache.get(cache_key)
        if cached and (now - float(cached[1])) < self._route_probe_cache_ttl_sec:
            return bool(cached[0]), str(cached[2])

        probe = None
        try:
            probe = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
            probe.settimeout(0.25)
            if self._is_valid_bind_ip(source):
                probe.bind((source, 0))
            probe.connect((target, max(1, int(target_port or 9))))
            selected = str(probe.getsockname()[0] or "")
            if not selected or selected == "0.0.0.0":
                raise OSError(errno.ENETUNREACH, "no route-selected source")
            result = (True, now, f"source={selected}")
        except OSError as exc:
            code = self._transport_socket_error_code(exc)
            result = (False, now, f"route-error={code or type(exc).__name__}")
        except Exception as exc:
            result = (False, now, f"route-error={type(exc).__name__}")
        finally:
            if probe is not None:
                try:
                    probe.close()
                except Exception:
                    pass

        self._route_probe_cache[cache_key] = result
        if len(self._route_probe_cache) > 2048:
            cutoff = now - max(10.0, self._route_probe_cache_ttl_sec * 4.0)
            self._route_probe_cache = {
                key: value for key, value in self._route_probe_cache.items()
                if float(value[1]) >= cutoff
            }
        return bool(result[0]), str(result[2])

    def _socket_recovery_loop(self) -> None:
        backoff = self._socket_reopen_backoff_sec
        while not self._stop_event.is_set():
            self._socket_reopen_event.wait(timeout=1.0)
            self._socket_reopen_event.clear()
            if self._stop_event.is_set():
                break

            with self._sock_lock:
                has_data = bool(self._data_socks)
                has_discovery_tx = bool(self._discovery_tx_socks)
            if has_data and has_discovery_tx:
                backoff = self._socket_reopen_backoff_sec
                continue

            if not self._router_runtime_ready():
                self._socket_reopen_event.set()
                self._stop_event.wait(0.5)
                continue

            now = time.monotonic()
            if now - self._socket_reopen_last_attempt < backoff:
                self._socket_reopen_event.set()
                self._stop_event.wait(min(0.5, backoff))
                continue
            self._socket_reopen_last_attempt = now

            with self._socket_reopen_lock:
                reason = self._socket_reopen_reason or "missing-runtime-sockets"

            try:
                self._open_sockets()
                self._socket_reopen_count += 1
                backoff = self._socket_reopen_backoff_sec
                self._log_evt(
                    "socket",
                    f"transport sockets recovered reason={reason} count={self._socket_reopen_count}",
                    ["✅", "🔄", "🌐"],
                )
                try:
                    self._send_hello(startup=True)
                except Exception:
                    pass
            except Exception as e:
                self._socket_runtime_failures += 1
                self._close_sockets()
                backoff = min(self._socket_reopen_max_backoff_sec, max(0.5, backoff * 2.0))
                self._log_sparse(
                    "socket-recovery-failed",
                    "socket",
                    f"transport socket repair deferred ({reason}): {type(e).__name__}: {e}; "
                    f"retry_backoff={backoff:.1f}s",
                    ["⚠️", "🔄", "🧯"],
                    every=2.0,
                )
                self._socket_reopen_event.set()
                self._stop_event.wait(backoff)

    def _open_sockets(self) -> None:
        with self._sock_lock:
            self._close_sockets_locked()

            self._discovery_tx_socks = self._open_discovery_sender_sockets()
            self._discovery_tx_sock = self._preferred_socket_alias(self._discovery_tx_socks)
            self._discovery_sock = self._open_discovery_socket()
            self._bound_discovery_port = self.discovery_port
            self._data_sock, self._bound_data_port = self._open_data_socket_with_fallback()

            if self._data_sock is None:
                raise RuntimeError("no HyperVRouterManager data socket could be bound")

            self._log_evt(
                "socket",
                f"hybrid sockets ready data={dict(self._bound_data_ports_by_ip)} "
                f"discovery_tx={sorted(self._discovery_tx_socks)}",
                ["🌐", "🏠", "✅"],
            )

    def _open_discovery_sender_sockets(self) -> Dict[str, socket.socket]:
        out: Dict[str, socket.socket] = {}
        for bind_ip in self._ordered_local_transport_ips():
            ds: Optional[socket.socket] = None
            try:
                ds = self._make_udp_socket()
                try:
                    ds.setsockopt(socket.IPPROTO_IP, socket.IP_MULTICAST_TTL, 1)
                except Exception:
                    pass
                try:
                    ds.setsockopt(socket.IPPROTO_IP, socket.IP_MULTICAST_LOOP, 1)
                except Exception:
                    pass
                try:
                    ds.setsockopt(socket.IPPROTO_IP, socket.IP_MULTICAST_IF, socket.inet_aton(bind_ip))
                except Exception:
                    pass
                ds.bind((bind_ip, 0))
                ds.settimeout(0.25)
                out[bind_ip] = ds
                self._socket_source_ips[id(ds)] = bind_ip
            except Exception as e:
                if ds is not None:
                    self._safe_socket_close(ds)
                self._log_sparse(
                    f"discovery-tx-bind:{bind_ip}",
                    "socket",
                    f"discovery TX path unavailable on {bind_ip}: {type(e).__name__}: {e}",
                    ["⚠️", "📡", "🧯"],
                    every=5.0,
                )

        if not out:
            # A route-selected wildcard sender is a last-resort compatibility
            # path. Stable frame/ACK traffic still uses the bound data sockets.
            ds = self._make_udp_socket()
            ds.bind(("", 0))
            ds.settimeout(0.25)
            out["0.0.0.0"] = ds
            self._socket_source_ips[id(ds)] = "0.0.0.0"
        return out

    def _open_discovery_sender_socket(self) -> Optional[socket.socket]:
        """Backward-compatible wrapper returning the preferred TX socket."""
        sockets = self._open_discovery_sender_sockets()
        self._discovery_tx_socks = sockets
        return self._preferred_socket_alias(sockets)

    def _join_multicast_group(self, sock_obj: socket.socket, iface_ip: str = "") -> None:
        selected = str(iface_ip or "").strip()
        mreq = struct.pack(
            "=4s4s",
            socket.inet_aton(self.discovery_group),
            socket.inet_aton(selected if self._is_valid_bind_ip(selected) else "0.0.0.0"),
        )
        sock_obj.setsockopt(socket.IPPROTO_IP, socket.IP_ADD_MEMBERSHIP, mreq)

    def _open_discovery_socket(self) -> Optional[socket.socket]:
        ds: Optional[socket.socket] = None
        try:
            ds = self._make_udp_socket()
            ds.bind(("", self.discovery_port))

            joined: List[str] = []
            for iface_ip in self._ordered_local_transport_ips():
                try:
                    self._join_multicast_group(ds, iface_ip)
                    joined.append(iface_ip)
                except Exception as e:
                    self._log_sparse(
                        f"multicast-join:{iface_ip}",
                        "socket",
                        f"multicast join failed on {iface_ip}: {type(e).__name__}: {e}",
                        ["⚠️", "📡"],
                        every=10.0,
                    )
            if not joined:
                self._join_multicast_group(ds, "0.0.0.0")
                joined.append("0.0.0.0")

            ds.settimeout(0.25)
            self._socket_source_ips[id(ds)] = "0.0.0.0"
            self._log_evt(
                "socket",
                f"discovery socket bound on 0.0.0.0:{self.discovery_port}; memberships={joined}",
                ["📡", "✅"],
            )
            return ds
        except OSError as e:
            if ds is not None:
                self._safe_socket_close(ds)
            if self._is_addr_in_use_error(e):
                self._log_evt(
                    "socket",
                    f"discovery bind in use on *:{self.discovery_port}; receive disabled but send-only discovery remains active",
                    ["⚠️", "📡", "🧯"],
                )
                if not self._allow_discovery_degraded_mode:
                    raise
                return None
            self._log_evt(
                "socket",
                f"discovery socket open failed: {type(e).__name__}: {e}",
                ["⚠️", "🧯"],
            )
            if not self._allow_discovery_degraded_mode:
                raise
            return None
        except Exception as e:
            if ds is not None:
                self._safe_socket_close(ds)
            self._log_evt(
                "socket",
                f"discovery socket open failed: {type(e).__name__}: {e}",
                ["⚠️", "🧯"],
            )
            if not self._allow_discovery_degraded_mode:
                raise
            return None

    def _open_data_socket_with_fallback(self) -> Tuple[Optional[socket.socket], int]:
        """
        Bind the stable HVRM data port on every validated concrete transport
        address.  If Windows refuses every address-specific bind, fall back to
        one wildcard socket on the *same* port so the Windows routing table can
        choose the correct source address.

        The fallback never changes the advertised/forwarded port.  This is
        important for AT&T IP Passthrough and port-forwarded UDP 47772.
        """
        self._data_socks = {}
        self._bound_data_ports_by_ip = {}

        ordered_ips = self._ordered_local_transport_ips()
        if not ordered_ips:
            raise RuntimeError("data sockets require at least one validated concrete local IPv4 address")

        errors: List[str] = []
        for bind_ip in ordered_ips:
            sock_obj: Optional[socket.socket] = None
            try:
                sock_obj = self._make_udp_socket()
                sock_obj.bind((bind_ip, self.data_port))
                sock_obj.settimeout(0.25)
                actual_port = int(sock_obj.getsockname()[1])
                self._data_socks[bind_ip] = sock_obj
                self._bound_data_ports_by_ip[bind_ip] = actual_port
                self._socket_source_ips[id(sock_obj)] = bind_ip
                self._log_evt(
                    "socket",
                    f"data path bound role={self._local_transport_roles.get(bind_ip, 'local')} "
                    f"address={bind_ip}:{actual_port}",
                    ["📦", "✅"],
                )
            except Exception as e:
                if sock_obj is not None:
                    self._safe_socket_close(sock_obj)
                errors.append(f"{bind_ip}:{self.data_port}={type(e).__name__}:{e}")
                self._log_sparse(
                    f"data-bind:{bind_ip}",
                    "socket",
                    f"data path bind failed on {bind_ip}:{self.data_port}: {type(e).__name__}: {e}",
                    ["⚠️", "📦", "🧯"],
                    every=5.0,
                )

        if not self._data_socks and self._allow_data_port_fallback:
            wildcard: Optional[socket.socket] = None
            try:
                wildcard = self._make_udp_socket()
                wildcard.bind(("", self.data_port))
                wildcard.settimeout(0.25)
                actual_port = int(wildcard.getsockname()[1])
                self._data_socks["0.0.0.0"] = wildcard
                self._bound_data_ports_by_ip["0.0.0.0"] = actual_port
                self._socket_source_ips[id(wildcard)] = "0.0.0.0"
                self._log_evt(
                    "socket",
                    f"data path using route-selected wildcard 0.0.0.0:{actual_port}",
                    ["🧭", "📦", "✅"],
                )
            except Exception as e:
                if wildcard is not None:
                    self._safe_socket_close(wildcard)
                errors.append(f"0.0.0.0:{self.data_port}={type(e).__name__}:{e}")

        if not self._data_socks:
            raise RuntimeError("all data socket binds failed: " + "; ".join(errors))

        preferred = self._preferred_socket_alias(self._data_socks)
        preferred_ip = self._socket_source_ips.get(id(preferred), "") if preferred is not None else ""
        preferred_port = int(self._bound_data_ports_by_ip.get(preferred_ip, self.data_port))
        return preferred, preferred_port

    def _close_sockets(self) -> None:
        with self._sock_lock:
            self._close_sockets_locked()

    def _close_sockets_locked(self) -> None:
        unique: List[socket.socket] = []
        for s in [
            self._discovery_sock,
            self._discovery_tx_sock,
            self._data_sock,
            *self._discovery_tx_socks.values(),
            *self._data_socks.values(),
        ]:
            if s is not None and s not in unique:
                unique.append(s)
        for s in unique:
            self._safe_socket_close(s)

        self._discovery_sock = None
        self._discovery_tx_sock = None
        self._data_sock = None
        self._discovery_tx_socks = {}
        self._data_socks = {}
        self._bound_data_ports_by_ip = {}
        self._socket_source_ips = {}
        self._bound_discovery_port = self.discovery_port
        self._bound_data_port = self.data_port
        self._route_source_cache.clear()
        self._route_probe_cache.clear()

        if self._socket_close_wait_sec > 0:
            time.sleep(self._socket_close_wait_sec)

    def _hello_loop(self) -> None:
        while not self._stop_event.wait(self.heartbeat_sec):
            if not self._router_runtime_ready():
                continue
            try:
                self._send_hello()
            except Exception as e:
                self._log_sparse(
                    "hello-loop",
                    "network",
                    f"hello loop error: {type(e).__name__}: {e}",
                    ["⚠️", "🧩"],
                    every=2.0,
                )

    def _network_sender_loop(self) -> None:
        while not self._stop_event.is_set():
            try:
                item = self._net_tx_q.get(timeout=0.25)
            except queue.Empty:
                continue

            try:
                if item is None:
                    break

                queued_ts = float(item.get("queued_ts", 0.0) or 0.0)
                age = max(0.0, time.monotonic() - queued_ts) if queued_ts else 0.0
                mtype = str(item.get("mtype") or "")
                max_age = 3.0 if mtype == "frame" else 15.0
                if queued_ts and age > max_age:
                    self._stats["peer_send_stale_dropped"] = int(self._stats.get("peer_send_stale_dropped", 0)) + 1
                    frame_id = str(item.get("frame_id") or "")
                    if frame_id:
                        with self._pending_lock:
                            self._pending_frames.pop(frame_id, None)
                    continue

                self._send_network_item_inline(item)
            except Exception as e:
                self._log_sparse(
                    "network-tx-loop",
                    "network",
                    f"wire send loop error: {type(e).__name__}: {e}",
                    ["⚠️", "📤", "🧯"],
                    every=2.0,
                )
            finally:
                try:
                    self._net_tx_q.task_done()
                except Exception:
                    pass

    def _recv_loop(self) -> None:
        while not self._stop_event.is_set():
            with self._sock_lock:
                socket_kinds: Dict[int, str] = {}
                socks: List[socket.socket] = []

                def _add(sock_obj: Optional[socket.socket], kind: str) -> None:
                    if sock_obj is None or sock_obj in socks:
                        return
                    socks.append(sock_obj)
                    socket_kinds[id(sock_obj)] = kind

                _add(self._discovery_sock, "discovery")
                for sock_obj in self._data_socks.values():
                    _add(sock_obj, "data")
                for sock_obj in self._discovery_tx_socks.values():
                    # hello replies can return to the discovery socket's
                    # ephemeral source port, so these sockets are polled too.
                    _add(sock_obj, "data")

            if not socks:
                self._stop_event.wait(0.25)
                continue

            try:
                ready, _, _ = select.select(socks, [], [], 0.25)
            except Exception:
                self._stop_event.wait(0.10)
                continue

            for sock_obj in ready:
                which = socket_kinds.get(id(sock_obj), "data")
                try:
                    data, addr = sock_obj.recvfrom(int(self._wire_message_max_bytes))
                except socket.timeout:
                    continue
                except OSError as e:
                    if self._is_transport_socket_error(e):
                        self._request_socket_reopen(
                            f"recv:{which}:{self._transport_socket_error_code(e)}"
                        )
                    continue
                except Exception:
                    continue

                try:
                    self._handle_wire_message(
                        data, addr[0], addr[1], which, recv_sock=sock_obj
                    )
                except Exception as e:
                    self._log_sparse(
                        "wire-msg-fail",
                        "network",
                        f"wire message handling failed: {type(e).__name__}: {e}",
                        ["⚠️", "🧩"],
                        every=2.0,
                    )

    def _health_loop(self) -> None:
        self._log_evt("worker", "health worker started", ["🧵", "🩺"])

        last_pressure_apply_ts = 0.0
        last_discovery_slowdown_ts = 0.0

        while not self._stop_event.wait(self.heartbeat_sec):
            now = time.time()

            try:
                # 1) expire offline peers
                self._prune_peers()
            except Exception as e:
                self._log_sparse(
                    "health-prune-peers",
                    "health",
                    f"health prune_peers failed: {type(e).__name__}: {e}",
                    ["⚠️", "🩺", "🧯"],
                    every=2.0,
                )

            try:
                # 2) prune all local / distributed dedupe stores
                self._prune_recent()
            except Exception as e:
                self._log_sparse(
                    "health-prune-recent",
                    "health",
                    f"health prune_recent failed: {type(e).__name__}: {e}",
                    ["⚠️", "🩺", "🧯"],
                    every=2.0,
                )

            try:
                # 3) expire pending frame tracking
                # frame retries are disabled now, so this mainly clears stale tracking
                self._retry_pending_frames()
            except Exception as e:
                self._log_sparse(
                    "health-retry-pending",
                    "health",
                    f"health retry_pending_frames failed: {type(e).__name__}: {e}",
                    ["⚠️", "🩺", "🧯"],
                    every=2.0,
                )

            try:
                # 4) hard prune any stale / overflowed pending frame records
                self._prune_pending_frames()
            except Exception as e:
                self._log_sparse(
                    "health-prune-pending",
                    "health",
                    f"health prune_pending_frames failed: {type(e).__name__}: {e}",
                    ["⚠️", "🩺", "🧯"],
                    every=2.0,
                )

            try:
                # 5) trim old flow-activity records so consumer-rate tracking does not grow forever
                cutoff = now - max(2.0, float(self._consumer_flow_window_sec or 2.0) * 2.0)
                while self._flow_activity_order:
                    key = self._flow_activity_order[0]
                    info = self._flow_activity.get(key)
                    if not isinstance(info, dict):
                        self._flow_activity_order.popleft()
                        self._flow_activity.pop(key, None)
                        continue

                    last_seen = float(info.get("last_seen", 0.0) or 0.0)
                    if last_seen >= cutoff:
                        break

                    self._flow_activity_order.popleft()
                    self._flow_activity.pop(key, None)
            except Exception as e:
                self._log_sparse(
                    "health-prune-flow-activity",
                    "health",
                    f"health flow activity prune failed: {type(e).__name__}: {e}",
                    ["⚠️", "🩺", "🧯"],
                    every=2.0,
                )

            try:
                # 6) trim breaker event timestamps
                window_start = now - float(self._remote_ingress_breaker_window_sec or 20.0)
                dq = self._remote_ingress_queue_full_events
                while dq and dq[0] < window_start:
                    dq.popleft()
            except Exception as e:
                self._log_sparse(
                    "health-prune-breaker-events",
                    "health",
                    f"health breaker queue prune failed: {type(e).__name__}: {e}",
                    ["⚠️", "🩺", "🧯"],
                    every=2.0,
                )

            try:
                # 7) if breaker has been open and pressure cooled off, let it close naturally
                if self._remote_ingress_breaker_open_until > 0.0 and now >= float(
                        self._remote_ingress_breaker_open_until):
                    self._remote_ingress_breaker_open_until = 0.0
                    self._log_sparse(
                        "health-breaker-closed",
                        "health",
                        "remote ingress breaker closed",
                        ["🟢", "🩺", "📥"],
                        every=2.0,
                    )
            except Exception as e:
                self._log_sparse(
                    "health-breaker-close",
                    "health",
                    f"health breaker close check failed: {type(e).__name__}: {e}",
                    ["⚠️", "🩺", "🧯"],
                    every=2.0,
                )

            try:
                # 8) dynamically tighten / relax mirroring thresholds based on recent pressure
                if (now - last_pressure_apply_ts) >= 1.0:
                    self._apply_pressure_mode()
                    last_pressure_apply_ts = now
            except Exception as e:
                self._log_sparse(
                    "health-pressure-mode",
                    "health",
                    f"health pressure mode update failed: {type(e).__name__}: {e}",
                    ["⚠️", "🩺", "🧯"],
                    every=2.0,
                )

            try:
                # 9) if the manager is under clear pressure, make discovery even quieter temporarily
                pressure = (
                        int(self._stats.get("peer_send_queue_full", 0))
                        + int(self._stats.get("remote_ingress_queue_full", 0))
                        + int(self._stats.get("remote_ingress_busy", 0))
                )

                if pressure >= 8:
                    if (now - last_discovery_slowdown_ts) >= 5.0:
                        self._log_sparse(
                            "health-discovery-slowdown",
                            "health",
                            f"pressure detected; keeping discovery quiet pressure={pressure}",
                            ["🚦", "📡", "🩺"],
                            every=5.0,
                        )
                        last_discovery_slowdown_ts = now
            except Exception as e:
                self._log_sparse(
                    "health-discovery-pressure",
                    "health",
                    f"health discovery pressure check failed: {type(e).__name__}: {e}",
                    ["⚠️", "🩺", "🧯"],
                    every=2.0,
                )

            try:
                # 10) periodically emit a compact health snapshot
                with self._pending_lock:
                    pending_count = len(self._pending_frames)

                ingress_qsize = 0
                net_qsize = 0
                try:
                    ingress_qsize = int(self._router_ingress_q.qsize())
                except Exception:
                    ingress_qsize = -1
                try:
                    net_qsize = int(self._net_tx_q.qsize())
                except Exception:
                    net_qsize = -1

                online_peers = 0
                with self._lock:
                    online_peers = sum(1 for p in self._peers.values() if getattr(p, "online", False))

                breaker_open = int(self._is_remote_ingress_breaker_open())

                self._log_sparse(
                    "health-snapshot",
                    "health",
                    (
                        f"health snapshot peers_online={online_peers} "
                        f"pending={pending_count} net_q={net_qsize} ingress_q={ingress_qsize} "
                        f"breaker_open={breaker_open} "
                        f"send_q_full={int(self._stats.get('peer_send_queue_full', 0))} "
                        f"ingress_q_full={int(self._stats.get('remote_ingress_queue_full', 0))} "
                        f"ingress_busy={int(self._stats.get('remote_ingress_busy', 0))} "
                        f"ack_rx={int(self._stats.get('ack_received', 0))} "
                        f"ack_direct_tx={int(self._stats.get('ack_direct_sent', 0))} "
                        f"ack_mc_tx={int(self._stats.get('ack_discovery_sent', 0))} "
                        f"ack_mc_rx={int(self._stats.get('ack_discovery_received', 0))} "
                        f"dropped_general={int(self._stats.get('general_traffic_dropped', 0))} "
                        f"dropped_noise={int(self._stats.get('noise_dropped', 0))}"
                    ),
                    ["🩺", "📊"],
                    every=max(10.0, float(self.heartbeat_sec)),
                )
            except Exception as e:
                self._log_sparse(
                    "health-snapshot-fail",
                    "health",
                    f"health snapshot failed: {type(e).__name__}: {e}",
                    ["⚠️", "🩺", "🧯"],
                    every=2.0,
                )

        self._log_evt("worker", "health worker stopped", ["🛑", "🩺"])

    def _send_hello(self, startup: bool = False) -> None:
        with self._sock_lock:
            tx_paths = list(self._discovery_tx_socks.items())
            if not tx_paths and self._discovery_tx_sock is not None:
                tx_paths = [(self._socket_source_ips.get(id(self._discovery_tx_sock), self._advertise_ip()), self._discovery_tx_sock)]
            advertised_discovery_port = self._bound_discovery_port or self.discovery_port

        if not tx_paths:
            return

        hello_id = uuid.uuid4().hex
        self._last_hello_id = hello_id
        self._last_hello_ts = time.time()
        self._hello_challenges[hello_id] = self._last_hello_ts + float(self._wire_max_clock_skew_sec)
        if len(self._hello_challenges) > 64:
            now_ts = time.time()
            for old_id, expiry in sorted(self._hello_challenges.items(), key=lambda kv: kv[1]):
                if expiry <= now_ts or len(self._hello_challenges) > 64:
                    self._hello_challenges.pop(old_id, None)

        targets: List[Tuple[str, int, str]] = []
        if self._transport_ip_allowed(self.discovery_group, discovery=True):
            targets.append((self.discovery_group, self.discovery_port, "multicast"))
        for broadcast_ip in self._discovery_broadcast_targets():
            targets.append((broadcast_ip, self.discovery_port, "broadcast"))
        for ip, port in self._known_peer_direct_targets():
            targets.append((ip, port, "direct"))

        deduped_targets: List[Tuple[str, int, str]] = []
        seen: Set[Tuple[str, int, str]] = set()
        for ip, port, label in targets:
            key = (str(ip or ""), int(port or 0), str(label))
            if not key[0] or key[1] <= 0 or key in seen:
                continue
            seen.add(key)
            deduped_targets.append(key)

        sent_paths: Set[str] = set()
        for target_ip, target_port, label in deduped_targets:
            if label in {"multicast", "broadcast"}:
                candidates = tx_paths
            else:
                selected_sock, selected_source = self._select_transport_socket(
                    target_ip, "hello", discovery=True
                )
                candidates = [(selected_source, selected_sock)] if selected_sock is not None else []

            for source_ip, tx_sock in candidates:
                if tx_sock is None:
                    continue
                source_ip = self._normalize_local_source_ip(source_ip, tx_sock)
                raw = self._encode_wire_message(self._build_hello_message(
                    hello_id=hello_id,
                    startup=startup,
                    advertised_ip=source_ip,
                    advertised_discovery_port=advertised_discovery_port,
                ))
                try:
                    tx_sock.sendto(raw, (target_ip, target_port))
                    sent_paths.add(source_ip)
                    self._stats["hybrid_discovery_tx"] = int(self._stats.get("hybrid_discovery_tx", 0)) + 1
                    if label == "multicast":
                        self._stats["peer_discovery_multicast"] += 1
                    elif label == "broadcast":
                        self._stats["peer_discovery_broadcast"] += 1
                except Exception as e:
                    self._log_sparse(
                        f"hello-send-fail:{label}:{source_ip}:{target_ip}:{target_port}",
                        "peer",
                        f"hello send failed source={source_ip} target={target_ip}:{target_port} "
                        f"mode={label}: {type(e).__name__}: {e}",
                        ["⚠️", "📡", "🧯"],
                        every=5.0,
                    )

        if sent_paths:
            self._log_sparse(
                f"hello-sent:{self.node_id}",
                "peer",
                f"hello sent node={self.node_id} seg={self.segment_id} paths={sorted(sent_paths)} "
                f"hello_id={hello_id[:12]} startup={int(bool(startup))}",
                ["📡", "📤", "🌐"],
                every=10.0,
            )

    def _flush_network_queue(self) -> None:
        while True:
            try:
                item = self._net_tx_q.get_nowait()
            except queue.Empty:
                break
            if item is None:
                break
            self._send_network_item_inline(item)

    def _handle_wire_message(
            self,
            raw: bytes,
            from_ip: str,
            from_port: int,
            which: str,
            recv_sock: Optional[socket.socket] = None,
    ) -> None:
        raw_bytes = bytes(raw or b"")
        if not raw_bytes or len(raw_bytes) > int(self._wire_message_max_bytes):
            return

        from_ip = str(from_ip or "").strip()
        try:
            from_port = int(from_port or 0)
        except Exception:
            return
        if not self._is_usable_unicast_ipv4(from_ip) or not (1 <= from_port <= 65535):
            return

        msg = None
        stripped = raw_bytes.strip(b"\x00\r\n\t ")
        candidates = [raw_bytes]
        if stripped and stripped != raw_bytes:
            candidates.append(stripped)

        for blob in candidates:
            try:
                decoded = blob.decode("utf-8", errors="strict")
                msg = json.loads(decoded)
                break
            except Exception:
                pass

        if msg is None:
            try:
                text_blob = stripped.decode("utf-8", errors="strict").lstrip("\ufeff\r\n\t \x00")
                decoder = json.JSONDecoder()
                msg, end_idx = decoder.raw_decode(text_blob)
                if text_blob[end_idx:].strip():
                    return
            except Exception:
                return

        if not isinstance(msg, dict):
            return

        if int(msg.get("enc_v", 0) or 0) == 1:
            if not self._wire_encryption_key:
                return
            try:
                from cryptography.hazmat.primitives.ciphers.aead import AESGCM
                nonce = base64.b64decode(str(msg.get("nonce") or ""), validate=True)
                ciphertext = base64.b64decode(str(msg.get("ciphertext") or ""), validate=True)
                clear = AESGCM(self._wire_encryption_key).decrypt(
                    nonce, ciphertext, self.segment_id.encode("utf-8")
                )
                msg = json.loads(clear.decode("utf-8"))
            except Exception:
                self._log_sparse(
                    f"wire-decrypt:{from_ip}",
                    "security",
                    f"encrypted peer packet rejected source={from_ip}",
                    ["🔐", "🛡️", "⚠️"],
                    every=10.0,
                )
                return
            if not isinstance(msg, dict):
                return

        magic = str(msg.get("magic") or "").strip()
        if magic not in self.ACCEPT_MAGICS:
            return
        if str(msg.get("segment_id") or "") != self.segment_id:
            return
        if not self._verify_wire_message_auth(msg):
            return

        node_like = self._bounded_text(msg.get("node_id") or msg.get("src_node_id"), 128)
        if not node_like or node_like == self.node_id:
            return

        raw_type = str(msg.get("type") or "").strip().lower()
        type_aliases = {
            "hello-response": "hello_ack",
            "helloack": "hello_ack",
            "frame_ack": "ack",
            "packet_ack": "ack",
            "peer_ack": "ack",
            "acknowledge": "ack",
            "status": "ack",
            "frame_status": "ack",
            "recv_ok": "ack",
            "receive_ok": "ack",
            "received": "ack",
            "processed": "ack",
            "success": "ack",
            "ok": "ack",
            "packet": "frame",
            "peer_frame": "frame",
            "frame_packet": "frame",
            "data": "frame",
            "raw_frame": "frame",
        }
        mtype = type_aliases.get(raw_type, raw_type)
        if mtype not in self.HVRM_CONTROL_TYPES:
            return

        if mtype == "hello_ack":
            hello_id = self._bounded_text(msg.get("hello_id"), 128)
            expiry = float(self._hello_challenges.get(hello_id, 0.0) or 0.0)
            if not hello_id or expiry < time.time():
                return

        # Reject stale/replayed envelopes when a timestamp is present. Legacy
        # peers without a timestamp still work unless authentication is required.
        ts_val = msg.get("ts")
        if ts_val is not None:
            try:
                if abs(time.time() - float(ts_val)) > float(self._wire_max_clock_skew_sec):
                    return
            except Exception:
                return
        elif self._wire_require_auth:
            return

        if not self._wire_rate_allowed(from_ip, mtype):
            self._log_sparse(
                f"wire-rate:{from_ip}:{mtype}",
                "security",
                f"wire rate limit hit source={from_ip} type={mtype}",
                ["🛡️", "🚦", "🛑"],
                every=2.0,
            )
            return

        # Frames remain data-socket only. ACKs may additionally arrive over
        # discovery multicast, but only when explicitly targeted to this node
        # and tied to an outstanding random frame_id for the same peer.
        if mtype in {"frame", "ack"}:
            discovery_ack = bool(mtype == "ack" and which == "discovery")
            if mtype == "frame" and which != "data" and self._data_sock is not None:
                return
            if mtype == "ack" and which != "data" and not discovery_ack:
                return
            if discovery_ack:
                ack_dst = self._bounded_text(
                    msg.get("dst_node_id") or msg.get("target_node_id") or msg.get("dst_peer_id"), 128
                )
                ack_frame_id = self._bounded_text(
                    msg.get("frame_id") or msg.get("id") or msg.get("ref"), 128
                )
                with self._pending_lock:
                    pending = self._pending_frames.get(ack_frame_id)
                    discovery_ack_valid = bool(
                        ack_dst == self.node_id
                        and pending is not None
                        and str(pending.get("peer_node_id") or "") == node_like
                    )
                if not discovery_ack_valid:
                    self._stats["ack_discovery_rejected"] = int(
                        self._stats.get("ack_discovery_rejected", 0)
                    ) + 1
                    return
            if not self._wire_source_matches_peer(node_like, from_ip, from_port, mtype, msg):
                self._log_sparse(
                    f"wire-source-reject:{node_like}:{from_ip}",
                    "security",
                    f"rejected unbound peer source node={node_like} source={from_ip}:{from_port} type={mtype}",
                    ["🛡️", "🚫", "🌐"],
                    every=2.0,
                )
                return

        if mtype in {"hello", "hello_ack"}:
            self._stats["peer_discovery_rx"] = int(self._stats.get("peer_discovery_rx", 0)) + 1

        if self._log_wire_messages:
            self._log_sparse(
                f"wire-msg:{which}:{mtype}:{node_like}",
                "peer",
                f"wire msg type={mtype} node={node_like} seg={msg.get('segment_id')} from={from_ip}:{from_port} via={which}",
                ["📥", "🧠"],
                every=10.0,
            )

        if mtype in {"hello", "hello_ack"}:
            self._update_peer_from_hello(msg, from_ip, from_port, which)
            self._mark_discovery_success(
                node_id=node_like,
                from_ip=from_ip,
                from_port=from_port,
                which=which,
                hello_id=str(msg.get("hello_id") or ""),
                was_reply=(mtype == "hello_ack"),
            )
            if mtype == "hello":
                self._send_hello_reply(msg, from_ip, from_port)
            return

        if mtype == "frame":
            self._handle_remote_frame(
                msg, from_ip, from_port, recv_sock=recv_sock
            )
            return

        if mtype == "ack":
            self._handle_frame_ack(msg, from_ip, from_port, which=which)
            return

    def _mark_discovery_success(
            self,
            *,
            node_id: str,
            from_ip: str,
            from_port: int,
            which: str,
            hello_id: str = "",
            was_reply: bool = False,
    ) -> None:
        """
        Promote the actual source IP of every valid HELLO/HELLO_ACK to a
        confirmed peer path.  The UDP source port of discovery is often
        ephemeral, so the peer's advertised stable data port is stored for
        frames while the observed source port remains discovery metadata.
        """
        if not node_id or node_id == self.node_id:
            return

        now = time.time()
        ip = self._sanitize_peer_ip(from_ip)
        with self._lock:
            peer = self._peers.get(str(node_id))
            if peer is None:
                return
            peer.last_seen = now
            peer.online = True
            peer.last_discovery_rx_ts = now
            peer.last_discovery_success_ts = now
            peer.discovery_success_count = int(peer.discovery_success_count or 0) + 1
            if hello_id:
                peer.last_hello_id = self._bounded_text(hello_id, 128)
            if ip:
                peer.last_hello_from_ip = ip
                peer.last_observed_ip = ip
            if 1 <= int(from_port or 0) <= 65535:
                peer.last_hello_from_port = int(from_port)

            stable_data_port = self._safe_port(peer.data_port, self.data_port)
            self._record_peer_path_locked(
                peer,
                ip,
                stable_data_port,
                confirmed=True,
                data_path=True,
                observed=True,
            )
            peer.listen_ip = self._best_peer_ip_locked(peer)
            peer.last_ack_ts = now

        self._stats["peer_discovery_success"] = int(self._stats.get("peer_discovery_success", 0)) + 1
        if self._assume_delivery_on_peer_contact:
            self._complete_pending_frames_for_peer(
                str(node_id),
                reason=("hello_reply_contact" if was_reply else "hello_contact"),
                min_age_sec=float(self._implicit_ack_grace_sec),
            )
        self._log_sparse(
            f"discovery-success:{node_id}",
            "peer",
            f"discovery success node={node_id} source={from_ip}:{from_port} via={which} "
            f"confirmed_data={ip or '-'}:{stable_data_port or 0} "
            f"hello_id={(hello_id or '-')[:12]} reply={int(bool(was_reply))}",
            ["✅", "📡", "🤝"],
            every=3.0,
        )

    def _update_peer_from_hello(self, msg: dict, from_ip: str, from_port: int = 0, which: str = "") -> None:
        node_id = self._bounded_text(msg.get("node_id") or msg.get("src_node_id"), 128)
        if not node_id or node_id == self.node_id:
            return

        now = time.time()
        advertised_ip = self._sanitize_peer_ip(
            msg.get("listen_ip") or msg.get("reply_to_ip") or msg.get("advertised_ip")
        )
        observed_ip = self._sanitize_peer_ip(from_ip)
        advertised_data_port = self._safe_port(
            msg.get("reply_data_port") or msg.get("data_port"), self.data_port
        )
        advertised_discovery_port = self._safe_port(
            msg.get("reply_discovery_port") or msg.get("discovery_port"), self.discovery_port
        )

        raw_hints = msg.get("address_hints") or []
        address_hints = self._dedupe_usable_ips(
            raw_hints if isinstance(raw_hints, (list, tuple, set)) else []
        )[:12]

        raw_roles = msg.get("address_roles") or {}
        advertised_roles: Dict[str, str] = {}
        if isinstance(raw_roles, dict):
            for raw_ip, raw_role in list(raw_roles.items())[:16]:
                ip = self._sanitize_peer_ip(raw_ip)
                role = self._bounded_text(raw_role, 48).lower()
                if ip and role and not self._is_unobserved_local_alias(ip, observed_ip):
                    advertised_roles[ip] = role

        private_ips = {
            ip for ip in self._dedupe_usable_ips(msg.get("private_ips") or [])
            if self._is_private_ipv4(ip) and not self._is_unobserved_local_alias(ip, observed_ip)
        }
        public_ips = {
            ip for ip in self._dedupe_usable_ips(msg.get("public_ips") or [])
            if not self._is_private_ipv4(ip) and not self._is_unobserved_local_alias(ip, observed_ip)
        }
        preferred_private_ip = self._sanitize_peer_ip(msg.get("preferred_private_ip"))
        if (
                preferred_private_ip
                and (
                    not self._is_private_ipv4(preferred_private_ip)
                    or self._is_unobserved_local_alias(preferred_private_ip, observed_ip)
                )
        ):
            preferred_private_ip = ""

        changed = False
        is_new = False
        with self._lock:
            peer = self._peers.get(node_id)
            if peer is None:
                initial_ip = self._choose_peer_ip(advertised_ip, observed_ip, "", "")
                peer = _Peer(
                    node_id=node_id,
                    host_name=self._bounded_text(msg.get("host_name") or node_id, 255) or node_id,
                    listen_ip=initial_ip,
                    data_port=advertised_data_port,
                    segment_id=self.segment_id,
                    advertised_ip=("" if self._is_unobserved_local_alias(advertised_ip, observed_ip) else advertised_ip),
                    last_hello_from_ip=observed_ip,
                    last_hello_from_port=int(from_port or 0),
                )
                self._peers[node_id] = peer
                is_new = True

            old_tuple = (
                peer.listen_ip,
                peer.data_port,
                peer.discovery_port,
                peer.host_name,
                tuple(sorted(peer.sender_ids)),
                tuple(sorted(peer.sender_kinds.items())),
                tuple(sorted(peer.candidate_ips)),
                tuple(sorted(peer.confirmed_ips)),
                tuple(sorted(getattr(peer, "observed_ips", set()))),
                tuple(sorted(peer.address_roles.items())),
                tuple(sorted(peer.private_ips)),
                tuple(sorted(peer.public_ips)),
                peer.passthrough_enabled,
                getattr(peer, "same_address_mode", False),
                peer.preferred_private_ip,
                peer.path_mode,
            )

            peer.host_name = self._bounded_text(msg.get("host_name") or peer.host_name or node_id, 255) or node_id
            peer.segment_id = self.segment_id
            if advertised_ip and not self._is_unobserved_local_alias(advertised_ip, observed_ip):
                peer.advertised_ip = advertised_ip
            if observed_ip:
                peer.last_hello_from_ip = observed_ip
                peer.last_observed_ip = observed_ip
            if 1 <= int(from_port or 0) <= 65535:
                peer.last_hello_from_port = int(from_port)

            peer.data_port = advertised_data_port
            peer.discovery_port = advertised_discovery_port
            peer.passthrough_enabled = bool(msg.get("passthrough_enabled", msg.get("public_ok", False)))
            peer.same_address_mode = bool(msg.get("same_address_mode", False))
            peer.path_mode = self._bounded_text(
                msg.get("path_mode")
                or ("same-address" if peer.same_address_mode else ("hybrid" if peer.passthrough_enabled else "lan")),
                32,
            ) or "lan"
            peer.address_roles.update(advertised_roles)
            peer.private_ips.update(private_ips)
            peer.public_ips.update(public_ips)
            if preferred_private_ip:
                peer.preferred_private_ip = preferred_private_ip

            self._record_peer_path_locked(
                peer,
                advertised_ip,
                advertised_data_port,
                confirmed=False,
                data_path=True,
                observed=False,
            )
            self._record_peer_path_locked(
                peer,
                observed_ip,
                advertised_data_port,
                confirmed=True,
                data_path=True,
                observed=True,
            )
            for hint in address_hints:
                self._record_peer_path_locked(
                    peer,
                    hint,
                    advertised_data_port,
                    confirmed=False,
                    data_path=True,
                    observed=False,
                )

            sender_ids = msg.get("sender_ids")
            if isinstance(sender_ids, (list, tuple, set)):
                peer.sender_ids = {
                    self._bounded_text(x, 128) for x in list(sender_ids)[:64] if self._bounded_text(x, 128)
                }
            sender_kinds = msg.get("sender_kinds")
            if isinstance(sender_kinds, dict):
                peer.sender_kinds = {
                    self._bounded_text(k, 128): self._bounded_text(v, 32)
                    for k, v in list(sender_kinds.items())[:64]
                    if self._bounded_text(k, 128) and self._bounded_text(v, 32)
                }
            allow_protocols = msg.get("allow_protocols")
            if isinstance(allow_protocols, (list, tuple, set)):
                peer.allow_protocols = {
                    self._bounded_text(x, 32) for x in list(allow_protocols)[:64]
                    if self._bounded_text(x, 32) in self.DEFAULT_PROTOCOLS
                }

            peer.public_ok = bool(msg.get("public_ok", False) and peer.public_ips)
            peer.gateway_ok = bool(msg.get("gateway_ok", False))
            peer.last_seen = now
            peer.online = True
            peer.hello_count += 1
            peer.last_discovery_rx_ts = now
            hello_id = self._bounded_text(msg.get("hello_id"), 128)
            if hello_id:
                peer.last_hello_id = hello_id
            peer.listen_ip = self._best_peer_ip_locked(peer)

            new_tuple = (
                peer.listen_ip,
                peer.data_port,
                peer.discovery_port,
                peer.host_name,
                tuple(sorted(peer.sender_ids)),
                tuple(sorted(peer.sender_kinds.items())),
                tuple(sorted(peer.candidate_ips)),
                tuple(sorted(peer.confirmed_ips)),
                tuple(sorted(getattr(peer, "observed_ips", set()))),
                tuple(sorted(peer.address_roles.items())),
                tuple(sorted(peer.private_ips)),
                tuple(sorted(peer.public_ips)),
                peer.passthrough_enabled,
                getattr(peer, "same_address_mode", False),
                peer.preferred_private_ip,
                peer.path_mode,
            )
            changed = new_tuple != old_tuple

        if is_new:
            self._log_evt(
                "peer",
                f"peer discovered node={node_id} host={peer.host_name} mode={peer.path_mode} "
                f"best={peer.listen_ip or '-'}:{peer.data_port} observed={sorted(peer.observed_ips)} "
                f"private={sorted(peer.private_ips)} public={sorted(peer.public_ips)}",
                ["🤝", "🌐", "✅"],
            )
        elif changed:
            self._log_evt(
                "peer",
                f"peer updated node={node_id} mode={peer.path_mode} best={peer.listen_ip or '-'}:{peer.data_port} "
                f"observed={sorted(peer.observed_ips)} private={sorted(peer.private_ips)} "
                f"public={sorted(peer.public_ips)} confirmed={sorted(peer.confirmed_ips)}",
                ["🔄", "🌐", "📝"],
            )

    def _send_hello_reply(self, hello_msg: dict, from_ip: str, from_port: int = 0) -> None:
        adv_ip = self._advertise_ip()
        msg = {
            "magic": self.MAGIC,
            "type": "hello_ack",
            "hello_id": self._bounded_text(hello_msg.get("hello_id"), 128),
            "node_id": self.node_id,
            "segment_id": self.segment_id,
            "host_name": self.host_name,
            "listen_ip": adv_ip,
            "reply_to_ip": adv_ip,
            "data_port": self._bound_data_port or self.data_port,
            "reply_data_port": self._bound_data_port or self.data_port,
            "discovery_port": self._bound_discovery_port or self.discovery_port,
            "reply_discovery_port": self._bound_discovery_port or self.discovery_port,
            "ts": time.time(),
        }
        msg.update(self._wire_identity_fields(adv_ip))
        raw = self._encode_wire_message(msg)

        peer_node_id = self._bounded_text(hello_msg.get("node_id") or hello_msg.get("src_node_id"), 128)
        peer_data_port = self._safe_port(
            hello_msg.get("reply_data_port") or hello_msg.get("data_port"), self.data_port
        )
        peer_discovery_port = self._safe_port(
            hello_msg.get("reply_discovery_port") or hello_msg.get("discovery_port"), self.discovery_port
        )
        observed = self._sanitize_peer_ip(from_ip)
        observed_port = self._safe_port(from_port, 0)

        with self._lock:
            peer = self._peers.get(peer_node_id)

        candidates: List[Tuple[str, int]] = []

        # First answer the exact socket tuple that sent the HELLO.  Discovery
        # transmit sockets are intentionally polled, so this works even when
        # the sender used an ephemeral source port.
        if (
                observed
                and observed_port
                and self._peer_transport_ip_allowed(peer, observed, discovery=True)
        ):
            candidates.append((observed, observed_port))

        # Then add the peer's stable control/data destination as a fallback.
        stable_port = peer_discovery_port if observed_port in {
            int(self.discovery_port), int(self._bound_discovery_port)
        } else peer_data_port
        if observed and stable_port:
            item = (observed, stable_port)
            if item not in candidates and self._peer_transport_ip_allowed(peer, observed, discovery=True):
                candidates.append(item)

        advertised = self._sanitize_peer_ip(
            hello_msg.get("reply_to_ip") or hello_msg.get("listen_ip") or hello_msg.get("advertised_ip")
        )
        if (
                advertised
                and stable_port
                and not self._is_unobserved_local_alias(advertised, observed)
                and self._advertised_fallback_plausible(observed, advertised, peer=peer)
        ):
            item = (advertised, stable_port)
            if item not in candidates:
                candidates.append(item)

        sent = 0
        for ip, port in candidates[:2]:
            if self._queue_network_message(
                    raw=raw,
                    ip=ip,
                    port=port,
                    mtype="hello_reply",
                    peer_node_id=peer_node_id,
            ):
                sent += 1

        if sent:
            self._stats["peer_discovery_reply"] = int(self._stats.get("peer_discovery_reply", 0)) + sent
            self._log_sparse(
                f"hello-reply:{from_ip}",
                "peer",
                f"hello reply queued node={peer_node_id or '?'} targets={candidates[:2]}",
                ["📡", "↩️", "✅"],
                every=3.0,
            )

    def _handle_remote_frame(
            self,
            msg: dict,
            from_ip: str,
            from_port: int,
            recv_sock: Optional[socket.socket] = None,
    ) -> None:
        frame_id = self._bounded_text(msg.get("frame_id") or msg.get("id"), 128)
        trace_id = self._bounded_text(msg.get("trace_id") or msg.get("trace"), 128)
        src_node_id = self._bounded_text(msg.get("src_node_id") or msg.get("node_id") or msg.get("peer_id"), 128)
        src_host_name = self._bounded_text(msg.get("src_host_name") or msg.get("host_name") or src_node_id, 255)
        src_sender_id = self._bounded_text(msg.get("src_sender_id") or msg.get("sender_id"), 128)
        protocol_tag = self._bounded_text(msg.get("protocol_tag") or msg.get("protocol") or msg.get("proto") or "RAW",
                                          32)
        if protocol_tag not in self.DEFAULT_PROTOCOLS:
            protocol_tag = "RAW"

        ack_targets = self._candidate_ack_targets_from_message(msg, from_ip, from_port, src_node_id)
        ack_ip = ack_targets[0][0] if ack_targets else ""
        ack_port = ack_targets[0][1] if ack_targets else 0

        if not src_node_id:
            return

        if self._is_remote_ingress_breaker_open():
            self._stats["remote_ingress_busy"] = int(self._stats.get("remote_ingress_busy", 0)) + 1
            self._stats["remote_ingress_breaker_drop"] = int(self._stats.get("remote_ingress_breaker_drop", 0)) + 1
            if ack_ip and ack_port and frame_id:
                self._send_frame_ack(
                    dst_ip=ack_ip,
                    dst_port=ack_port,
                    dst_node_id=src_node_id,
                    frame_id=frame_id,
                    status="busy",
                    detail=f"breaker_open=1 src_node={src_node_id} proto={protocol_tag}",
                    preferred_socket=recv_sock,
                )
            return

        self._note_peer_data_path(src_node_id, from_ip, from_port)
        raw = self._unpack_payload_bytes(msg)
        if raw is None:
            self._stats["remote_ingress_decode_fail"] = int(self._stats.get("remote_ingress_decode_fail", 0)) + 1
            if ack_ip and ack_port:
                self._send_frame_ack(
                    dst_ip=ack_ip,
                    dst_port=ack_port,
                    dst_node_id=src_node_id,
                    frame_id=frame_id or "-",
                    status="bad_frame",
                    detail="invalid, oversized, or corrupt payload",
                    preferred_socket=recv_sock,
                )
            return

        origin_node_id = self._bounded_text(msg.get("origin_node_id") or src_node_id, 128)
        origin_frame_id = self._bounded_text(msg.get("origin_frame_id") or frame_id, 128)
        content_hash = self._bounded_text(msg.get("content_hash") or msg.get("payload_sha256"), 128)
        if not origin_frame_id:
            origin_frame_id = hashlib.blake2b(
                origin_node_id.encode("utf-8", "ignore") + b"|" + raw,
                digest_size=16,
            ).hexdigest()

        if origin_node_id == self.node_id:
            if ack_ip and ack_port:
                self._send_frame_ack(
                    dst_ip=ack_ip,
                    dst_port=ack_port,
                    dst_node_id=src_node_id,
                    frame_id=frame_id or origin_frame_id,
                    status="observed",
                    detail="duplicate self-origin frame dropped",
                    preferred_socket=recv_sock,
                )
            return

        origin_key = f"{origin_node_id}|{origin_frame_id}"
        if self._remember_recent_value(
                self._recent_origin_frames,
                self._recent_origin_order,
                origin_key,
                ttl_sec=self.dedupe_ttl_sec * 2.0,
        ):
            if ack_ip and ack_port:
                self._send_frame_ack(
                    dst_ip=ack_ip,
                    dst_port=ack_port,
                    dst_node_id=src_node_id,
                    frame_id=frame_id or origin_frame_id,
                    status="observed",
                    detail="duplicate origin frame dropped",
                    preferred_socket=recv_sock,
                )
            return

        if content_hash and self._remember_recent_value(
                self._recent_content_hashes,
                self._recent_content_order,
                content_hash,
                ttl_sec=self.dedupe_ttl_sec,
        ):
            if ack_ip and ack_port:
                self._send_frame_ack(
                    dst_ip=ack_ip,
                    dst_port=ack_port,
                    dst_node_id=src_node_id,
                    frame_id=frame_id or origin_frame_id,
                    status="observed",
                    detail="duplicate content hash dropped",
                    preferred_socket=recv_sock,
                )
            return

        if not frame_id:
            frame_id = hashlib.blake2b(
                src_node_id.encode("utf-8", "ignore") + b"|" + raw,
                digest_size=16,
            ).hexdigest()

        duplicate_hint = False
        try:
            fp = self._fingerprint(raw, self.INBOUND_IFACE_NAME, protocol_tag, prefix=f"remote:{src_node_id}")
            duplicate_hint = bool(self._seen_recently(fp))
        except Exception:
            pass

        self._note_peer_frame_rx(src_node_id, len(raw))
        self._stats["remote_ingress_read"] = int(self._stats.get("remote_ingress_read", 0)) + 1

        pkt = self._decode_wire_packet(raw, protocol_tag)
        if pkt is None:
            self._stats["remote_ingress_decode_fail"] = int(self._stats.get("remote_ingress_decode_fail", 0)) + 1
            if ack_ip and ack_port:
                self._send_frame_ack(
                    dst_ip=ack_ip,
                    dst_port=ack_port,
                    dst_node_id=src_node_id,
                    frame_id=frame_id,
                    status="decode_failed",
                    detail="could not decode packet bytes",
                    preferred_socket=recv_sock,
                )
            return

        # Transport ACK semantics: once the HVRM envelope, payload hash, and
        # packet bytes have all validated, acknowledge immediately from the
        # exact UDP socket that received the frame.  Do not wait for the router
        # worker; router processing can be slower than the wire ACK timeout.
        transport_ack_sent = False
        if ack_ip and ack_port and frame_id:
            transport_ack_sent = self._send_frame_ack(
                dst_ip=ack_ip,
                dst_port=ack_port,
                dst_node_id=src_node_id,
                frame_id=frame_id,
                status="received",
                detail=(
                    f"transport_received=1 src_node={src_node_id} "
                    f"proto={protocol_tag} payload_len={len(raw)}"
                ),
                preferred_socket=recv_sock,
            )

        setattr(pkt, "_hyperv_remote_frame", True)
        setattr(pkt, "_hyperv_remote_node_id", src_node_id)
        setattr(pkt, "_hyperv_remote_host_name", src_host_name)
        setattr(pkt, "_hyperv_remote_sender_id", src_sender_id)
        setattr(pkt, "_hyperv_remote_trace_id", trace_id)
        setattr(pkt, "_hyperv_duplicate_hint", duplicate_hint)
        setattr(pkt, "sniffed_on", self.INBOUND_IFACE_NAME)

        _ = self._consult_hostboundary(pkt, self.INBOUND_IFACE_NAME)
        queued = self._enqueue_router_ingress(
            packet=pkt,
            raw=raw,
            frame_id=frame_id,
            trace_id=trace_id,
            src_node_id=src_node_id,
            src_host_name=src_host_name,
            src_sender_id=src_sender_id,
            protocol_tag=protocol_tag,
            duplicate_hint=duplicate_hint,
            reply_ip=ack_ip,
            reply_port=ack_port,
            success_notified=bool(transport_ack_sent),
        )
        if queued:
            self._stats["remote_ingress_queued"] = int(self._stats.get("remote_ingress_queued", 0)) + 1
            return

        self._stats["remote_ingress_failed"] = int(self._stats.get("remote_ingress_failed", 0)) + 1
        self._stats["remote_ingress_busy"] = int(self._stats.get("remote_ingress_busy", 0)) + 1
        if ack_ip and ack_port:
            self._send_frame_ack(
                dst_ip=ack_ip,
                dst_port=ack_port,
                dst_node_id=src_node_id,
                frame_id=frame_id,
                status="queue_full",
                detail=f"queue_full=1 src_node={src_node_id} proto={protocol_tag} payload_len={len(raw)}",
                preferred_socket=recv_sock,
            )

    def _handle_frame_ack(
            self,
            msg: dict,
            from_ip: str,
            from_port: int,
            *,
            which: str = "data",
    ) -> None:
        frame_id = self._bounded_text(msg.get("frame_id") or msg.get("id") or msg.get("ref"), 128)
        src_node_id = self._bounded_text(
            msg.get("src_node_id") or msg.get("node_id") or msg.get("peer_id") or msg.get("sender_node_id"),
            128,
        )
        if not frame_id or not src_node_id:
            return

        with self._pending_lock:
            pending = self._pending_frames.get(frame_id)
            if pending is None or str(pending.get("peer_node_id") or "") != src_node_id:
                self._stats["ack_unmatched"] = int(self._stats.get("ack_unmatched", 0)) + 1
                return

        raw_type = str(msg.get("type") or "").strip().lower()
        status = self._bounded_text(
            msg.get("status") or msg.get("ack_status") or msg.get("state") or msg.get(
                "result") or raw_type or "processed",
            32,
        ).lower()
        detail = self._bounded_text(msg.get("detail") or msg.get("message") or msg.get("reason"), 512)
        if status in {"ack", "frame_ack", "frame_status", "status"}:
            detail_l = detail.lower()
            if "processed" in detail_l:
                status = "processed"
            elif "busy" in detail_l:
                status = "busy"
            elif "queue_full" in detail_l:
                status = "queue_full"
            elif "observed" in detail_l:
                status = "observed"
            else:
                status = "processed"

        self._note_peer_ack(src_node_id)
        ack_transport = self._bounded_text(msg.get("ack_transport"), 32).lower()
        arrived_via_discovery = bool(which == "discovery" or ack_transport == "discovery-multicast")
        if arrived_via_discovery:
            # The multicast source port belongs to the discovery TX socket and
            # must never replace the peer's stable data port 47772.
            self._stats["ack_discovery_received"] = int(
                self._stats.get("ack_discovery_received", 0)
            ) + 1
        else:
            self._note_peer_data_path(src_node_id, from_ip, from_port)
        self._stats["ack_received"] = int(self._stats.get("ack_received", 0)) + 1
        terminal_success = {
            "received", "receipt", "queued", "processed", "observed",
            "ok", "success", "accepted",
        }
        terminal_failure = {"busy", "queue_full", "decode_failed", "bad_frame", "failed", "error"}

        with self._pending_lock:
            pending = self._pending_frames.get(frame_id)
            if pending is None:
                return
            pending["last_ack_status"] = status
            pending["last_ack_detail"] = detail
            pending["last_ack_ts"] = time.time()
            pending["acked_by"] = src_node_id
            pending["acked_from_ip"] = str(from_ip or "")
            pending["acked_from_port"] = int(from_port or 0)
            if status in terminal_success or status in terminal_failure:
                self._pending_frames.pop(frame_id, None)

        self._log_sparse(
            f"ack-rx:{src_node_id}:{status}:{which}",
            "ack",
            f"ack received frame={frame_id} peer={src_node_id} status={status} "
            f"via={which} source={from_ip}:{from_port}",
            ["✅", "📥", "🤝"],
            every=1.0,
        )

    def _make_frame_messages(
            self,
            *,
            frame_id: str,
            trace_id: str,
            protocol_tag: str,
            inbound_iface: str,
            raw: bytes,
            dst_sender_id: str,
    ) -> List[bytes]:
        payload_b64, payload_codec, payload_sha256 = self._pack_payload_bytes(bytes(raw or b""))
        payload_len = len(raw or b"")
        advertised_ip = self._advertise_ip()
        preferred_ack_port = int(self._bound_data_port or self.data_port or 0)
        source_sender_id = self._derive_source_sender_id(inbound_iface)
        origin_frame_id = str(frame_id or uuid.uuid4().hex)

        msg = {
            "magic": self.MAGIC,
            "type": "frame",
            "segment_id": self.segment_id,
            "ts": time.time(),
            "frame_id": origin_frame_id,
            "trace_id": trace_id,
            "protocol_tag": protocol_tag,
            "src_node_id": self.node_id,
            "src_host_name": self.host_name,
            "src_sender_id": source_sender_id,
            "dst_sender_id": dst_sender_id or "",
            "payload_b64": payload_b64,
            "payload_len": payload_len,
            "payload_sha256": str(payload_sha256 or ""),
            "payload_codec": payload_codec,
            "reply_ip": advertised_ip,
            "reply_port": preferred_ack_port,
            "reply_discovery_port": int(self._bound_discovery_port or self.discovery_port or 0),
            "origin_node_id": str(self.node_id or ""),
            "origin_frame_id": origin_frame_id,
            "content_hash": str(payload_sha256 or ""),
        }
        msg.update(self._wire_identity_fields(advertised_ip))
        return [self._encode_wire_message(msg)]

    def _make_frame_ack_messages(
            self,
            *,
            frame_id: str,
            status: str,
            detail: str = "",
            dst_node_id: str = "",
            ack_transport: str = "data",
    ) -> List[bytes]:
        advertised_ip = self._advertise_ip()
        msg = {
            "magic": self.MAGIC,
            "type": "ack",
            "segment_id": self.segment_id,
            "ts": time.time(),
            "node_id": self.node_id,
            "src_node_id": self.node_id,
            "src_host_name": self.host_name,
            "dst_node_id": self._bounded_text(dst_node_id, 128),
            "frame_id": frame_id,
            "status": status,
            "ack_transport": self._bounded_text(ack_transport, 32) or "data",
            "detail": detail,
            "reply_ip": advertised_ip,
            "reply_port": int(self._bound_data_port or self.data_port or 0),
        }
        msg.update(self._wire_identity_fields(advertised_ip))
        return [self._encode_wire_message(msg)]

    def _enqueue_remote(
            self,
            *,
            protocol_tag: str,
            raw: bytes,
            inbound_iface: str,
            dst_node_id: str,
            dst_sender_id: str,
    ) -> bool:
        if self._is_remote_ingress_breaker_open():
            return False

        with self._lock:
            peer = self._peers.get(str(dst_node_id))
            if peer is None or not peer.online:
                return False
            peer_host = peer.host_name
            peer_targets = self._candidate_peer_targets(peer)

        if not peer_targets:
            return False
        target_ip, target_port = peer_targets[0]

        frame_id = uuid.uuid4().hex
        trace_id = hashlib.blake2b(
            f"{self.node_id}|{dst_node_id}|{protocol_tag}|{len(raw)}|{time.time()}".encode("utf-8"),
            digest_size=8,
        ).hexdigest()
        raw_msg = self._make_frame_messages(
            frame_id=frame_id,
            trace_id=trace_id,
            protocol_tag=protocol_tag,
            inbound_iface=inbound_iface,
            raw=raw,
            dst_sender_id=dst_sender_id,
        )[0]

        with self._pending_lock:
            self._enforce_pending_frame_cap_locked()
            if len(self._pending_frames) >= self._pending_frame_cap:
                self._log_sparse(
                    f"pending-cap:{dst_node_id}",
                    "ack",
                    f"pending frame cap reached; dropping new frame peer={dst_node_id} proto={protocol_tag}",
                    ["⚠️", "📦", "🧯"],
                    every=2.0,
                )
                return False

            self._pending_frames[frame_id] = {
                "frame_id": frame_id,
                "trace_id": trace_id,
                "peer_node_id": dst_node_id,
                "peer_host_name": peer_host,
                "peer_ip": target_ip,
                "peer_port": target_port,
                "peer_targets": list(peer_targets),
                "target_index": 0,
                "attempted_targets": [(target_ip, target_port)],
                "dst_sender_id": dst_sender_id,
                "protocol_tag": protocol_tag,
                "created_ts": time.time(),
                "last_send_ts": 0.0,
                "retry_count": 0,
                "send_success_count": 0,
                "first_send_ok_ts": 0.0,
                "last_ack_status": "",
                "last_ack_detail": "",
                "raw_msg": raw_msg,
                "raw_messages": [raw_msg],
            }

        ok = self._queue_network_message(
            raw=raw_msg,
            ip=target_ip,
            port=target_port,
            mtype="frame",
            peer_node_id=dst_node_id,
            frame_id=frame_id,
            trace_id=trace_id,
            protocol_tag=protocol_tag,
            dst_sender_id=dst_sender_id,
        )
        if not ok:
            with self._pending_lock:
                self._pending_frames.pop(frame_id, None)
        return ok

    def _send_frame_ack(
            self,
            *,
            dst_ip: str,
            dst_port: int,
            dst_node_id: str,
            frame_id: str,
            status: str,
            detail: str = "",
            preferred_socket: Optional[socket.socket] = None,
    ) -> bool:
        """
        Send a transport ACK back to the exact recvfrom() tuple.

        The preferred socket is normally the socket that received the frame.
        Reusing it preserves the source IP and source port expected by the
        sender, survives NAT/IP-passthrough translation, and avoids waiting on
        the normal network queue.  Stable learned peer paths remain fallbacks.
        """
        ip = self._sanitize_peer_ip(dst_ip)
        port = self._safe_port(dst_port, 0)
        if not ip or not port or not frame_id:
            return False

        raws = self._make_frame_ack_messages(
            frame_id=frame_id,
            status=status,
            detail=detail,
            dst_node_id=dst_node_id,
            ack_transport="data",
        )
        if not raws:
            return False

        raw_ack = raws[0]

        direct_sent = False

        # First choice: reply synchronously from the exact receiving socket.
        # The incoming frame has already passed envelope/auth/source checks.
        if preferred_socket is not None:
            try:
                with self._sock_lock:
                    source_ip = self._socket_source_ips.get(id(preferred_socket), "")
                    try:
                        local_name = preferred_socket.getsockname()
                        local_ip = self._sanitize_peer_ip(local_name[0])
                        local_port = int(local_name[1])
                    except Exception:
                        local_ip = ""
                        local_port = int(self._bound_data_port or self.data_port)

                    if not source_ip or source_ip == "0.0.0.0":
                        source_ip = local_ip or self._route_selected_source_ip(ip) or self._advertise_ip()
                    source_port = local_port or int(self._bound_data_port or self.data_port)
                    direct_raw = self._retarget_wire_source_metadata(
                        raw_ack, source_ip=source_ip, source_port=source_port
                    )
                    preferred_socket.sendto(direct_raw, (ip, port))

                direct_sent = True
                self._stats["ack_direct_sent"] = int(self._stats.get("ack_direct_sent", 0)) + 1
                self._log_sparse(
                    f"ack-direct:{dst_node_id}:{status}",
                    "ack",
                    f"ack sent frame={frame_id} peer={dst_node_id or '?'} "
                    f"target={ip}:{port} source={source_ip or '-'}:{source_port} status={status}",
                    ["✅", "↩️", "📡"],
                    every=2.0,
                )
            except Exception as e:
                self._stats["ack_direct_failed"] = int(self._stats.get("ack_direct_failed", 0)) + 1
                self._log_sparse(
                    f"ack-direct-fail:{dst_node_id}:{ip}:{port}",
                    "ack",
                    f"direct ack failed frame={frame_id} peer={dst_node_id or '?'} "
                    f"target={ip}:{port}: {type(e).__name__}: {e}",
                    ["⚠️", "↩️", "🧯"],
                    every=2.0,
                )

        # UDP sendto() success only means the datagram entered the local stack.
        # It does not prove that a private LAN peer can route back to an AT&T
        # passthrough public IP. Publish a second, node-targeted ACK over the
        # discovery multicast path. The sender accepts it only when node_id and
        # random outstanding frame_id both match.
        discovery_sent = False
        if self._ack_discovery_fallback_enabled and (
                self._ack_discovery_redundant or not direct_sent
        ):
            discovery_sent = self._send_frame_ack_over_discovery(
                dst_node_id=dst_node_id,
                frame_id=frame_id,
                status=status,
                detail=detail,
            )

        if direct_sent or discovery_sent:
            return True

        # Final compatibility fallback: exact source tuple first, then the
        # learned stable data path through the ordinary network queue.
        targets: List[Tuple[str, int]] = [(ip, port)]
        for target in self._candidate_reply_targets(
                dst_node_id=dst_node_id, dst_ip=ip, dst_port=port
        ):
            if target not in targets:
                targets.append(target)

        queued = False
        for target_ip, target_port in targets[: max(2, int(self._ack_target_limit or 1))]:
            if self._queue_network_message(
                    raw=raw_ack,
                    ip=target_ip,
                    port=target_port,
                    mtype="ack",
                    peer_node_id=dst_node_id,
                    frame_id=frame_id,
                    status=status,
            ):
                queued = True
                self._stats["ack_fallback_queued"] = int(self._stats.get("ack_fallback_queued", 0)) + 1
                break
        return queued

    def _send_frame_ack_over_discovery(
            self,
            *,
            dst_node_id: str,
            frame_id: str,
            status: str,
            detail: str = "",
    ) -> bool:
        """Send a node-targeted ACK over the working discovery multicast LAN."""
        dst_node_id = self._bounded_text(dst_node_id, 128)
        frame_id = self._bounded_text(frame_id, 128)
        if not dst_node_id or not frame_id:
            return False

        raws = self._make_frame_ack_messages(
            frame_id=frame_id,
            status=status,
            detail=detail,
            dst_node_id=dst_node_id,
            ack_transport="discovery-multicast",
        )
        if not raws:
            return False
        raw_ack = raws[0]

        with self._sock_lock:
            tx_paths = list(self._discovery_tx_socks.items())
            if not tx_paths and self._discovery_tx_sock is not None:
                tx_paths = [(
                    self._socket_source_ips.get(id(self._discovery_tx_sock), "0.0.0.0"),
                    self._discovery_tx_sock,
                )]

        sent = 0
        used_socket_ids: Set[int] = set()
        for source_hint, sock_obj in tx_paths:
            if sock_obj is None or id(sock_obj) in used_socket_ids:
                continue
            used_socket_ids.add(id(sock_obj))
            if sent >= max(1, int(self._ack_discovery_target_limit or 1)):
                break
            try:
                try:
                    local_name = sock_obj.getsockname()
                    local_ip = self._sanitize_peer_ip(local_name[0])
                    local_port = int(local_name[1])
                except Exception:
                    local_ip = ""
                    local_port = 0
                source_ip = self._sanitize_peer_ip(source_hint) or local_ip or self._advertise_ip()
                wire = self._retarget_wire_source_metadata(
                    raw_ack,
                    source_ip=source_ip,
                    source_port=local_port or int(self.discovery_port),
                )
                sock_obj.sendto(wire, (self.discovery_group, int(self.discovery_port)))
                sent += 1
            except Exception as e:
                self._log_sparse(
                    f"ack-discovery-send-fail:{dst_node_id}:{source_hint}",
                    "ack",
                    f"discovery ACK send failed frame={frame_id} peer={dst_node_id} "
                    f"source={source_hint or '-'}: {type(e).__name__}: {e}",
                    ["⚠️", "📡", "🧯"],
                    every=3.0,
                )

        if sent:
            self._stats["ack_discovery_sent"] = int(self._stats.get("ack_discovery_sent", 0)) + sent
            self._log_sparse(
                f"ack-discovery:{dst_node_id}:{status}",
                "ack",
                f"discovery ACK sent frame={frame_id} peer={dst_node_id} "
                f"group={self.discovery_group}:{self.discovery_port} paths={sent} status={status}",
                ["✅", "📡", "↩️"],
                every=2.0,
            )
        return sent > 0

    def _candidate_ack_targets_from_message(
            self,
            msg: dict,
            from_ip: str,
            from_port: int,
            src_node_id: str,
    ) -> List[Tuple[str, int]]:
        """Return ACK targets with the exact recvfrom() tuple first."""
        out: List[Tuple[str, int]] = []
        observed_ip = self._sanitize_peer_ip(from_ip)
        observed_source_port = self._safe_port(from_port, 0)

        with self._lock:
            peer = self._peers.get(str(src_node_id)) if src_node_id else None
            peer_data_port = self._safe_port(
                getattr(peer, "data_port", 0) if peer is not None else 0,
                self._bound_data_port or self.data_port,
            )

        hinted_port = self._safe_port(
            msg.get("reply_port") or msg.get("ack_port") or msg.get("reply_data_port") or msg.get("src_data_port"),
            peer_data_port,
        )

        # _handle_wire_message() has already validated this frame source.
        # Therefore the exact recvfrom() tuple is authoritative for its ACK,
        # even when it is a public IP seen through IP Passthrough/NAT.
        if observed_ip:
            if observed_source_port:
                out.append((observed_ip, observed_source_port))
            if hinted_port:
                item = (observed_ip, hinted_port)
                if item not in out:
                    out.append(item)
            if peer_data_port:
                item = (observed_ip, peer_data_port)
                if item not in out:
                    out.append(item)

        hinted_ip = self._sanitize_peer_ip(msg.get("reply_ip") or msg.get("reply_to_ip") or msg.get("ack_ip"))
        if (
                hinted_ip
                and hinted_port
                and not self._is_unobserved_local_alias(hinted_ip, observed_ip)
                and self._peer_knows_ip(src_node_id, hinted_ip)
        ):
            item = (hinted_ip, hinted_port)
            if self._peer_transport_ip_allowed(peer, hinted_ip, discovery=False) and item not in out:
                out.append(item)

        for item in self._candidate_reply_targets(
                dst_node_id=src_node_id,
                dst_ip=observed_ip,
                dst_port=observed_source_port or peer_data_port,
        ):
            if item not in out:
                out.append(item)

        return out[: max(2, int(self._ack_target_limit or 1))]

    def _candidate_reply_targets(
            self,
            *,
            dst_node_id: str,
            dst_ip: str,
            dst_port: int,
    ) -> List[Tuple[str, int]]:
        """
        Prefer the exact source tuple supplied by recvfrom().  This is required
        for NAT-translated and same-address IP-passthrough traffic.  Learned
        stable peer paths are only fallbacks.
        """
        out: List[Tuple[str, int]] = []
        supplied_ip = self._sanitize_peer_ip(dst_ip)
        supplied_port = self._safe_port(dst_port, 0)

        with self._lock:
            peer = self._peers.get(str(dst_node_id)) if dst_node_id else None
            peer_targets = self._candidate_peer_targets(peer) if peer is not None else []
            peer_data_port = self._safe_port(
                getattr(peer, "data_port", 0) if peer is not None else 0,
                self._bound_data_port or self.data_port,
            )

        if (
                supplied_ip
                and supplied_port
                and self._peer_transport_ip_allowed(peer, supplied_ip, discovery=False)
        ):
            out.append((supplied_ip, supplied_port))

        if supplied_ip and peer_data_port and self._peer_transport_ip_allowed(peer, supplied_ip, discovery=False):
            item = (supplied_ip, peer_data_port)
            if item not in out:
                out.append(item)

        for item in peer_targets:
            if item not in out:
                out.append(item)

        return out[: max(2, int(self._ack_target_limit or 1))]

    def _candidate_peer_targets(self, peer: _Peer) -> List[Tuple[str, int]]:
        if peer is None:
            return []

        now = time.time()
        observed_ips = set(getattr(peer, "observed_ips", set()) or set())
        observed_ports = dict(getattr(peer, "observed_data_ports", {}) or {})
        candidates: List[Tuple[int, str, int]] = []

        ips: Set[str] = set(peer.candidate_ips.keys())
        ips.update(peer.private_ips)
        ips.update(peer.public_ips)
        ips.update(observed_ips)
        for ip in (
                peer.preferred_private_ip,
                peer.last_success_ip,
                peer.last_data_from_ip,
                getattr(peer, "last_observed_ip", ""),
                peer.listen_ip,
                peer.last_hello_from_ip,
                peer.advertised_ip,
        ):
            if ip:
                ips.add(str(ip))

        has_observed = any(
            self._sanitize_peer_ip(ip)
            and self._peer_transport_ip_allowed(peer, ip, discovery=False)
            for ip in observed_ips
        )

        for raw_ip in ips:
            ip = self._sanitize_peer_ip(raw_ip)
            if not ip or not self._peer_transport_ip_allowed(peer, ip, discovery=False):
                continue

            # A peer cannot be reached by sending to one of this machine's own
            # addresses.  This specifically rejects a shared AT&T WAN address
            # advertised by every LAN computer.
            if self._is_unobserved_local_alias(ip, "" ) and ip not in observed_ips:
                continue

            seen_ts = float(peer.candidate_ips.get(ip, 0.0) or 0.0)
            if seen_ts and (now - seen_ts) > float(self._peer_path_ttl_sec):
                continue

            port = self._safe_port(peer.data_port, self.data_port)
            if ip == peer.last_data_from_ip and int(peer.last_data_from_port or 0) > 0:
                port = int(peer.last_data_from_port)
            elif ip == peer.last_success_ip and int(peer.last_success_port or 0) > 0:
                port = int(peer.last_success_port)
            elif int(observed_ports.get(ip, 0) or 0) > 0:
                port = int(observed_ports[ip])
            elif int(peer.candidate_data_ports.get(ip, 0) or 0) > 0:
                port = int(peer.candidate_data_ports[ip])
            if not (1 <= port <= 65535):
                continue

            score = self._local_path_affinity_score(ip)
            if ip in peer.confirmed_ips:
                score += 2400
            if ip in observed_ips:
                score += 2200
            if ip == peer.last_success_ip:
                score += 1900
            if ip == peer.last_data_from_ip:
                score += 1800
            if ip == getattr(peer, "last_observed_ip", ""):
                score += 1650
            if ip == peer.last_hello_from_ip:
                score += 1500
            if ip == peer.preferred_private_ip:
                score += 450
            if ip == peer.listen_ip:
                score += 300
            if ip == peer.advertised_ip:
                score += 75
            if self._is_private_ipv4(ip):
                score += 300 if self._prefer_private_lan_paths else 75
            elif peer.public_ok or peer.passthrough_enabled or getattr(peer, "same_address_mode", False):
                score += 125

            if (
                    has_observed
                    and ip not in observed_ips
                    and ip not in peer.confirmed_ips
                    and ip != peer.last_success_ip
            ):
                # Once a valid packet has actually been observed from a peer,
                # do not rotate ACK retries into merely advertised Hyper-V,
                # WSL, APIPA, or shared-WAN hints.
                continue

            score += min(250, int(peer.path_successes.get(ip, 0) or 0) * 25)
            score -= min(1200, int(peer.path_failures.get(ip, 0) or 0) * 150)
            if seen_ts:
                score += max(0, int(90 - (now - seen_ts)))
            candidates.append((score, ip, port))

        candidates.sort(key=lambda x: (x[0], x[1], x[2]), reverse=True)
        out: List[Tuple[str, int]] = []
        for _, ip, port in candidates:
            item = (ip, port)
            if item not in out:
                out.append(item)
        return out[: max(1, int(self._peer_target_limit or 1))]

    def _can_assume_delivery(self, info: Dict[str, Any], now: Optional[float] = None) -> bool:
        return False

    def _complete_pending_frames_for_peer(self, node_id: str, *, reason: str, min_age_sec: float = 0.0) -> int:
        return 0

    def _drop_queued_network_item(self, *, prefer_frame: bool = True) -> Optional[Dict[str, Any]]:
        q = self._net_tx_q
        victim = None
        try:
            with q.mutex:
                items = list(q.queue)
                if not items:
                    return None
                index = None
                if prefer_frame:
                    for i, candidate in enumerate(items):
                        if isinstance(candidate, dict) and str(candidate.get("mtype") or "") == "frame":
                            index = i
                            break
                if index is None:
                    index = 0
                victim = items.pop(index)
                q.queue.clear()
                q.queue.extend(items)
                if q.unfinished_tasks > 0:
                    q.unfinished_tasks -= 1
                q.not_full.notify()
        except Exception:
            return None

        if isinstance(victim, dict):
            frame_id = str(victim.get("frame_id") or "")
            if frame_id:
                with self._pending_lock:
                    self._pending_frames.pop(frame_id, None)
            return victim
        return None

    def _queue_network_message(
            self,
            *,
            raw: bytes,
            ip: str,
            port: int,
            mtype: str,
            peer_node_id: str = "",
            frame_id: str = "",
            trace_id: str = "",
            status: str = "",
            protocol_tag: str = "",
            dst_sender_id: str = "",
    ) -> bool:
        item = {
            "raw": raw,
            "ip": str(ip),
            "port": int(port),
            "mtype": str(mtype),
            "peer_node_id": str(peer_node_id),
            "frame_id": str(frame_id),
            "trace_id": str(trace_id),
            "status": str(status),
            "protocol_tag": str(protocol_tag),
            "dst_sender_id": str(dst_sender_id),
            "queued_ts": time.monotonic(),
        }

        try:
            self._net_tx_q.put_nowait(item)
            return True
        except queue.Full:
            self._stats["peer_send_queue_full"] = int(self._stats.get("peer_send_queue_full", 0)) + 1
            # ACK/hello control must not be trapped behind stale mirrored frames.
            # For frame traffic, replace the oldest queued frame so current
            # packets continue moving instead of freezing on an old backlog.
            control = str(mtype) in {"ack", "hello", "hello_ack", "hello_reply"}
            victim = self._drop_queued_network_item(prefer_frame=True)
            if victim is not None:
                try:
                    self._net_tx_q.put_nowait(item)
                    self._stats["peer_send_queue_replaced"] = int(self._stats.get("peer_send_queue_replaced", 0)) + 1
                    return True
                except queue.Full:
                    pass

            self._log_sparse(
                f"net-q-full:{mtype}",
                "network",
                f"network queue full; dropping mtype={mtype} peer={peer_node_id or '-'} ip={ip}:{port}",
                ["⚠️", "📤", "🧯"],
                every=2.0,
            )
            return False

    def _send_network_item_inline(self, item: Dict[str, Any]) -> bool:
        ip = self._sanitize_peer_ip(item.get("ip"))
        port = self._safe_port(item.get("port"), 0)
        mtype = str(item.get("mtype") or "")
        peer_node_id = str(item.get("peer_node_id") or "")
        frame_id = str(item.get("frame_id") or "")
        is_discovery = bool(
            mtype in {"hello", "hello_reply"}
            or port == self.discovery_port
            or port == self._bound_discovery_port
        )

        if not ip or port <= 0:
            return False

        with self._lock:
            peer = self._peers.get(peer_node_id) if peer_node_id else None
        if not self._peer_transport_ip_allowed(peer, ip, discovery=is_discovery):
            return False

        with self._sock_lock:
            sock_obj, source_ip = self._select_transport_socket(ip, mtype, discovery=is_discovery)
            source_port = 0
            if sock_obj is not None:
                try:
                    source_port = int(sock_obj.getsockname()[1])
                except Exception:
                    source_port = int(self._bound_data_ports_by_ip.get(source_ip, self.data_port))

        if sock_obj is None:
            return False
        if not self._router_runtime_ready():
            return False
        route_ready, route_reason = self._target_route_ready(
            source_ip,
            ip,
            port,
            discovery=is_discovery,
        )
        if not route_ready:
            self._stats["peer_send_route_deferred"] = int(
                self._stats.get("peer_send_route_deferred", 0)
            ) + 1
            self._log_sparse(
                f"route-deferred:{source_ip}:{ip}",
                "network",
                f"peer send deferred until route exists source={source_ip or '-'} "
                f"target={ip}:{port} reason={route_reason}",
                ["⏳", "🧭", "🌐"],
                every=3.0,
            )
            return False

        attempt_ts = time.time()
        if mtype == "frame" and frame_id:
            with self._pending_lock:
                pending = self._pending_frames.get(frame_id)
                if pending is not None:
                    pending["last_send_ts"] = attempt_ts
                    pending["last_source_ip"] = source_ip
                    pending["last_target_ip"] = ip
                    pending["last_target_port"] = port
                    attempted = list(pending.get("attempted_targets") or [])
                    target_key = (ip, port)
                    if target_key not in attempted:
                        attempted.append(target_key)
                    pending["attempted_targets"] = attempted[-8:]

        raw_to_send = self._retarget_wire_source_metadata(
            bytes(item.get("raw") or b""), source_ip=source_ip, source_port=source_port
        )
        if not raw_to_send:
            return False

        try:
            sock_obj.sendto(raw_to_send, (ip, port))
            self._stats["peer_send_inline"] += 1
            self._stats["peer_send_ok"] += 1
            if self._is_private_ipv4(ip):
                self._stats["hybrid_private_send"] = int(self._stats.get("hybrid_private_send", 0)) + 1
            else:
                self._stats["hybrid_public_send"] = int(self._stats.get("hybrid_public_send", 0)) + 1

            if mtype == "frame":
                self._note_peer_frame_tx(peer_node_id, len(raw_to_send))
                with self._pending_lock:
                    pending = self._pending_frames.get(frame_id)
                    if pending is not None:
                        now_ts = time.time()
                        pending["last_send_ts"] = now_ts
                        pending["last_source_ip"] = source_ip
                        pending["last_target_ip"] = ip
                        pending["last_target_port"] = port
                        pending["send_success_count"] = int(pending.get("send_success_count", 0)) + 1
                        pending["last_send_error"] = ""
                        if float(pending.get("first_send_ok_ts", 0.0) or 0.0) <= 0.0:
                            pending["first_send_ok_ts"] = now_ts
            return True
        except Exception as e:
            self._stats["peer_send_fail"] += 1
            if self._is_transport_socket_error(e):
                code = self._transport_socket_error_code(e)
                if code in {errno.ENETUNREACH, errno.EHOSTUNREACH, 10051, 10064, 10065}:
                    self._route_probe_cache[(str(source_ip or ""), str(ip))] = (
                        False,
                        time.monotonic(),
                        f"send-route-error={code}",
                    )
                else:
                    self._request_socket_reopen(
                        f"send:{source_ip or '-'}:{code}"
                    )
            if peer_node_id:
                self._note_peer_path_failure(peer_node_id, ip)
            if mtype == "frame" and frame_id:
                with self._pending_lock:
                    pending = self._pending_frames.get(frame_id)
                    if pending is not None:
                        pending["last_send_ts"] = time.time()
                        pending["last_send_error"] = f"{type(e).__name__}: {e}"
            self._log_sparse(
                f"network-send-fail:{source_ip}:{ip}:{port}",
                "network",
                f"peer send failed source={source_ip or '-'} target={ip}:{port}: {type(e).__name__}: {e}",
                ["⚠️", "🌐", "🧯"],
                every=3.0,
            )
            return False

    def _prune_peers(self) -> None:
        now = time.time()
        offline_logs: List[Tuple[str, str, str, int]] = []

        with self._lock:
            for peer in self._peers.values():
                was_online = peer.online
                peer.online = (now - peer.last_seen) <= self.peer_timeout_sec
                if was_online and not peer.online:
                    offline_logs.append((peer.node_id, peer.host_name, peer.listen_ip, peer.data_port))

        for node_id, host_name, ip, port in offline_logs:
            self._log_evt("peer", f"peer offline node={node_id} host={host_name} listen={ip}:{port}", ["⚠️", "🌐", "💤"])

    def _retry_pending_frames(self) -> None:
        now = time.time()

        # Refresh peer targets before taking pending_lock so lock order remains
        # self._lock -> pending_lock nowhere in this method.
        fresh_targets: Dict[str, List[Tuple[str, int]]] = {}
        with self._lock:
            for node_id, peer in self._peers.items():
                fresh_targets[node_id] = list(self._candidate_peer_targets(peer))

        retry_items: List[Dict[str, Any]] = []
        expired: List[Dict[str, Any]] = []
        failed_paths: List[Tuple[str, str]] = []

        with self._pending_lock:
            for frame_id, info in list(self._pending_frames.items()):
                last_send_ts = float(info.get("last_send_ts", 0.0) or 0.0)
                retry_count = int(info.get("retry_count", 0) or 0)
                if last_send_ts <= 0.0:
                    continue
                if (now - last_send_ts) < self._frame_ack_timeout_sec:
                    continue
                if retry_count >= self._frame_retry_limit:
                    expired.append(dict(info))
                    self._pending_frames.pop(frame_id, None)
                    continue

                node_id = str(info.get("peer_node_id") or "")
                current = (
                    str(info.get("peer_ip") or ""),
                    int(info.get("peer_port") or 0),
                )
                if current[0]:
                    failed_paths.append((node_id, current[0]))

                targets = list(fresh_targets.get(node_id) or info.get("peer_targets") or [])
                targets = [
                    (str(ip), int(port)) for ip, port in targets
                    if self._sanitize_peer_ip(ip) and 1 <= int(port or 0) <= 65535
                ]
                if not targets and current[0] and current[1] > 0:
                    targets = [current]
                if not targets:
                    expired.append(dict(info))
                    self._pending_frames.pop(frame_id, None)
                    continue

                attempted = [tuple(x) for x in list(info.get("attempted_targets") or []) if len(tuple(x)) == 2]
                next_target = next((target for target in targets if target not in attempted), None)
                if next_target is None:
                    next_target = targets[0]

                target_ip, target_port = next_target
                info["peer_targets"] = list(targets)
                info["target_index"] = targets.index(next_target) if next_target in targets else 0
                info["peer_ip"] = str(target_ip)
                info["peer_port"] = int(target_port)
                info["retry_count"] = retry_count + 1
                info["last_send_ts"] = now
                retry_items.append(dict(info))

        for node_id, ip in failed_paths:
            self._note_peer_path_failure(node_id, ip)

        for info in retry_items:
            self._stats["peer_send_retry"] += 1
            queued = self._queue_network_message(
                raw=bytes(info.get("raw_msg") or b""),
                ip=str(info.get("peer_ip") or ""),
                port=int(info.get("peer_port") or 0),
                mtype="frame",
                peer_node_id=str(info.get("peer_node_id") or ""),
                frame_id=str(info.get("frame_id") or ""),
                trace_id=str(info.get("trace_id") or ""),
                protocol_tag=str(info.get("protocol_tag") or ""),
                dst_sender_id=str(info.get("dst_sender_id") or ""),
            )
            self._log_sparse(
                f"ack-retry:{info.get('peer_node_id') or '?'}",
                "ack",
                f"retry frame={info.get('frame_id')} peer={info.get('peer_node_id') or '?'} "
                f"target={info.get('peer_ip')}:{info.get('peer_port')} "
                f"retry={info.get('retry_count')} queued={int(bool(queued))}",
                ["🔁", "📡", "🧭"],
                every=1.5,
            )

        for info in expired:
            self._log_sparse(
                f"ack-expire:{info.get('peer_node_id') or '?'}",
                "ack",
                f"frame ack timeout after send frame_id={info.get('frame_id')} "
                f"trace={info.get('trace_id') or '-'} peer={info.get('peer_node_id') or '?'} "
                f"ip={info.get('peer_ip')}:{info.get('peer_port')} "
                f"last_ack={info.get('last_ack_status') or '-'}",
                ["⌛", "📡", "⚠️"],
                every=1.5,
            )

    def _enqueue_router_ingress(
            self,
            *,
            packet,
            raw: bytes,
            frame_id: str,
            trace_id: str,
            src_node_id: str,
            src_host_name: str,
            src_sender_id: str,
            protocol_tag: str,
            duplicate_hint: bool,
            reply_ip: str = "",
            reply_port: int = 0,
            success_notified: bool = False,
    ) -> bool:
        if self._is_remote_ingress_breaker_open():
            self._stats["remote_ingress_busy"] = int(self._stats.get("remote_ingress_busy", 0)) + 1
            self._stats["remote_ingress_breaker_drop"] = int(self._stats.get("remote_ingress_breaker_drop", 0)) + 1
            return False

        try:
            item = _RouterIngressItem(
                packet=packet,
                raw=bytes(raw or b""),
                frame_id=str(frame_id or ""),
                trace_id=str(trace_id or ""),
                src_node_id=str(src_node_id or ""),
                src_host_name=str(src_host_name or ""),
                src_sender_id=str(src_sender_id or ""),
                protocol_tag=str(protocol_tag or "RAW"),
                duplicate_hint=bool(duplicate_hint),
                reply_ip=str(reply_ip or ""),
                reply_port=int(reply_port or 0),
                success_notified=bool(success_notified),
            )
            self._router_ingress_q.put_nowait(item)
            return True
        except queue.Full:
            self._stats["remote_ingress_queue_full"] = int(self._stats.get("remote_ingress_queue_full", 0)) + 1
            self._stats["remote_ingress_busy"] = int(self._stats.get("remote_ingress_busy", 0)) + 1
            try:
                old_item = self._router_ingress_q.get_nowait()
                try:
                    self._router_ingress_q.task_done()
                except Exception:
                    pass
                self._router_ingress_q.put_nowait(item)
                self._stats["remote_ingress_replaced_oldest"] = int(
                    self._stats.get("remote_ingress_replaced_oldest", 0)
                ) + 1
                return True
            except Exception:
                pass
            self._record_remote_ingress_queue_full(
                src_node_id=src_node_id,
                src_sender_id=src_sender_id,
                protocol_tag=protocol_tag,
                payload_len=len(raw or b""),
            )
            self._log_sparse(
                f"router-ingress-full:{src_node_id or '?'}:{protocol_tag}",
                "frame",
                f"router ingress queue full; dropping remote frame frame_id={frame_id} src_node={src_node_id} sender={src_sender_id or '-'} proto={protocol_tag} payload_len={len(raw or b'')}",
                ["⚠️", "📥", "🧯"],
                every=1.0,
            )
            return False
        except Exception as e:
            self._log_sparse(
                f"router-ingress-enqueue:{src_node_id or '?'}",
                "frame",
                f"failed queueing remote frame for router frame_id={frame_id} src_node={src_node_id}: {type(e).__name__}: {e}",
                ["⚠️", "📥", "🧯"],
                every=2.0,
            )
            return False

    def _router_ingress_loop(self) -> None:
        self._log_evt("worker", "router ingress worker started", ["🧵", "📥", "🧠"])
        while not self._stop_event.is_set():
            try:
                item = self._router_ingress_q.get(timeout=0.25)
            except queue.Empty:
                continue
            except Exception:
                if self._stop_event.wait(0.05):
                    break
                continue

            if item is None:
                break
            if not isinstance(item, _RouterIngressItem):
                continue

            now = time.time()
            if item.next_try_ts and item.next_try_ts > now:
                delay = min(0.25, max(0.01, item.next_try_ts - now))
                if self._stop_event.wait(delay):
                    break
                if not self._requeue_router_ingress_item(item):
                    self._stats["remote_ingress_failed"] = int(self._stats.get("remote_ingress_failed", 0)) + 1
                continue

            try:
                fed = bool(self._feed_packet_into_router(item.packet))
            except Exception as e:
                fed = False
                self._log_sparse(
                    f"router-ingress-ex:{item.src_node_id or '?'}",
                    "frame",
                    f"router ingress exception frame_id={item.frame_id} src_node={item.src_node_id}: {type(e).__name__}: {e}",
                    ["⚠️", "🧠", "🧯"],
                    every=2.0,
                )

            if fed:
                self._stats["remote_ingress_ok"] += 1
                if item.reply_ip and item.frame_id and not item.success_notified:
                    self._send_frame_ack(
                        dst_ip=item.reply_ip,
                        dst_port=item.reply_port,
                        dst_node_id=item.src_node_id,
                        frame_id=item.frame_id,
                        status="processed",
                        detail=(
                            f"router_ingest_ok=1 iface={self.INBOUND_IFACE_NAME} "
                            f"attempts={item.attempts} duplicate_hint={int(item.duplicate_hint)} payload_len={len(item.raw)}"
                        ),
                    )
                continue

            item.attempts += 1
            if item.attempts >= int(self._router_ingress_retry_limit or 3):
                self._stats["remote_ingress_failed"] = int(self._stats.get("remote_ingress_failed", 0)) + 1
                if item.reply_ip and item.frame_id:
                    self._send_frame_ack(
                        dst_ip=item.reply_ip,
                        dst_port=item.reply_port,
                        dst_node_id=item.src_node_id,
                        frame_id=item.frame_id,
                        status="busy",
                        detail=(
                            f"router_unavailable=1 final=1 iface={self.INBOUND_IFACE_NAME} "
                            f"attempts={item.attempts} duplicate_hint={int(item.duplicate_hint)} payload_len={len(item.raw)}"
                        ),
                    )
                continue

            self._stats["remote_ingress_requeued"] = int(self._stats.get("remote_ingress_requeued", 0)) + 1
            item.next_try_ts = time.time() + min(
                self._router_ingress_retry_cap_sec,
                self._router_ingress_retry_backoff_sec * max(1, item.attempts),
            )
            if not self._requeue_router_ingress_item(item):
                self._stats["remote_ingress_failed"] = int(self._stats.get("remote_ingress_failed", 0)) + 1
                if item.reply_ip and item.frame_id:
                    self._send_frame_ack(
                        dst_ip=item.reply_ip,
                        dst_port=item.reply_port,
                        dst_node_id=item.src_node_id,
                        frame_id=item.frame_id,
                        status="queue_full",
                        detail=(
                            f"router_requeue_failed=1 iface={self.INBOUND_IFACE_NAME} "
                            f"attempts={item.attempts} duplicate_hint={int(item.duplicate_hint)} payload_len={len(item.raw)}"
                        ),
                    )
                continue

    def _prune_pending_frames(self) -> None:
        now = time.time()
        expired: List[Dict[str, Any]] = []

        with self._pending_lock:
            for frame_id, info in list(self._pending_frames.items()):
                age = now - float(info.get("created_ts", now))
                if age > (self._frame_ack_timeout_sec * 2.0):
                    expired.append(info)
                    self._pending_frames.pop(frame_id, None)
            self._enforce_pending_frame_cap_locked()

        for info in expired:
            self._log_sparse(
                f"ack-timeout:{info.get('peer_node_id') or '?'}",
                "ack",
                f"frame ack timeout after send frame_id={info.get('frame_id')} trace={info.get('trace_id') or '-'} peer={info.get('peer_node_id') or '?'} ip={info.get('peer_ip')}:{info.get('peer_port')} last_ack={info.get('last_ack_status') or '-'}",
                ["⌛", "📡", "⚠️"],
                every=3.0,
            )

    def _prune_recent(self) -> None:
        now = time.time()
        cutoff = now - self.dedupe_ttl_sec

        # --------------------------------------------------
        # existing local fingerprint cache
        # --------------------------------------------------
        while self._recent_order:
            fp, ts = self._recent_order[0]
            if ts >= cutoff:
                break
            self._recent_order.popleft()
            if self._recent.get(fp) == ts:
                self._recent.pop(fp, None)

        while len(self._recent_order) > self.recent_cache_size:
            fp, ts = self._recent_order.popleft()
            if self._recent.get(fp) == ts:
                self._recent.pop(fp, None)

        # --------------------------------------------------
        # NEW: origin frame dedupe (cross-machine)
        # --------------------------------------------------
        while self._recent_origin_order:
            key, ts = self._recent_origin_order[0]
            if ts >= cutoff:
                break
            self._recent_origin_order.popleft()
            if self._recent_origin_frames.get(key) == ts:
                self._recent_origin_frames.pop(key, None)

        while len(self._recent_origin_order) > self.recent_cache_size:
            key, ts = self._recent_origin_order.popleft()
            if self._recent_origin_frames.get(key) == ts:
                self._recent_origin_frames.pop(key, None)

        # --------------------------------------------------
        # NEW: content hash dedupe (secondary safety)
        # --------------------------------------------------
        while self._recent_content_order:
            key, ts = self._recent_content_order[0]
            if ts >= cutoff:
                break
            self._recent_content_order.popleft()
            if self._recent_content_hashes.get(key) == ts:
                self._recent_content_hashes.pop(key, None)

        while len(self._recent_content_order) > self.recent_cache_size:
            key, ts = self._recent_content_order.popleft()
            if self._recent_content_hashes.get(key) == ts:
                self._recent_content_hashes.pop(key, None)

    def _note_peer_frame_rx(self, node_id: str, size_bytes: int) -> None:
        if not node_id:
            return
        with self._lock:
            peer = self._peers.get(node_id)
            if peer is None:
                return
            peer.rx_frames += 1
            peer.rx_bytes += int(size_bytes or 0)
            peer.last_frame_rx_ts = time.time()

    def _note_peer_frame_tx(self, node_id: str, size_bytes: int) -> None:
        if not node_id:
            return
        with self._lock:
            peer = self._peers.get(node_id)
            if peer is None:
                return
            peer.tx_frames += 1
            peer.tx_bytes += int(size_bytes or 0)
            peer.last_frame_tx_ts = time.time()

    def _note_peer_ack(self, node_id: str) -> None:
        if not node_id:
            return
        with self._lock:
            peer = self._peers.get(node_id)
            if peer is None:
                return
            peer.last_ack_ts = time.time()

    def _note_peer_data_path(self, node_id: str, from_ip: str, from_port: int = 0) -> None:
        ip = self._sanitize_peer_ip(from_ip)
        if not node_id or not ip:
            return
        with self._lock:
            peer = self._peers.get(str(node_id))
            if peer is None:
                return
            port = self._safe_port(from_port, peer.data_port or self.data_port)
            peer.last_data_from_ip = ip
            peer.last_data_from_port = port
            peer.last_success_ip = ip
            peer.last_success_port = port
            peer.last_observed_ip = ip
            peer.last_observed_port = port
            peer.path_successes[ip] = int(peer.path_successes.get(ip, 0) or 0) + 1
            peer.path_failures[ip] = 0
            self._record_peer_path_locked(
                peer,
                ip,
                port,
                confirmed=True,
                data_path=True,
                observed=True,
            )
            peer.listen_ip = self._best_peer_ip_locked(peer)

    def _classify_protocol(self, packet) -> Optional[str]:
        try:
            name = packet.__class__.__name__.upper()

            if "TCP" in name:
                return "TCP"
            if "UDP" in name:
                return "UDP"
            if name == "ICMP" or "ICMPV4" in name:
                return "ICMP"
            if "ICMPV6" in name:
                return "ICMPv6"
            if "ARP" in name:
                return "ARP"
            if "ISAKMP" in name:
                return "ISAKMP"
            if "IKEV2" in name:
                return "IKEv2"
            if "ESP" in name:
                return "ESP"
            if "AH" == name or name.endswith(".AH"):
                return "AH"
            if "GRE" in name:
                return "GRE"

            try:
                if Ether is not None and packet.haslayer(Ether):
                    return "ETHER"
            except Exception:
                pass
            try:
                if IP is not None and packet.haslayer(IP):
                    return "IP"
            except Exception:
                pass
            try:
                if IPv6 is not None and packet.haslayer(IPv6):
                    return "IPv6"
            except Exception:
                pass
        except Exception:
            pass
        return "RAW"

    def _packet_to_bytes(self, packet) -> bytes:
        try:
            return bytes(packet)
        except Exception:
            return b""

    def _decode_packet(self, raw: bytes):
        if not raw:
            return None

        if Ether is not None:
            try:
                pkt = Ether(raw)
                if pkt is not None:
                    return pkt
            except Exception:
                pass

        try:
            first = raw[0] >> 4
            if first == 4 and IP is not None:
                return IP(raw)
            if first == 6 and IPv6 is not None:
                return IPv6(raw)
        except Exception:
            pass

        if Raw is not None:
            try:
                return Raw(load=raw)
            except Exception:
                pass
        return None

    def _decode_wire_packet(self, raw: bytes, protocol_tag: str):
        proto = str(protocol_tag or "RAW").upper()
        proto = {
            "IPV4": "IP",
            "IPV6": "IPv6",
            "ICMPV6": "ICMPv6",
            "ETHERNET": "ETHER",
        }.get(proto, proto)

        if not raw:
            return None

        if proto == "ARP" and ARP is not None:
            try:
                return ARP(raw)
            except Exception:
                pass

        if proto in {"IP", "TCP", "UDP", "ICMP", "ESP", "AH", "GRE", "ISAKMP", "IKEV2"} and IP is not None:
            try:
                return IP(raw)
            except Exception:
                pass

        if proto in {"IPv6", "ICMPv6"} and IPv6 is not None:
            try:
                return IPv6(raw)
            except Exception:
                pass

        if proto == "ETHER" and Ether is not None:
            try:
                pkt = Ether(raw)
                if pkt is not None:
                    return pkt
            except Exception:
                pass
            try:
                nib = raw[0] >> 4
                if nib == 4 and IP is not None:
                    return IP(raw)
                if nib == 6 and IPv6 is not None:
                    return IPv6(raw)
            except Exception:
                pass

        return self._decode_packet(raw)

    def _feed_packet_into_router(self, packet) -> bool:
        tried_any = False

        def _call_ingest(target) -> bool:
            nonlocal tried_any
            for fn_name in (
                    "enqueue_ingress_packet",
                    "ingest_packet",
                    "process_packet",
                    "handle_packet",
                    "_process_packet",
                    "route_packet",
                    "ingest_packet",
                    "on_packet",
                    "receive_packet",
            ):
                fn = getattr(target, fn_name, None)
                if not callable(fn):
                    continue
                tried_any = True
                try:
                    called = False
                    try:
                        result = fn(packet, self.INBOUND_IFACE_NAME)
                        called = True
                    except TypeError:
                        result = None
                    if not called:
                        try:
                            result = fn(packet, inbound_iface=self.INBOUND_IFACE_NAME)
                            called = True
                        except TypeError:
                            result = None
                    if not called:
                        try:
                            result = fn(packet, iface_name=self.INBOUND_IFACE_NAME)
                            called = True
                        except TypeError:
                            result = None
                    if not called:
                        try:
                            result = fn(packet, source_iface=self.INBOUND_IFACE_NAME)
                            called = True
                        except TypeError:
                            result = None
                    if not called:
                        result = fn(packet)
                    if result is False:
                        continue
                    return True
                except Exception as e:
                    self._log_sparse(
                        f"router-process-fail:{fn_name}",
                        "frame",
                        f"router {fn_name} failed: {type(e).__name__}: {e}",
                        ["⚠️", "🧠", "🧯"],
                        every=2.0,
                    )
            return False

        router = self._resolve_router()
        if router is not None and _call_ingest(router):
            return True

        for obj in (self._windivert_manager, self._wintun_manager, self._hostboundary_manager,
                    *list(self._hyperv_managers.values())):
            if obj is None or obj is router:
                continue
            if _call_ingest(obj):
                return True

        if not tried_any:
            self._log_sparse(
                "router-resolve",
                "frame",
                "could not resolve any callable packet ingest path for remote packet feed",
                ["⚠️", "🧠", "🧯"],
                every=3.0,
            )
        else:
            self._log_sparse(
                "router-no-process",
                "frame",
                "remote frame was read locally but no ingest path accepted it",
                ["⚠️", "🧠", "🧯"],
                every=3.0,
            )
        return False

    def _resolve_router(self):
        if self._router_ref is not None:
            return self._router_ref

        candidates = [
                         self._windivert_manager,
                         self._wintun_manager,
                         self._hostboundary_manager,
                     ] + list(self._hyperv_managers.values())

        for obj in candidates:
            found = self._extract_router_from_object(obj)
            if found is not None:
                self._router_ref = found
                return found

        return None

    def _maybe_capture_router_ref(self, obj: Any) -> None:
        if self._router_ref is not None:
            return
        found = self._extract_router_from_object(obj)
        if found is not None:
            self._router_ref = found

    def _extract_router_from_object(self, obj: Any):
        if obj is None:
            return None

        for attr in ("router", "_router", "router_manager", "_router_manager", "parent_router"):
            try:
                cand = getattr(obj, attr, None)
                if cand is not None and (
                        callable(getattr(cand, "process_packet", None))
                        or callable(getattr(cand, "handle_packet", None))
                ):
                    return cand
            except Exception:
                pass

        if callable(getattr(obj, "process_packet", None)) or callable(getattr(obj, "handle_packet", None)):
            return obj
        return None

    # ---------------------------------------------------------
    # misc helpers
    # ---------------------------------------------------------

    def _make_udp_socket(self) -> socket.socket:
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM, socket.IPPROTO_UDP)
        s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        try:
            s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEPORT, 1)
        except Exception:
            pass
        try:
            s.setsockopt(socket.SOL_SOCKET, socket.SO_BROADCAST, 1)
        except Exception:
            pass
        try:
            s.setsockopt(socket.SOL_SOCKET, socket.SO_RCVBUF, 4 * 1024 * 1024)
        except Exception:
            pass
        try:
            s.setsockopt(socket.SOL_SOCKET, socket.SO_SNDBUF, 4 * 1024 * 1024)
        except Exception:
            pass
        return s

    def _is_addr_in_use_error(self, e: Exception) -> bool:
        if isinstance(e, OSError):
            return getattr(e, "errno", None) in {98, 10048}
        return False

    def _safe_socket_close(self, s: socket.socket) -> None:
        try:
            s.close()
        except Exception:
            pass

    def _coerce_bool(self, value: Any, default: bool = False) -> bool:
        if value is None:
            return bool(default)
        if isinstance(value, bool):
            return value
        if isinstance(value, (int, float)):
            return bool(value)
        text = str(value or "").strip().lower()
        if text in {"1", "true", "yes", "on", "enabled", "enable"}:
            return True
        if text in {"0", "false", "no", "off", "disabled", "disable", "none", "null"}:
            return False
        return bool(default)

    def _coerce_ip_list(self, value: Any) -> List[str]:
        if value is None:
            return []
        if isinstance(value, str):
            raw_values = value.replace(",", " ").replace(";", " ").split() if value.strip() else []
        elif isinstance(value, dict):
            raw_values = list(value.keys())
        elif isinstance(value, (list, tuple, set)):
            raw_values = list(value)
        else:
            raw_values = [value]
        out: List[str] = []
        for raw in raw_values:
            ip = self._sanitize_peer_ip(raw)
            if ip and ip not in out:
                out.append(ip)
        return out

    def _dedupe_usable_ips(self, values: Any) -> List[str]:
        out: List[str] = []
        if values is None:
            return out
        if isinstance(values, str):
            iterable = self._coerce_ip_list(values)
        else:
            try:
                iterable = list(values)
            except Exception:
                iterable = [values]
        for value in iterable:
            ip = self._sanitize_peer_ip(value)
            if ip and ip not in out:
                out.append(ip)
        return out

    def _discover_local_ipv4_addresses(self) -> List[str]:
        """
        Auto-discover only usable addresses on active, non-virtual interfaces.
        Hyper-V/WSL/TAP/APIPA addresses remain available when explicitly passed
        to configure(), but are not advertised automatically as peer paths.
        """
        preferred: List[str] = []
        fallback: List[str] = []

        try:
            import psutil  # type: ignore
            stats = psutil.net_if_stats()
            for iface_name, iface_addrs in psutil.net_if_addrs().items():
                iface_stat = stats.get(iface_name)
                if iface_stat is not None and not bool(getattr(iface_stat, "isup", False)):
                    continue
                virtual = self._is_probably_virtual_interface_name(iface_name)
                for addr in iface_addrs:
                    if getattr(addr, "family", None) != socket.AF_INET:
                        continue
                    ip = self._sanitize_peer_ip(getattr(addr, "address", ""))
                    if not ip:
                        continue
                    if virtual:
                        fallback.append(ip)
                    else:
                        preferred.append(ip)
        except Exception:
            pass

        # Hostname resolution is a fallback only; on Windows it commonly
        # returns a Hyper-V Default Switch address before the real adapter.
        if not preferred:
            try:
                _, _, addrs = socket.gethostbyname_ex(socket.gethostname())
                fallback.extend(addrs)
            except Exception:
                pass
            try:
                for info in socket.getaddrinfo(socket.gethostname(), None, socket.AF_INET, socket.SOCK_DGRAM):
                    fallback.append(str(info[4][0] or ""))
            except Exception:
                pass

        if preferred:
            return self._dedupe_usable_ips(preferred)
        if self._auto_detect_virtual_transport_ips:
            return self._dedupe_usable_ips(fallback)
        return []

    def _build_local_address_roles(
            self,
            local_ips: Any,
            *,
            public_ip: str = "",
            private_lan_ips: Optional[Any] = None,
            primary_ip: str = "",
    ) -> Dict[str, str]:
        public_ip = self._sanitize_peer_ip(public_ip)
        primary_ip = self._sanitize_peer_ip(primary_ip)
        explicit_private = set(self._coerce_ip_list(private_lan_ips))
        roles: Dict[str, str] = {}
        for ip in self._dedupe_usable_ips(local_ips):
            if public_ip and ip == public_ip:
                role = "passthrough-public"
            elif self._is_private_ipv4(ip):
                role = "lan-private" if ip in explicit_private else "private-local"
            else:
                role = "public-local"
            if ip == primary_ip:
                role = f"primary-{role}"
            roles[ip] = role
        return roles

    def _ordered_local_transport_ips(self) -> List[str]:
        with self._lock:
            ips = list(self._local_transport_roles.keys())
            primary = self._sanitize_peer_ip(self.bind_ip or self._primary_bind_ip)
        if primary and primary not in ips:
            ips.append(primary)

        def _rank(ip: str) -> Tuple[int, str]:
            if ip == primary:
                return (0, ip)
            if self._is_private_ipv4(ip):
                return (1, ip)
            return (2, ip)

        return sorted(self._dedupe_usable_ips(ips), key=_rank)

    def _has_hybrid_local_paths(self) -> bool:
        ips = self._ordered_local_transport_ips()
        has_private = any(self._is_private_ipv4(ip) for ip in ips)
        has_public = any(not self._is_private_ipv4(ip) for ip in ips)
        return bool(has_private and has_public)

    def _preferred_socket_alias(self, sockets: Dict[str, socket.socket]) -> Optional[socket.socket]:
        if not sockets:
            return None
        primary = self._sanitize_peer_ip(self.bind_ip or self._primary_bind_ip)
        if primary in sockets:
            return sockets[primary]
        for ip in self._ordered_local_transport_ips():
            if ip in sockets:
                return sockets[ip]
        return next(iter(sockets.values()))

    def _normalize_local_source_ip(self, source_ip: str, sock_obj: Optional[socket.socket] = None) -> str:
        ip = self._sanitize_peer_ip(source_ip)
        if ip:
            return ip
        if sock_obj is not None:
            try:
                ip = self._sanitize_peer_ip(sock_obj.getsockname()[0])
                if ip:
                    return ip
            except Exception:
                pass
        return self._advertise_ip()

    def _local_path_affinity_score(self, destination_ip: str) -> int:
        dst = self._sanitize_peer_ip(destination_ip)
        if not dst:
            return -100000
        score = 0
        local_ips = self._ordered_local_transport_ips()
        if self._is_private_ipv4(dst):
            score += 250 if self._prefer_private_lan_paths else 50
        for local_ip in local_ips:
            if self._same_ipv4_subnet(dst, local_ip):
                score = max(score, 1200)
            elif self._is_private_ipv4(dst) and self._is_private_ipv4(local_ip):
                score = max(score, 500)
            elif (not self._is_private_ipv4(dst)) and (not self._is_private_ipv4(local_ip)):
                score = max(score, 300)
            elif self._same_private_scope(dst, local_ip):
                score = max(score, 350)
        return score

    def _route_selected_source_ip(self, destination_ip: str) -> str:
        """Ask the OS routing table which local IPv4 source it would use."""
        destination_ip = self._sanitize_peer_ip(destination_ip)
        if not destination_ip:
            return ""
        now = time.monotonic()
        cached = self._route_source_cache.get(destination_ip)
        if cached and (now - float(cached[1])) <= float(self._route_source_cache_ttl_sec):
            return self._sanitize_peer_ip(cached[0])

        source_ip = ""
        probe: Optional[socket.socket] = None
        try:
            probe = socket.socket(socket.AF_INET, socket.SOCK_DGRAM, socket.IPPROTO_UDP)
            probe.connect((destination_ip, 9))
            source_ip = self._sanitize_peer_ip(probe.getsockname()[0])
        except Exception:
            source_ip = ""
        finally:
            if probe is not None:
                self._safe_socket_close(probe)

        self._route_source_cache[destination_ip] = (source_ip, now)
        if len(self._route_source_cache) > 256:
            oldest = sorted(self._route_source_cache.items(), key=lambda kv: kv[1][1])[:64]
            for key, _ in oldest:
                self._route_source_cache.pop(key, None)
        return source_ip

    def _select_transport_socket(
            self,
            destination_ip: str,
            mtype: str,
            *,
            discovery: bool = False,
    ) -> Tuple[Optional[socket.socket], str]:
        destination_ip = self._sanitize_peer_ip(destination_ip)
        socket_map = self._discovery_tx_socks if discovery else self._data_socks
        route_source = self._route_selected_source_ip(destination_ip) if destination_ip else ""

        if not socket_map:
            fallback = self._discovery_tx_sock or self._discovery_sock or self._data_sock
            if fallback is None:
                return None, ""
            fallback_source = route_source or self._socket_source_ips.get(id(fallback), "")
            return fallback, self._normalize_local_source_ip(fallback_source, fallback)

        # A wildcard data socket intentionally delegates interface/source
        # choice to Windows.  Retarget wire metadata to the route-selected
        # source rather than advertising 0.0.0.0.
        if "0.0.0.0" in socket_map:
            source_ip = route_source or self._advertise_ip()
            return socket_map["0.0.0.0"], source_ip

        if route_source in socket_map:
            return socket_map[route_source], route_source

        primary = self._sanitize_peer_ip(self.bind_ip or self._primary_bind_ip)

        def _score(item: Tuple[str, socket.socket]) -> Tuple[int, str]:
            source_ip, _ = item
            score = 0
            role = str(self._local_transport_roles.get(source_ip, "") or "")

            if route_source and source_ip == route_source:
                score += 10000
            if destination_ip and self._same_ipv4_subnet(source_ip, destination_ip):
                score += 7000
            if source_ip == primary:
                score += 3000
            if "passthrough-lan-wan" in role:
                score += 2600
            elif "passthrough-public" in role:
                score += 2200
            elif "lan-private" in role:
                score += 1800
            elif "private-local" in role:
                score += 300

            # Do not select an unrelated private virtual adapter simply because
            # the destination is private.  Same-subnet and OS-route evidence
            # above are required for a strong private-source preference.
            if destination_ip and self._is_private_ipv4(destination_ip):
                if self._same_ipv4_subnet(source_ip, destination_ip):
                    score += 2500
                elif source_ip == primary:
                    score += 1200
            elif destination_ip and not self._is_private_ipv4(destination_ip):
                if not self._is_private_ipv4(source_ip):
                    score += 1200

            return (score, source_ip)

        source_ip, sock_obj = max(socket_map.items(), key=_score)
        return sock_obj, source_ip

    def _wire_identity_fields(self, advertised_ip: str = "") -> Dict[str, Any]:
        advertised_ip = self._sanitize_peer_ip(advertised_ip) or self._advertise_ip()
        with self._lock:
            sender_ids = sorted(self._senders.keys())
            sender_kinds = {sid: self._senders[sid].kind for sid in self._senders}
            allow_protocols = sorted(
                set().union(*(sender.allow_protocols for sender in self._senders.values()))
                if self._senders else set()
            )
            cfg = dict(self._ip_passthrough_config)
            roles = dict(self._local_transport_roles)

        local_ips = self._passthrough_address_hints(advertised_ip)
        private_ips = [ip for ip in local_ips if self._is_private_ipv4(ip)]
        public_ips = [ip for ip in local_ips if not self._is_private_ipv4(ip)]
        preferred_private_ip = ""
        for ip in private_ips:
            if self._same_ipv4_subnet(ip, advertised_ip):
                preferred_private_ip = ip
                break
        if not preferred_private_ip and private_ips:
            preferred_private_ip = private_ips[0]

        public_ok, gateway_ok = self._passthrough_wire_flags()
        hybrid_mode = bool(private_ips and public_ips)
        same_address_mode = bool(cfg.get("same_address_mode", False))
        if same_address_mode:
            path_mode = "same-address"
        elif hybrid_mode:
            path_mode = "hybrid"
        elif public_ips:
            path_mode = "passthrough"
        else:
            path_mode = "lan"

        return {
            "sender_ids": sender_ids,
            "sender_kinds": sender_kinds,
            "allow_protocols": allow_protocols,
            "public_ok": bool(public_ok),
            "gateway_ok": bool(gateway_ok),
            "passthrough_enabled": bool(cfg.get("enabled", False)),
            "same_address_mode": same_address_mode,
            "path_mode": path_mode,
            "address_hints": local_ips,
            "address_roles": roles,
            "private_ips": private_ips,
            "public_ips": public_ips,
            "preferred_private_ip": preferred_private_ip,
            "observed_source_required_for_shared_public": True,
        }

    def _build_hello_message(
            self,
            *,
            hello_id: str,
            startup: bool,
            advertised_ip: str,
            advertised_discovery_port: int,
    ) -> Dict[str, Any]:
        advertised_ip = self._sanitize_peer_ip(advertised_ip) or self._advertise_ip()
        advertised_data_port = int(
            self._bound_data_ports_by_ip.get(advertised_ip, self._bound_data_port or self.data_port)
        )
        msg: Dict[str, Any] = {
            "magic": self.MAGIC,
            "type": "hello",
            "hello_id": hello_id,
            "expects_reply": True,
            "startup": bool(startup),
            "node_id": self.node_id,
            "segment_id": self.segment_id,
            "host_name": self.host_name,
            "listen_ip": advertised_ip,
            "reply_to_ip": advertised_ip,
            "data_port": advertised_data_port,
            "reply_data_port": advertised_data_port,
            "discovery_port": int(advertised_discovery_port),
            "reply_discovery_port": int(advertised_discovery_port),
            "ts": time.time(),
        }
        msg.update(self._wire_identity_fields(advertised_ip))
        return msg

    def _retarget_wire_source_metadata(self, raw: bytes, *, source_ip: str, source_port: int) -> bytes:
        source_ip = self._sanitize_peer_ip(source_ip)
        if not raw or not source_ip:
            return bytes(raw or b"")
        try:
            msg = json.loads(bytes(raw).decode("utf-8"))
        except Exception:
            return bytes(raw)
        if not isinstance(msg, dict) or str(msg.get("magic") or "") not in self.ACCEPT_MAGICS:
            return bytes(raw)

        mtype = str(msg.get("type") or "").strip().lower()
        identity = self._wire_identity_fields(source_ip)
        msg.update(identity)
        msg["source_path_ip"] = source_ip
        msg["reply_ip"] = source_ip
        if 1 <= int(source_port or 0) <= 65535:
            msg["reply_port"] = int(source_port)
        if mtype in {"hello", "hello_ack", "hello-response", "helloack"}:
            msg["listen_ip"] = source_ip
            msg["reply_to_ip"] = source_ip
            stable_data_port = int(self._bound_data_ports_by_ip.get(source_ip, self.data_port))
            msg["data_port"] = stable_data_port
            msg["reply_data_port"] = stable_data_port
        return self._encode_wire_message(msg)

    def _advertise_ip(self) -> str:
        local_ips = self._ordered_local_transport_ips()
        if self._prefer_private_lan_paths:
            for ip in local_ips:
                if self._is_private_ipv4(ip):
                    return ip
        primary = self._sanitize_peer_ip(self.bind_ip or self._primary_bind_ip)
        if primary:
            return primary
        if local_ips:
            return local_ips[0]

        discovered = self._discover_local_ipv4_addresses()
        for ip in discovered:
            if self._is_private_ipv4(ip):
                return ip
        return discovered[0] if discovered else "127.0.0.1"

    def _stable_flow_key(self, packet, inbound_iface: str, protocol_tag: str, raw: bytes) -> str:
        try:
            src = getattr(packet, "src", "") or ""
            dst = getattr(packet, "dst", "") or ""
            sport = getattr(packet, "sport", 0) or 0
            dport = getattr(packet, "dport", 0) or 0
            return f"{inbound_iface}|{protocol_tag}|{src}|{dst}|{sport}|{dport}"
        except Exception:
            return f"{inbound_iface}|{protocol_tag}|{hashlib.blake2b(raw, digest_size=8).hexdigest()}"

    def _quick_proto_from_raw(self, raw: bytes) -> str:
        pkt = self._decode_packet(raw)
        return self._classify_protocol(pkt) if pkt is not None else "RAW"

    def _fingerprint(self, raw: bytes, iface_name: str, protocol_tag: str, prefix: str = "pkt") -> str:
        h = hashlib.blake2b(digest_size=16)
        h.update(str(prefix).encode("utf-8", "ignore"))
        h.update(b"|")
        h.update(str(iface_name).encode("utf-8", "ignore"))
        h.update(b"|")
        h.update(str(protocol_tag).encode("utf-8", "ignore"))
        h.update(b"|")
        h.update(raw)
        return h.hexdigest()

    def _broadcast_fingerprint(self, raw: bytes, protocol_tag: str) -> str:
        h = hashlib.blake2b(digest_size=16)
        h.update(b"broadcast|")
        h.update(str(protocol_tag).encode("utf-8", "ignore"))
        h.update(b"|")
        h.update(raw)
        return h.hexdigest()

    def _seen_recently(self, fp: str) -> bool:
        now = time.time()
        prev = self._recent.get(fp)
        self._recent[fp] = now
        self._recent_order.append((fp, now))
        return prev is not None and (now - prev) <= self.dedupe_ttl_sec

    def _is_noisy_local_broadcast(self, packet) -> bool:
        try:
            dst = str(getattr(packet, "dst", "") or "").lower()
            if dst == "ff:ff:ff:ff:ff:ff":
                return True
            if dst.startswith("01:00:5e:"):
                return True
            if dst.startswith("33:33:"):
                return True
        except Exception:
            pass

        try:
            if ARP is not None and getattr(packet, "haslayer", None):
                if packet.haslayer(ARP):
                    return True
        except Exception:
            pass

        try:
            ip_dst = str(getattr(packet, "dst", "") or "")
            if ip_dst == "255.255.255.255":
                return True
            if ip_dst.startswith("224."):
                return True
            if ip_dst.lower().startswith("ff"):
                return True
        except Exception:
            pass

        return False

    def _packet_udp_ports(self, packet) -> Tuple[int, int]:
        sport = 0
        dport = 0
        try:
            if UDP is not None and getattr(packet, "haslayer", None) and packet.haslayer(UDP):
                udp_layer = packet.getlayer(UDP)
                if udp_layer is not None:
                    sport = int(getattr(udp_layer, "sport", 0) or 0)
                    dport = int(getattr(udp_layer, "dport", 0) or 0)
        except Exception:
            pass
        return sport, dport

    def _extract_udp_payload_bytes(self, packet, raw: Optional[bytes] = None) -> bytes:
        try:
            if UDP is not None and getattr(packet, "haslayer", None) and packet.haslayer(UDP):
                udp_layer = packet.getlayer(UDP)
                if udp_layer is not None and getattr(udp_layer, "payload", None) is not None:
                    data = bytes(udp_layer.payload)
                    if data:
                        return data[: self._control_payload_scan_limit]
        except Exception:
            pass

        try:
            if Raw is not None and getattr(packet, "haslayer", None) and packet.haslayer(Raw):
                rl = packet.getlayer(Raw)
                data = bytes(getattr(rl, "load", b"") or b"")
                if data:
                    return data[: self._control_payload_scan_limit]
        except Exception:
            pass

        blob = bytes(raw or b"")
        if not blob:
            return b""

        idx = blob.find(b'{"magic":"HVRM')
        if idx >= 0:
            return blob[idx: idx + self._control_payload_scan_limit]

        stripped = blob.strip(b"\x00\r\n\t ")
        return stripped[: self._control_payload_scan_limit]

    def _extract_hvrm_message(self, packet, raw: Optional[bytes] = None) -> Optional[Dict[str, Any]]:
        blob = self._extract_udp_payload_bytes(packet, raw)
        if not blob:
            return None

        candidates = [bytes(blob)]
        stripped = bytes(blob).strip(b"\x00\r\n\t ")
        if stripped and stripped != blob:
            candidates.append(stripped)

        for candidate in candidates:
            try:
                msg = json.loads(candidate.decode("utf-8", errors="ignore"))
                if isinstance(msg, dict):
                    return msg
            except Exception:
                pass

        try:
            text_blob = stripped.decode("utf-8", errors="ignore").lstrip("\ufeff\r\n\t \x00")
            decoder = json.JSONDecoder()
            msg, _ = decoder.raw_decode(text_blob)
            if isinstance(msg, dict):
                return msg
        except Exception:
            pass

        return None

    def _looks_like_hvrm_json(self, blob: bytes) -> bool:
        if not blob:
            return False

        preview = bytes(blob[: self._control_payload_scan_limit])

        if b'"magic":"HVRM' not in preview and b'"magic": "HVRM' not in preview:
            return False

        try:
            text_blob = preview.decode("utf-8", errors="ignore").lstrip("\ufeff\r\n\t \x00")
            decoder = json.JSONDecoder()
            msg, _ = decoder.raw_decode(text_blob)
            if not isinstance(msg, dict):
                return False

            magic = str(msg.get("magic") or "").strip()
            mtype = str(msg.get("type") or "").strip().lower()
            return magic in self.ACCEPT_MAGICS and mtype in self.HVRM_CONTROL_TYPES
        except Exception:
            pass

        return (
                b'"type":"hello"' in preview
                or b'"type":"hello_ack"' in preview
                or b'"type":"frame"' in preview
                or b'"type":"ack"' in preview
        )

    def _control_ports(self) -> Set[int]:
        return {
            int(self.discovery_port or 0),
            int(self.data_port or 0),
            int(self._bound_discovery_port or 0),
            int(self._bound_data_port or 0),
        }

    def _is_hvrm_control_packet(self, packet, raw: Optional[bytes] = None) -> bool:
        sport = 0
        dport = 0

        try:
            sport = int(getattr(packet, "sport", 0) or 0)
        except Exception:
            sport = 0
        try:
            dport = int(getattr(packet, "dport", 0) or 0)
        except Exception:
            dport = 0

        try:
            if UDP is not None and getattr(packet, "haslayer", None) and packet.haslayer(UDP):
                udp_layer = packet.getlayer(UDP)
                sport = int(getattr(udp_layer, "sport", sport) or sport)
                dport = int(getattr(udp_layer, "dport", dport) or dport)
        except Exception:
            pass

        payload = self._extract_udp_payload_bytes(packet, raw)
        if not payload:
            return False

        if not self._looks_like_hvrm_json(payload):
            return False

        ports = self._control_ports()
        if sport in ports or dport in ports:
            return True

        return True

    def _should_drop_wireshark_hvrm(self, packet, raw: bytes, inbound_iface: str) -> bool:
        if not self._is_wireshark_iface(inbound_iface):
            return False

        if not self._is_hvrm_control_packet(packet, raw):
            return False

        msg = self._extract_hvrm_message(packet, raw)
        if msg is None:
            self._log_sparse(
                "wireshark-hvrm-drop",
                "route",
                f"dropping HVRM control packet seen on WireShark iface={inbound_iface}",
                ["🧹", "🕵️", "📡"],
                every=3.0,
            )
            return True

        mtype = str(msg.get("type") or "").strip().lower()
        node_id = str(msg.get("node_id") or msg.get("src_node_id") or "").strip()
        listen_ip = str(msg.get("listen_ip") or msg.get("reply_to_ip") or "").strip()

        if mtype in self.HVRM_CONTROL_TYPES:
            self._log_sparse(
                f"wireshark-hvrm-drop:{mtype}",
                "route",
                f"dropping HVRM {mtype} from WireShark node={node_id or '-'} listen={listen_ip or '-'}",
                ["🧹", "🕵️", "📡"],
                every=3.0,
            )
            return True

        return False

    def _should_drop_sidecar_noise(self, packet, protocol_tag: str) -> bool:
        proto = str(protocol_tag or "").upper()

        if proto == "ARP":
            return True

        try:
            if ARP is not None and getattr(packet, "haslayer", None) and packet.haslayer(ARP):
                return True
        except Exception:
            pass

        if self._is_noisy_local_broadcast(packet):
            return True

        try:
            if self._is_broadcast_or_multicast_packet(packet):
                return True
        except Exception:
            pass

        sport, dport = self._packet_udp_ports(packet)
        if sport in self.LOCAL_NOISE_UDP_PORTS or dport in self.LOCAL_NOISE_UDP_PORTS:
            return True

        try:
            if self._is_hvrm_control_packet(packet):
                return True
        except Exception:
            pass

        return False

    def _requeue_router_ingress_item(self, item: _RouterIngressItem) -> bool:
        try:
            self._router_ingress_q.put_nowait(item)
            return True
        except queue.Full:
            self._stats["remote_ingress_queue_full"] = int(self._stats.get("remote_ingress_queue_full", 0)) + 1
            self._log_sparse(
                f"router-requeue-full:{item.src_node_id or '?'}",
                "frame",
                f"router ingress requeue full; dropping frame_id={item.frame_id} src_node={item.src_node_id}",
                ["⚠️", "📥", "🧯"],
                every=2.0,
            )
            return False

    def _enforce_pending_frame_cap_locked(self) -> None:
        if len(self._pending_frames) <= self._pending_frame_cap:
            return

        overflow = len(self._pending_frames) - self._pending_frame_cap
        items = sorted(
            self._pending_frames.items(),
            key=lambda kv: (
                float(kv[1].get("last_send_ts", 0.0) or 0.0),
                float(kv[1].get("created_ts", 0.0) or 0.0),
            ),
        )
        for frame_id, _info in items[: max(1, overflow)]:
            self._pending_frames.pop(frame_id, None)
            self._stats["pending_pruned"] = int(self._stats.get("pending_pruned", 0)) + 1

    def _is_valid_bind_ip(self, ip: str) -> bool:
        ip_s = str(ip or "").strip()
        if not self._is_usable_unicast_ipv4(ip_s):
            return False
        return ip_s != "127.0.0.1"

    def _is_broadcast_or_multicast_packet(self, packet) -> bool:
        try:
            ether = packet.getlayer(Ether) if Ether is not None and getattr(packet, "getlayer", None) else None
            if ether is not None:
                dst = str(getattr(ether, "dst", "") or "").lower()
                if dst == "ff:ff:ff:ff:ff:ff":
                    return True
                if dst.startswith("01:00:5e") or dst.startswith("33:33"):
                    return True
        except Exception:
            pass

        for attr in ("dst", "src"):
            try:
                ip = str(getattr(packet, attr, "") or "")
                if ip.endswith(".255"):
                    return True
                if ip.startswith("224.") or ip.startswith("239."):
                    return True
                if ip.lower().startswith("ff"):
                    return True
            except Exception:
                pass
        return False

    def _packet_tcp_ports(self, packet) -> Tuple[int, int]:
        try:
            if TCP is not None and getattr(packet, "haslayer", None) and packet.haslayer(TCP):
                layer = packet.getlayer(TCP)
                return int(getattr(layer, "sport", 0) or 0), int(getattr(layer, "dport", 0) or 0)
        except Exception:
            pass
        return 0, 0

    def _packet_endpoints(self, packet) -> Tuple[str, str]:
        try:
            if IP is not None and getattr(packet, "haslayer", None) and packet.haslayer(IP):
                layer = packet.getlayer(IP)
                return str(getattr(layer, "src", "") or ""), str(getattr(layer, "dst", "") or "")
        except Exception:
            pass
        try:
            if IPv6 is not None and getattr(packet, "haslayer", None) and packet.haslayer(IPv6):
                layer = packet.getlayer(IPv6)
                return str(getattr(layer, "src", "") or ""), str(getattr(layer, "dst", "") or "")
        except Exception:
            pass
        return "", ""

    def _flow_activity_key(self, packet, protocol_tag: str, iface_name: str) -> str:
        src_ip, dst_ip = self._packet_endpoints(packet)
        tcp_sport, tcp_dport = self._packet_tcp_ports(packet)
        udp_sport, udp_dport = self._packet_udp_ports(packet)
        sport = tcp_sport or udp_sport
        dport = tcp_dport or udp_dport
        return f"{iface_name}|{protocol_tag}|{src_ip}:{sport}|{dst_ip}:{dport}"

    def _track_flow_activity(self, packet, protocol_tag: str, iface_name: str, raw_len: int) -> Dict[str, float]:
        now = time.time()
        key = self._flow_activity_key(packet, protocol_tag, iface_name)
        info = self._flow_activity.get(key)
        if info is None or (now - float(info.get("window_start", 0.0) or 0.0)) > self._consumer_flow_window_sec:
            info = {"window_start": now, "packets": 0.0, "bytes": 0.0, "last_seen": now}
            self._flow_activity[key] = info
            self._flow_activity_order.append(key)
        info["packets"] = float(info.get("packets", 0.0) or 0.0) + 1.0
        info["bytes"] = float(info.get("bytes", 0.0) or 0.0) + float(raw_len)
        info["last_seen"] = now
        while len(self._flow_activity_order) > self._flow_activity_cap:
            old = self._flow_activity_order.popleft()
            if old != key:
                self._flow_activity.pop(old, None)
        return info

    def _is_tls_allowlisted(self, packet) -> bool:
        tcp_sport, tcp_dport = self._packet_tcp_ports(packet)
        if tcp_sport in self._tls_allowlist_ports or tcp_dport in self._tls_allowlist_ports:
            return True
        src_ip, dst_ip = self._packet_endpoints(packet)
        return src_ip in self._tls_allowlist_hosts or dst_ip in self._tls_allowlist_hosts

    def _general_traffic_drop_reason(self, packet, protocol_tag: str, raw: bytes, iface_name: str) -> str:
        if self._is_broadcast_or_multicast_packet(packet):
            return "broadcast_or_multicast"

        tcp_sport, tcp_dport = self._packet_tcp_ports(packet)
        udp_sport, udp_dport = self._packet_udp_ports(packet)

        allowed_udp_ports = {
            int(self.discovery_port),
            int(self.data_port),
            int(self._bound_discovery_port),
            int(self._bound_data_port),
            53,
            123,
            3333, 4444, 5555, 7777,
            18080, 18081, 18083,
            37888, 37889,
        }

        if str(protocol_tag or "").upper() == "UDP":
            if udp_sport == 443 or udp_dport == 443:
                return "quic"
            if udp_sport not in allowed_udp_ports and udp_dport not in allowed_udp_ports:
                return "udp_not_allowlisted"

        if tcp_sport == 443 or tcp_dport == 443:
            if not self._is_tls_allowlisted(packet):
                return "tls"

        if len(raw or b"") >= int(self._mirror_payload_soft_limit or 0):
            return "large_stream"

        flow_info = self._track_flow_activity(packet, str(protocol_tag or "RAW"), iface_name, len(raw or b""))
        if float(flow_info.get("bytes", 0.0) or 0.0) >= float(self._consumer_flow_bytes_per_window):
            return "consumer_rate"
        if float(flow_info.get("packets", 0.0) or 0.0) >= float(self._consumer_flow_packets_per_window):
            return "consumer_rate"

        return ""

    def _record_remote_ingress_queue_full(self, *, src_node_id: str, src_sender_id: str, protocol_tag: str,
                                          payload_len: int) -> None:
        now = time.time()
        window_start = now - float(self._remote_ingress_breaker_window_sec or 15.0)
        dq = self._remote_ingress_queue_full_events
        dq.append(now)
        while dq and dq[0] < window_start:
            dq.popleft()
        if len(dq) >= int(self._remote_ingress_breaker_threshold or 4):
            self._remote_ingress_breaker_open_until = max(
                self._remote_ingress_breaker_open_until,
                now + 20.0,
            )
        self._log_sparse(
            f"remote-ingress-full-breaker:{src_node_id or '?'}:{protocol_tag}",
            "frame",
            f"remote ingress pressure src_node={src_node_id or '-'} sender={src_sender_id or '-'} proto={protocol_tag} payload_len={payload_len} full_events={len(dq)} breaker_until={self._remote_ingress_breaker_open_until:.3f}",
            ["🚦", "📥", "🧯"],
            every=1.0,
        )

    def _is_remote_ingress_breaker_open(self) -> bool:
        return time.time() < float(getattr(self, "_remote_ingress_breaker_open_until", 0.0) or 0.0)

    def _log_evt(self, event: str, message: str, emojis: Optional[list[str]] = None) -> None:
        self._log(f"[{str(event or 'evt').upper()}] {message}", emojis)

    def _log(self, message: str, emojis: Optional[list[str]] = None) -> None:
        try:
            msg_cls = globals().get("RouterRandomMessages")
            if msg_cls is not None:
                self.router_logger.log_message(msg_cls("HyperVRouterManager", message, emojis or []))
                return
        except Exception:
            pass
        try:
            self.router_logger.log_message(message)
        except Exception:
            pass

    def _log_sparse(
            self,
            bucket: str,
            event: str,
            message: str,
            emojis: Optional[list[str]] = None,
            every: float = 5.0,
    ) -> None:
        now = time.time()
        last = float(self._log_throttle.get(bucket, 0.0))
        if (now - last) >= max(0.25, float(every)):
            self._log_throttle[bucket] = now
            self._log_evt(event, message, emojis or [])

    # ---------------------------------------------------------
    # extra helpers for wire reliability
    # ---------------------------------------------------------

    def _pack_payload_bytes(self, raw: bytes) -> Tuple[str, str, str]:
        payload = bytes(raw or b"")
        codec = "plain"
        payload_sha256 = hashlib.sha256(payload).hexdigest()
        compress_over = int(getattr(self, "_wire_payload_compress_over", 0) or 0)
        if compress_over > 0 and len(payload) >= compress_over:
            try:
                compressed = zlib.compress(payload, level=1)
                if len(compressed) + 24 < len(payload):
                    payload = compressed
                    codec = "zlib"
            except Exception:
                codec = "plain"
                payload = bytes(raw or b"")
        return base64.b64encode(payload).decode("ascii"), codec, payload_sha256

    def _unpack_payload_bytes(self, msg: Dict[str, Any]) -> Optional[bytes]:
        codec = str(msg.get("payload_codec") or msg.get("codec") or "plain").strip().lower()
        if codec not in {"plain", "zlib", "deflate", "gzip"}:
            return None

        payload: Optional[bytes] = None

        def _try_b64(val):
            if not isinstance(val, str) or not val:
                return None
            if len(val) > int(self._wire_message_max_bytes):
                return None
            try:
                return base64.b64decode(val.encode("ascii"), validate=True)
            except Exception:
                return None

        def _try_hex(val):
            if not isinstance(val, str) or not val:
                return None
            if len(val) > int(self._wire_payload_max_bytes) * 2:
                return None
            try:
                return bytes.fromhex(val)
            except Exception:
                return None

        for key in ("payload_b64", "payload_base64", "data_b64", "raw_b64", "frame_b64", "payload", "data"):
            payload = _try_b64(msg.get(key))
            if payload is not None:
                break
        if payload is None:
            for key in ("payload_hex", "raw_hex", "data_hex", "frame_hex"):
                payload = _try_hex(msg.get(key))
                if payload is not None:
                    break
        if payload is None:
            arr = msg.get("payload_bytes")
            if isinstance(arr, list) and len(arr) <= int(self._wire_payload_max_bytes):
                try:
                    payload = bytes(int(x) & 0xFF for x in arr)
                except Exception:
                    payload = None
        if payload is None:
            return None

        max_out = int(self._wire_payload_max_bytes)
        if codec in {"zlib", "deflate", "gzip"}:
            try:
                wbits = (zlib.MAX_WBITS | 16) if codec == "gzip" else zlib.MAX_WBITS
                dec = zlib.decompressobj(wbits)
                out = dec.decompress(payload, max_out + 1)
                if len(out) > max_out or dec.unconsumed_tail or not dec.eof:
                    return None
                payload = out
            except Exception:
                return None
        elif len(payload) > max_out:
            return None

        try:
            declared_len = int(msg.get("payload_len")) if msg.get("payload_len") is not None else len(payload)
        except Exception:
            return None
        if declared_len != len(payload) or declared_len < 0 or declared_len > max_out:
            return None

        want_sha = str(msg.get("payload_sha256") or msg.get("sha256") or "").strip().lower()
        if want_sha:
            if len(want_sha) != 64 or any(ch not in "0123456789abcdef" for ch in want_sha):
                return None
            if hashlib.sha256(payload).hexdigest() != want_sha:
                return None
        return payload

    def _derive_source_sender_id(self, inbound_iface: str) -> str:
        kind = self._infer_ingress_kind(inbound_iface)
        if kind == "wintun":
            return "wintun-local"
        if kind == "windivert":
            return "windivert-local"
        if kind == "hyperv":
            return str(inbound_iface or "hyperv-local")
        if kind == "wireshark":
            return "wireshark-local"
        return str(inbound_iface or "router")

    def _discovery_broadcast_targets(self) -> List[str]:
        targets: List[str] = []
        if self._send_global_broadcast:
            targets.append("255.255.255.255")
        if self._send_subnet_broadcast:
            for ip in self._ordered_local_transport_ips():
                if not self._is_private_ipv4(ip):
                    continue
                parts = self._ipv4_parts(ip)
                if parts:
                    targets.append(f"{parts[0]}.{parts[1]}.{parts[2]}.255")
        out: List[str] = []
        for target in targets:
            if target not in out:
                out.append(target)
        return out

    def _known_peer_direct_targets(self) -> List[Tuple[str, int]]:
        if not self._send_direct_hello:
            return []

        now = time.time()
        out: List[Tuple[str, int]] = []
        with self._lock:
            peers = list(self._peers.values())

        for peer in peers:
            if (now - peer.last_seen) > max(self.peer_timeout_sec, self._direct_hello_every_sec * 2.0):
                continue
            for ip, _ in self._candidate_peer_targets(peer):
                if not self._peer_transport_ip_allowed(peer, ip, discovery=True):
                    continue
                item = (ip, int(peer.discovery_port or self.discovery_port))
                if item not in out:
                    out.append(item)
        return out[: max(1, int(self._peer_target_limit or 1))]

    def _peer_last_seen(self, node_id: str) -> float:
        with self._lock:
            peer = self._peers.get(str(node_id))
            if peer is None:
                return 0.0
            return float(peer.last_seen or 0.0)

    def _choose_peer_ip(self, advertised_ip: str, hello_ip: str, data_ip: str, current_ip: str = "") -> str:
        candidates: List[str] = []
        for value in (data_ip, hello_ip, advertised_ip, current_ip):
            ip = self._sanitize_peer_ip(value)
            if ip and ip not in candidates:
                candidates.append(ip)
        if not candidates:
            return ""
        return max(candidates, key=self._local_path_affinity_score)

    def _same_ipv4_subnet(self, ip_a: str, ip_b: str) -> bool:
        a = self._ipv4_parts(ip_a)
        b = self._ipv4_parts(ip_b)
        return bool(a and b and a[:3] == b[:3])

    def _is_private_ipv4(self, ip: str) -> bool:
        parts = self._ipv4_parts(ip)
        if not parts:
            return False
        if parts[0] == 10:
            return True
        if parts[0] == 172 and 16 <= parts[1] <= 31:
            return True
        if parts[0] == 192 and parts[1] == 168:
            return True
        if parts[0] == 100 and 64 <= parts[1] <= 127:  # RFC 6598 CGNAT
            return True
        return False

    def _transport_ip_allowed(self, ip: str, *, discovery: bool) -> bool:
        ip_s = str(ip or "").strip()
        if discovery and ip_s == self.discovery_group:
            return True
        if ip_s == "255.255.255.255":
            return bool(self._send_global_broadcast)
        if not self._is_usable_unicast_ipv4(ip_s):
            return False
        if self._is_private_ipv4(ip_s):
            return True
        return bool(self._allow_public_discovery if discovery else self._allow_public_peer_data)

    def _peer_transport_ip_allowed(
            self,
            peer: Optional[_Peer],
            ip: str,
            *,
            discovery: bool,
    ) -> bool:
        ip_s = self._sanitize_peer_ip(ip)
        if not ip_s:
            return False
        if peer is not None and peer.segment_id != self.segment_id:
            return False

        observed_ips = set(getattr(peer, "observed_ips", set()) or set()) if peer is not None else set()
        if self._is_unobserved_local_alias(ip_s, ip_s if ip_s in observed_ips else "") and ip_s not in observed_ips:
            return False

        if self._transport_ip_allowed(ip_s, discovery=discovery):
            return True
        if peer is None:
            return False
        if self._is_private_ipv4(ip_s):
            return True

        known = ip_s in {
            peer.listen_ip,
            peer.advertised_ip,
            peer.last_hello_from_ip,
            peer.last_data_from_ip,
            peer.last_success_ip,
            getattr(peer, "last_observed_ip", ""),
            *peer.candidate_ips.keys(),
            *peer.public_ips,
            *observed_ips,
        }
        return bool(
            known
            and self._hybrid_allow_passthrough_public
            and (
                ip_s in observed_ips
                or peer.public_ok
                or peer.passthrough_enabled
                or getattr(peer, "same_address_mode", False)
                or ip_s in peer.public_ips
            )
        )

    def configure_wire_security(
            self,
            *,
            shared_secret: Optional[str] = None,
            server_key: Optional[str] = None,
            require_auth: bool = False,
            encrypt_payloads: bool = False,
            allow_public_peer_data: Optional[bool] = None,
            allow_public_discovery: Optional[bool] = None,
            allow_cross_subnet_private_hints: Optional[bool] = None,
            allow_same_segment_passthrough_public: Optional[bool] = None,
    ) -> None:
        secret_text = server_key if server_key is not None else shared_secret
        secret = str(secret_text or "").encode("utf-8")
        if require_auth and not secret:
            raise ValueError("require_auth=True requires a non-empty shared_secret")
        self._wire_shared_secret = secret
        self._wire_require_auth = bool(require_auth)
        self._wire_encrypt_payloads = bool(encrypt_payloads)
        self._wire_encryption_key = hashlib.sha256(secret).digest() if secret else b""
        if self._wire_encrypt_payloads and not self._wire_encryption_key:
            raise ValueError("encrypt_payloads=True requires shared_secret or server_key")
        if self._wire_encrypt_payloads:
            try:
                from cryptography.hazmat.primitives.ciphers.aead import AESGCM  # noqa: F401
            except Exception as exc:
                self._wire_encrypt_payloads = False
                raise RuntimeError("Encrypted peer packets require the cryptography package") from exc
        if allow_public_peer_data is not None:
            self._allow_public_peer_data = bool(allow_public_peer_data)
        if allow_public_discovery is not None:
            self._allow_public_discovery = bool(allow_public_discovery)
        if allow_cross_subnet_private_hints is not None:
            self._allow_cross_subnet_private_peer_hints = bool(allow_cross_subnet_private_hints)
        if allow_same_segment_passthrough_public is not None:
            self._hybrid_allow_passthrough_public = bool(allow_same_segment_passthrough_public)
        self._log_evt(
            "security",
            f"wire security configured auth={'required' if self._wire_require_auth else ('optional' if secret else 'off')} encryption={'aes-gcm' if self._wire_encrypt_payloads else 'off'} "
            f"public_data={int(self._allow_public_peer_data)} public_discovery={int(self._allow_public_discovery)} "
            f"same_segment_passthrough_public={int(self._hybrid_allow_passthrough_public)} "
            f"cross_subnet_private_hints={int(self._allow_cross_subnet_private_peer_hints)}",
            ["🛡️", "🔐", "🌐"],
        )

    def _bounded_text(self, value: Any, max_len: int) -> str:
        text = str(value or "").strip()
        if len(text) > int(max_len):
            return ""
        return text

    def _safe_port(self, value: Any, default: int = 0) -> int:
        try:
            port = int(value or 0)
        except Exception:
            port = 0
        if 1 <= port <= 65535:
            return port
        try:
            default_port = int(default or 0)
        except Exception:
            default_port = 0
        return default_port if 1 <= default_port <= 65535 else 0

    def _ipv4_parts(self, ip: Any) -> Optional[List[int]]:
        text = str(ip or "").strip()
        try:
            parts = [int(x) for x in text.split(".")]
        except Exception:
            return None
        if len(parts) != 4 or any(x < 0 or x > 255 for x in parts):
            return None
        return parts

    def _is_usable_unicast_ipv4(self, ip: Any) -> bool:
        parts = self._ipv4_parts(ip)
        if not parts:
            return False
        if parts[0] in {0, 127} or parts[0] >= 224:
            return False
        if parts[:2] == [169, 254] and not self._allow_link_local_transport:
            return False
        if parts == [255, 255, 255, 255]:
            return False
        if parts[-1] == 255 and self._same_ipv4_subnet(str(ip), self.bind_ip):
            return False
        return True

    def _sanitize_peer_ip(self, value: Any) -> str:
        text = str(value or "").strip()
        return text if self._is_usable_unicast_ipv4(text) else ""

    def _same_private_scope(self, ip_a: str, ip_b: str) -> bool:
        a = self._ipv4_parts(ip_a)
        b = self._ipv4_parts(ip_b)
        if not a or not b:
            return False
        if a[0] == b[0] == 10:
            return True
        if a[0] == b[0] == 172 and 16 <= a[1] <= 31 and 16 <= b[1] <= 31:
            return True
        if a[:2] == b[:2] == [192, 168]:
            return True
        if a[0] == b[0] == 100 and 64 <= a[1] <= 127 and 64 <= b[1] <= 127:
            return True
        return False

    def _is_link_local_ipv4(self, ip: Any) -> bool:
        parts = self._ipv4_parts(ip)
        return bool(parts and parts[:2] == [169, 254])

    def _is_probably_virtual_interface_name(self, iface_name: Any) -> bool:
        name = str(iface_name or "").strip().lower()
        if not name:
            return True
        virtual_tokens = (
            "vethernet", "hyper-v", "hyperv", "default switch", "wsl",
            "docker", "container", "vmware", "virtualbox", "loopback",
            "npcap", "windivert", "wintun", "wireguard", "zerotier",
            "tailscale", "protonvpn", "openvpn", "tap-windows", "tunnel",
        )
        return any(token in name for token in virtual_tokens)

    def _is_local_transport_ip(self, ip: Any) -> bool:
        ip_s = self._sanitize_peer_ip(ip)
        if not ip_s:
            return False
        with self._lock:
            local = set(self._local_transport_roles.keys())
            cfg = dict(self._ip_passthrough_config)
            for value in (
                    self.bind_ip,
                    self._primary_bind_ip,
                    cfg.get("public_ip"),
                    cfg.get("lan_ip"),
                    cfg.get("bind_ip"),
            ):
                candidate = self._sanitize_peer_ip(value)
                if candidate:
                    local.add(candidate)
        return ip_s in local

    def _is_unobserved_local_alias(self, candidate_ip: Any, observed_ip: Any = "") -> bool:
        candidate = self._sanitize_peer_ip(candidate_ip)
        observed = self._sanitize_peer_ip(observed_ip)
        if not candidate or not self._suppress_local_address_as_peer_hint:
            return False
        return bool(candidate != observed and self._is_local_transport_ip(candidate))

    def _advertised_fallback_plausible(
            self,
            observed_ip: str,
            advertised_ip: str,
            peer: Optional[_Peer] = None,
    ) -> bool:
        observed_ip = self._sanitize_peer_ip(observed_ip)
        advertised_ip = self._sanitize_peer_ip(advertised_ip)
        if not advertised_ip:
            return False
        if self._is_unobserved_local_alias(advertised_ip, observed_ip):
            return False
        if not self._peer_transport_ip_allowed(peer, advertised_ip, discovery=True):
            return False
        if advertised_ip == observed_ip or self._same_ipv4_subnet(advertised_ip, observed_ip):
            return True
        if peer is not None and advertised_ip in set(getattr(peer, "observed_ips", set()) or set()):
            return True
        if peer is not None and peer.public_ok and advertised_ip in peer.public_ips:
            return bool(self._hybrid_allow_passthrough_public)
        return bool(
            self._allow_cross_subnet_private_peer_hints
            and self._is_private_ipv4(advertised_ip)
            and (not observed_ip or self._is_private_ipv4(observed_ip))
        )

    def _record_peer_path_locked(
            self,
            peer: _Peer,
            ip: str,
            port: int,
            *,
            confirmed: bool,
            data_path: bool,
            observed: bool = False,
    ) -> None:
        ip = self._sanitize_peer_ip(ip)
        if not ip:
            return
        if not observed and self._is_unobserved_local_alias(ip, ""):
            return

        now = time.time()
        peer.candidate_ips[ip] = now
        stable_port = self._safe_port(port, peer.data_port or self.data_port)
        if data_path and stable_port:
            peer.candidate_data_ports[ip] = stable_port
        if confirmed:
            peer.confirmed_ips.add(ip)

        if observed:
            peer.observed_ips.add(ip)
            peer.last_observed_ip = ip
            peer.last_observed_port = stable_port
            if stable_port:
                peer.observed_data_ports[ip] = stable_port

        if self._is_private_ipv4(ip):
            peer.private_ips.add(ip)
            peer.address_roles.setdefault(ip, "observed-lan" if observed else "lan-private")
            if not peer.preferred_private_ip or observed or confirmed:
                peer.preferred_private_ip = ip
        else:
            peer.public_ips.add(ip)
            if observed:
                role = "observed-passthrough"
            elif peer.same_address_mode:
                role = "passthrough-lan-wan"
            else:
                role = "passthrough-public" if peer.public_ok or peer.passthrough_enabled else "public"
            peer.address_roles.setdefault(ip, role)

        if len(peer.candidate_ips) > 12:
            keep = sorted(
                peer.candidate_ips.items(),
                key=lambda kv: (
                    kv[0] in peer.observed_ips,
                    kv[0] in peer.confirmed_ips,
                    kv[1],
                ),
                reverse=True,
            )[:12]
            keep_ips = {candidate_ip for candidate_ip, _ in keep}
            peer.candidate_ips = dict(keep)
            peer.candidate_data_ports = {
                candidate_ip: p for candidate_ip, p in peer.candidate_data_ports.items()
                if candidate_ip in keep_ips
            }
            peer.confirmed_ips.intersection_update(keep_ips)
            peer.observed_ips.intersection_update(keep_ips)
            peer.observed_data_ports = {
                candidate_ip: p for candidate_ip, p in peer.observed_data_ports.items()
                if candidate_ip in keep_ips
            }
            peer.private_ips.intersection_update(keep_ips)
            peer.public_ips.intersection_update(keep_ips)
            peer.address_roles = {
                candidate_ip: role for candidate_ip, role in peer.address_roles.items()
                if candidate_ip in keep_ips
            }
            peer.path_successes = {
                candidate_ip: n for candidate_ip, n in peer.path_successes.items()
                if candidate_ip in keep_ips
            }
            peer.path_failures = {
                candidate_ip: n for candidate_ip, n in peer.path_failures.items()
                if candidate_ip in keep_ips
            }

    def _best_peer_ip_locked(self, peer: _Peer) -> str:
        targets = self._candidate_peer_targets(peer)
        return targets[0][0] if targets else ""

    def _peer_knows_ip(self, node_id: str, ip: str) -> bool:
        ip = self._sanitize_peer_ip(ip)
        if not node_id or not ip:
            return False
        with self._lock:
            peer = self._peers.get(str(node_id))
            if peer is None:
                return False
            return ip in {
                peer.listen_ip,
                peer.advertised_ip,
                peer.last_hello_from_ip,
                peer.last_data_from_ip,
                peer.last_success_ip,
                getattr(peer, "last_observed_ip", ""),
                *peer.candidate_ips.keys(),
                *peer.private_ips,
                *peer.public_ips,
                *getattr(peer, "observed_ips", set()),
            }

    def _wire_source_matches_peer(
            self,
            node_id: str,
            from_ip: str,
            from_port: int,
            mtype: str,
            msg: Dict[str, Any],
    ) -> bool:
        ip = self._sanitize_peer_ip(from_ip)
        if not ip:
            return False
        with self._lock:
            peer = self._peers.get(str(node_id))
            if peer is None:
                return bool(
                    not self._wire_require_known_peer_for_data
                    and self._transport_ip_allowed(ip, discovery=False)
                )

            # ACKs may return through a translated public/private path that is
            # different from the path used for discovery. A matching random
            # frame_id plus matching peer node is sufficient to accept the ACK;
            # wire authentication, when configured, was already verified.
            if mtype == "ack":
                frame_id = self._bounded_text(
                    msg.get("frame_id") or msg.get("id") or msg.get("ref"), 128
                )
                with self._pending_lock:
                    pending = self._pending_frames.get(frame_id)
                    if (
                            pending is not None
                            and str(pending.get("peer_node_id") or "") == str(node_id)
                            and self._is_usable_unicast_ipv4(ip)
                    ):
                        return True

            if not self._peer_transport_ip_allowed(peer, ip, discovery=False):
                return False
            known_ips = {
                peer.listen_ip,
                peer.advertised_ip,
                peer.last_hello_from_ip,
                peer.last_data_from_ip,
                peer.last_success_ip,
                getattr(peer, "last_observed_ip", ""),
                *peer.candidate_ips.keys(),
                *peer.private_ips,
                *peer.public_ips,
                *getattr(peer, "observed_ips", set()),
            }
            if ip in known_ips:
                return True
            if self._allow_peer_ip_migration and self._is_private_ipv4(ip):
                for known in known_ips:
                    if known and self._is_private_ipv4(known) and (
                        self._same_ipv4_subnet(ip, known) or self._same_private_scope(ip, known)
                    ):
                        return True
        return False

    def _wire_rate_allowed(self, from_ip: str, mtype: str) -> bool:
        now = time.monotonic()
        key = f"{from_ip}|{mtype}"
        limit = self._wire_frames_per_sec if mtype == "frame" else self._wire_control_per_sec
        bucket = self._wire_rx_rate.get(key)
        if not isinstance(bucket, dict) or (now - float(bucket.get("start", 0.0))) >= 1.0:
            self._wire_rx_rate[key] = {"start": now, "count": 1.0}
            return True
        count = int(bucket.get("count", 0.0)) + 1
        bucket["count"] = float(count)
        if len(self._wire_rx_rate) > self._wire_rx_rate_cap:
            stale = sorted(self._wire_rx_rate.items(), key=lambda kv: float(kv[1].get("start", 0.0)))
            for stale_key, _ in stale[: len(stale) - self._wire_rx_rate_cap]:
                self._wire_rx_rate.pop(stale_key, None)
        return count <= int(limit)

    def _wire_message_mac(self, msg: Dict[str, Any]) -> str:
        if not self._wire_shared_secret:
            return ""
        unsigned = {k: v for k, v in msg.items() if k not in {"auth", "auth_v"}}
        canonical = json.dumps(unsigned, separators=(",", ":"), ensure_ascii=False, sort_keys=True).encode("utf-8")
        return hashlib.blake2s(canonical, key=self._wire_shared_secret, digest_size=16).hexdigest()

    def _constant_time_text_equal(self, left: str, right: str) -> bool:
        a = str(left or "").encode("ascii", errors="ignore")
        b = str(right or "").encode("ascii", errors="ignore")
        if len(a) != len(b):
            return False
        diff = 0
        for x, y in zip(a, b):
            diff |= x ^ y
        return diff == 0

    def _encode_wire_message(self, msg: Dict[str, Any]) -> bytes:
        out = dict(msg)
        if self._wire_shared_secret:
            out["auth_v"] = 1
            out["auth"] = self._wire_message_mac(out)
        raw = json.dumps(out, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        if self._wire_encrypt_payloads:
            from cryptography.hazmat.primitives.ciphers.aead import AESGCM
            nonce = os.urandom(12)
            ciphertext = AESGCM(self._wire_encryption_key).encrypt(nonce, raw, self.segment_id.encode("utf-8"))
            envelope = {
                "enc_v": 1,
                "segment_id": self.segment_id,
                "nonce": base64.b64encode(nonce).decode("ascii"),
                "ciphertext": base64.b64encode(ciphertext).decode("ascii"),
            }
            raw = json.dumps(envelope, separators=(",", ":")).encode("utf-8")
        if len(raw) > int(self._wire_message_max_bytes):
            raise ValueError(f"wire message too large: {len(raw)} bytes")
        return raw

    def _verify_wire_message_auth(self, msg: Dict[str, Any]) -> bool:
        supplied = str(msg.get("auth") or "").strip().lower()
        if not self._wire_shared_secret:
            return not self._wire_require_auth
        if not supplied:
            return not self._wire_require_auth
        expected = self._wire_message_mac(msg)
        return self._constant_time_text_equal(supplied, expected)

    def _note_peer_path_failure(self, node_id: str, ip: str) -> None:
        ip = self._sanitize_peer_ip(ip)
        if not node_id or not ip:
            return
        with self._lock:
            peer = self._peers.get(str(node_id))
            if peer is None:
                return
            peer.path_failures[ip] = int(peer.path_failures.get(ip, 0) or 0) + 1
            if peer.path_failures[ip] >= 3 and ip not in peer.confirmed_ips:
                peer.candidate_ips.pop(ip, None)
                peer.candidate_data_ports.pop(ip, None)
            peer.listen_ip = self._best_peer_ip_locked(peer)

